import std.collection.HashMap
import std.time.DateTime

class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request.get("path") ?? None<String>()
        let method = request.get("method") ?? None<String>()

        if (path == None<String>()) {
            return false
        }

        // Allow options requests to any path
        if (method == Some<String>("OPTIONS")) {
            return true
        }

        // Allow GET requests to root
        if (method == Some<String>("GET") && path == Some<String>("/")) {
            return true
        }

        // Check if path starts with allowed prefixes
        let is_allowed_path = this.is_start_with(path.getOrThrow())

        if (!is_allowed_path) {
            return false
        }

        // Check authorization for protected paths
        if (method != Some<String>("OPTIONS")) {
            let user = this.get_jwt_user(request)
            if (user == None<HashMap<String, Any>>()) {
                return false
            }
        }

        return true
    }

    public func is_start_with(request_uri: String): Bool {
        let prefixes = ["/api", "/login"]

        for (prefix in prefixes) {
            if (request_uri.startsWith(prefix)) {
                return true
            }
        }

        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers = request.get("headers") ?? None<HashMap<String, Any>>()
        if (headers == None<HashMap<String, Any>>()) {
            return None<HashMap<String, Any>>()
        }

        let auth_header = headers.getOrThrow().get("Authorization") ?? None<HashMap<String, Any>>()
        if (auth_header == None<HashMap<String, Any>>()) {
            return None<HashMap<String, Any>>()
        }

        let auth_data = auth_header.getOrThrow()
        let jwt = auth_data.get("jwt") ?? None<String>()
        if (jwt == None<String>()) {
            return None<HashMap<String, Any>>()
        }

        // Simple JWT token validation (in a real implementation, you'd verify the signature)
        // For this example, we just check if the token exists and contains current date
        let current_date = DateTime.now().format("yyyy-MM-dd")
        let token_valid = jwt.getOrThrow().contains(current_date)

        if (!token_valid) {
            return None<HashMap<String, Any>>()
        }

        let user = auth_data.get("user") ?? None<HashMap<String, Any>>()
        return user
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        // In a real implementation, you would:
        // 1. Store the user info in thread-local storage or request context
        // 2. Log the access with timestamp, user info, etc.

        // Here we just demonstrate the structure with a simple print
        let name = user.get("name") ?? None<String>()
        let address = user.get("address") ?? None<String>()

        println("Access logged for user ${name.getOrElse("unknown")} from ${address.getOrElse("unknown")}")
    }
}

