class AccessGatewayFilter {
    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        let path = request["path"] ?? ""
        let method = request["method"] ?? ""

        // Allow login requests
        if (path.toRuneArray() == ["/", "l", "o", "g", "i", "n"].toRuneArray() && 
            method.toRuneArray() == ["P", "O", "S", "T"].toRuneArray()) {
            return true
        }

        // Check if path starts with allowed prefixes
        if (this.is_start_with(request_uri: path.toString())) {
            let user_opt = this.get_jwt_user(request: request)
            if (user_opt != None<HashMap<String, Any>>) {
                this.set_current_user_info_and_log(user: user_opt.getOrThrow())
                return true
            }
        }

        return false
    }

    public func is_start_with(request_uri: String): Bool {
        let prefixes = [
            "/api".toRuneArray(),
            "/login".toRuneArray()
        ]

        let uri = request_uri.toRuneArray()
        for (i in 0..<prefixes.size) {
            let prefix = prefixes[i]
            if (uri.size >= prefix.size) {
                let matches = { j in 
                    if (j >= prefix.size) { 
                        return true 
                    }
                    return uri[j] == prefix[j]
                }

                var all_match = true
                for (j in 0..<prefix.size) {
                    if (!matches(j)) {
                        all_match = false
                        break
                    }
                }

                if (all_match) {
                    return true
                }
            }
        }

        return false
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        let headers_opt = request["headers"] as? HashMap<String, Any>
        if (headers_opt == None<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>
        }

        let headers = headers_opt.getOrThrow()
        let auth_opt = headers["Authorization"] as? HashMap<String, Any>
        if (auth_opt == None<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>
        }

        let auth = auth_opt.getOrThrow()
        let user_opt = auth["user"] as? HashMap<String, Any>
        if (user_opt == None<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>
        }

        return Some<HashMap<String, Any>>(user_opt.getOrThrow())
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        // In a real implementation, this would:
        // 1. Store current user (e.g., in thread-local storage)
        // 2. Log access information
        // For now, we'll just print the user info
        let mut output = "Access logged for user: {\n"
        for (i in 0..<user.size) {
            let (key, val) = user.pairAt(i)
            output += "  ${key}: ${val.toString()}"
            if (i < user.size - 1) {
                output += ",\n"
            }
        }
        output += "\n}"
        println(output)
    }
}

