import std.collection.HashMap
import std.collection.*
import std.time.DateTime

class AccessGatewayFilter {
    /*
    This class is a filter used for accessing gateway filtering, primarily for authentication and access log recording.
    */

    public init() {
    }

    public func filter(request: HashMap<String, Any>): Bool {
        /*
        Filter the incoming request based on certain rules and conditions.
        */
        let path = request.get("path") ?? ""
        let method = request.get("method") ?? ""

        // Allow all POST requests to /login
        if (method == "POST" && this.is_start_with(request_uri: path)) {
            return true
        }

        // Check JWT for other paths
        if (this.is_start_with(request_uri: path)) {
            let user_opt = this.get_jwt_user(request: request)
            return user_opt is Some<HashMap<String, Any>>
        }

        return false
    }

    public func is_start_with(request_uri: String): Bool {
        /*
        Check if the request URI starts with certain prefixes.
        */
        return request_uri.startsWith("/api") || request_uri.startsWith("/login")
    }

    public func get_jwt_user(request: HashMap<String, Any>): Option<HashMap<String, Any>> {
        /*
        Get the user information from the JWT token in the request.
        */
        let headers_opt = request.get("headers")
        if (headers_opt !is Some<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>()
        }

        let headers = (headers_opt as Some<HashMap<String, Any>>).getOrThrow()
        let auth_opt = headers.get("Authorization")
        if (auth_opt !is Some<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>()
        }

        let auth = (auth_opt as Some<HashMap<String, Any>>).getOrThrow()
        let user_opt = auth.get("user")
        if (user_opt !is Some<HashMap<String, Any>>) {
            return None<HashMap<String, Any>>()
        }

        return Some<HashMap<String, Any>>(user_opt as Some<HashMap<String, Any>>).getOrThrow()
    }

    public func set_current_user_info_and_log(user: HashMap<String, Any>): Unit {
        /*
        Set the current user information and log the access.
        */
        println("User accessed: ${user.get("name") ?? "unknown"} from ${user.get("address") ?? "unknown"} at ${DateTime.now().format("yyyy-MM-dd HH:mm:ss")}")
    }
}

