import std.collection.*
import std.reflect.*
import std.convert.*
import std.io.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let args_list = command_string.split(' ')
        if (args_list[0] == "python" && args_list[1] == "script.py") {
            args_list = args_list.slice(2, args_list.size)
        } else {
            return (false, None<HashSet<String>>())
        }

        var i = 0
        var missing_args = HashSet<String>()

        while (i < args_list.size) {
            let arg = args_list[i]
            if (arg.startsWith("--")) {
                // Long option format (--arg=value or --arg value)
                let pair = arg.split('=', max_splits: 1)
                let key = pair[0].slice(2, pair[0].size)
                let value = if (pair.size == 2) { pair[1] } else { "" }

                if (this.types.contains(key)) {
                    let converted = this.convert_type(key, if (value.isEmpty) { 
                        // Try to find next argument as value if no = was provided
                        if (i + 1 < args_list.size) {
                            i += 1
                            args_list[i]
                        } else {
                            missing_args.add(key)
                            continue
                        }
                    } else { value })
                    this.arguments.add(key, converted)
                } else {
                    // Boolean flag case for options
                    if (value.isEmpty) {
                        this.arguments.add(key, true)
                    } else {
                        this.arguments.add(key, value)
                    }
                }
            } else if (arg.startsWith("-")) {
                // Short option format (-arg value)
                let key = arg.slice(1, arg.size)
                if (i + 1 < args_list.size) {
                    i += 1
                    let value = args_list[i]
                    if (this.types.contains(key)) {
                        let converted = this.convert_type(key, value)
                        this.arguments.add(key, converted)
                    } else {
                        this.arguments.add(key, value)
                    }
                } else {
                    // Boolean flag
                    this.arguments.add(key, true)
                }
            }
            i += 1
        }

        // Check required arguments
        for (key in this.required) {
            if (!this.arguments.contains(key)) {
                missing_args.add(key)
            }
        }

        if (missing_args.size > 0) {
            return (false, Some<HashSet<String>>(missing_args))
        }
        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        return this.arguments.get(key) ?? None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        this.required.add(arg)
        this.types.add(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        let target_type = this.types.get(arg) ?? TypeInfo.of<String>()

        return match (target_type) {
            case TypeInfo.of<Int64>() => value.toInt64() ?? value
            case TypeInfo.of<Bool>() => value == "true"
            case TypeInfo.of<Float64>() => value.toFloat64() ?? value
            case TypeInfo.of<Int32>() => value.toInt32() ?? value
            case _ => value
        }
    }
}

