class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ")
        var i = 0
        var missing_args = HashSet<String>()
        var parsed = true

        // Skip "python script.py" prefix if exists
        if (parts.size > 2 && parts[0] == "python" && parts[1] == "script.py") {
            i = 2
        }

        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                let kv = part.substring(2).split("=")
                if (kv.size == 2) {
                    let key = kv[0]
                    let value = kv[1]
                    if (types.contains(key)) {
                        arguments[key] = convert_type(key, value)
                    } else {
                        arguments[key] = value
                    }
                } else {
                    // Boolean flag case
                    let key = part.substring(2)
                    arguments[key] = true
                }
                i += 1
            } else if (part.startsWith("-")) {
                let key = part.substring(1)
                if (i + 1 < parts.size) {
                    let value = parts[i + 1]
                    if (types.contains(key)) {
                        arguments[key] = convert_type(key, value)
                    } else {
                        arguments[key] = value
                    }
                    i += 2
                } else {
                    // Boolean flag case
                    arguments[key] = true
                    i += 1
                }
            } else {
                i += 1
            }
        }

        // Check required arguments
        for (key in required) {
            if (!arguments.contains(key)) {
                missing_args.add(key)
            }
        }

        parsed = missing_args.size == 0
        let result = if (parsed) { 
            (true, None<HashSet<String>>()) 
        } else { 
            (false, Some<HashSet<String>>(missing_args)) 
        }
        return result
    }

    public func get_argument(key: String): Any {
        return arguments.get(key).getOrThrow()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            this.required.add(arg)
        }
        types[arg] = arg_type
    }

    public func convert_type(arg: String, value: String): Any {
        if (types.contains(arg)) {
            let t = types[arg]
            return match (t) {
                case TypeInfo.of<Int64>() => value.toInt64().getOrThrow()
                case TypeInfo.of<Float64>() => value.toFloat64().getOrThrow()
                case TypeInfo.of<Bool>() => 
                    if (value.toLowerCase() == "true") { true } 
                    else { false }
                case _ => value // fallback to String if type not matched
            }
        }
        return value
    }
}

import std.collection.*
import std.reflect.*
import std.convert.*
import std.string.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let args = command_string.split(" ")
        if (args.size < 3 || args[0] != "python" || args[1] != "script.py") {
            return (false, Some<HashSet<String>>(HashSet<String>())) // Simplified error handling
        }

        var i = 2
        let missing = HashSet<String>()

        while (i < args.size) {
            let arg = args[i]
            if (arg.startsWith("--")) {
                let keyValue = arg.substring(2).split("=")
                let key = keyValue[0]
                let value = keyValue.size > 1 ? keyValue[1] : ""

                if (types.contains(key)) {
                    let converted = convert_type(key, value)
                    arguments.add(key, converted)
                } else {
                    arguments.add(key, value)
                }
                i += 1
            } else if (arg.startsWith("-")) {
                let flag = arg.substring(1)
                arguments.add(flag, true)
                i += 1
            } else {
                // positional argument handling (simplified)
                // In real implementation we'd need to track current argument being filled
                if (arguments.size > 0) {
                    let lastKey = ArrayList(arguments.keys())[arguments.size - 1]
                    if (types.contains(lastKey)) {
                        let converted = convert_type(lastKey, args[i])
                        arguments.add(lastKey, converted)
                    } else {
                        arguments.add(lastKey, args[i])
                    }
                }
                i += 1
            }
        }

        // Check for missing required args
        for (key in required) {
            if (!arguments.contains(key)) {
                missing.add(key)
            }
        }

        if (missing.size > 0) {
            return (false, Some<HashSet<String>>(missing))
        }
        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        return arguments.get(key) ?? "None" // Simplified - would normally be Option<Any>
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            self.required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        let typeInfo = types.get(arg)
        if (typeInfo != None<TypeInfo>()) {
            let t = typeInfo.getOrThrow()
            match (t.typeName()) {
                case "Int64" => return value.toInt64() ?? value
                case "Bool" => return if (value.toLower() == "true") { true } else { false }
                case "Float64" => return value.toFloat64() ?? value
                case _ => return value
            }
        }
        return value
    }
}

