class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ")
        var i = 0
        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--") || part.startsWith("-")) {
                let arg_name_part = part.substring(if (part.startsWith("--")) { 2 } else { 1 })
                let equals_pos = arg_name_part.indexOf("=")
                var arg_name: String
                var value: Option<String> = None<String>()

                if (equals_pos != -1) {
                    arg_name = arg_name_part.substring(0, equals_pos)
                    let raw_value = arg_name_part.substring(equals_pos + 1)
                    if (raw_value != "") {
                        value = Some<String>(raw_value)
                    }
                } else {
                    arg_name = arg_name_part
                }

                if (value == None<String>()) {
                    i += 1
                    if (i < parts.size) {
                        value = Some<String>(parts[i])
                    } else {
                        value = Some<String>("true") // treat flag without value as true
                    }
                }

                let converted_value = if (types.contains(arg_name)) {
                    convert_type(arg_name, value.getOrThrow())
                } else {
                    if (value.getOrThrow() == "true") {
                        true
                    } else if (value.getOrThrow() == "false") {
                        false
                    } else {
                        value.getOrThrow()
                    }
                }

                arguments.add(arg_name, converted_value)
            }
            i += 1
        }

        let missing_args = HashSet<String>()
        for (arg in required) {
            if (!arguments.contains(arg)) {
                missing_args.add(arg)
            }
        }

        if (missing_args.size > 0) {
            return (false, Some<HashSet<String>>(missing_args))
        } else {
            return (true, None<HashSet<String>>())
        }
    }

    public func get_argument(key: String): Any {
        return arguments[key] ?? None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            this.required.add(arg)
        }
        this.types.add(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        let target_type = types[arg] ?? TypeInfo.of<String>()
        let converted = match (target_type) {
            case TypeInfo.of<Int64>()  => Some<Int64>(toInt64(value))
            case TypeInfo.of<Int32>()  => Some<Int32>(toInt32(value))
            case TypeInfo.of<Int16>()  => Some<Int16>(toInt16(value))
            case TypeInfo.of<Int8>()   => Some<Int8>(toInt8(value))
            case TypeInfo.of<UInt64>() => Some<UInt64>(toUInt64(value))
            case TypeInfo.of<UInt32>() => Some<UInt32>(toUInt32(value))
            case TypeInfo.of<UInt16>() => Some<UInt16>(toUInt16(value))
            case TypeInfo.of<UInt8>()  => Some<UInt8>(toUInt8(value))
            case TypeInfo.of<Float64>()=> Some<Float64>(toFloat64(value))
            case TypeInfo.of<Float32>()=> Some<Float32>(toFloat32(value))
            case TypeInfo.of<Bool>()   => Some<Bool>(value == "true")
            case _ => None<Any>()
        }

        return converted ?? value
    }
}

