class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.splitter(' ').filter({it != "" && it != "script.py"})
        var i = 0
        var missing_args = HashSet<String>()
        var parsedOk = true

        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                let equal_index = part.indexOf('=')
                let (key, value) = if (equal_index != -1) {
                    (part.substring(2, equal_index), part.substring(equal_index + 1))
                } else {
                    (part.substring(2), "true") // boolean flag
                }
                if (this.types.contains(key)) {
                    let converted = this.convert_type(key, value)
                    this.arguments.add(key, converted)
                } else {
                    this.arguments.add(key, value)
                }
            } else if (part.startsWith("-")) {
                let next = if (i + 1 < parts.size) parts[i + 1] else ""
                let key = part.substring(1)
                if (!next.startsWith("-")) {
                    if (this.types.contains(key)) {
                        let converted = this.convert_type(key, next)
                        this.arguments.add(key, converted)
                        i += 1
                    } else {
                        this.arguments.add(key, next)
                        i += 1
                    }
                } else {
                    this.arguments.add(key, "true") // boolean flag without value
                }
            }
            i += 1
        }

        // Check required args
        for (req in this.required) {
            if (!this.arguments.contains(req)) {
                missing_args.add(req)
                parsedOk = false
            }
        }

        return if (parsedOk) {
            (true, None<HashSet<String>>())
        } else {
            (false, Some<HashSet<String>>(missing_args))
        }
    }

    public func get_argument(key: String): Any {
        return if (this.arguments.contains(key)) {
            this.arguments[key] ?? "" // Should technically never be None here
        } else {
            None<Any>() // Cangjie doesn't have proper Option<Any> return yet, but per spec we return "None if doesn't exist"
            // Note: This could be enhanced with proper union types in future
        }
        // Alternative strict implementation (preferring to throw or return Option):
        // return this.arguments[key] ?? None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            this.required.add(arg)
        }
        this.types.add(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        let target_type = this.types[arg] ?? TypeInfo.of<String>()
        return match (target_type) {
            case TypeInfo.of<Int64>() => value.toInt64() ?? value // fallback to string if conversion fails
            case TypeInfo.of<Int32>() => value.toInt32() ?? value
            case TypeInfo.of<Float64>() => value.toFloat64() ?? value
            case TypeInfo.of<Bool>() => value == "true" // simple bool conversion
            case _ => value // default case (String)
        }
    }
}

