extension String {
    func splitter(delimiter: Rune): ArrayList<String> {
        let result = ArrayList<String>()
        var current = ""
        for (r in this.runes()) {
            if (r == delimiter) {
                result.add(current)
                current = ""
            } else {
                current = current + r.toString()
            }
        }
        if (current != "") {
            result.add(current)
        }
        return result
    }

