        let parts = command_string.split(" ")
        var i = 0
        var missing_args = HashSet<String>()

        while (i < parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                let key_value = part[2..].split("=")
                let key = key_value[0]

                if (key_value.size == 2) {
                    let raw_value = key_value[1]
                    let converted_value = convert_type(key, raw_value)
                    arguments.add(key, converted_value)
                } else {
                    // Boolean flag case
                    arguments.add(key, true)
                }
            } else if (part.startsWith("-")) {
                let key = part[1..]
                i = i + 1
                if (i >= parts.size) {
                    missing_args.add(key)
                    break
                }
                let value = parts[i]
                let converted_value = convert_type(key, value)
                arguments.add(key, converted_value)
            }
            i = i + 1
        }

        // Check for missing required arguments
        for (arg in required) {
            if (!arguments.contains(arg)) {
                missing_args.add(arg)
            }
        }

        if (missing_args.size > 0) {
            return (false, Some<HashSet<String>>(missing_args))
        } else {
            return (true, None<HashSet<String>>())
        }
    }

    public func get_argument(key: String): Option<Any> {
        return arguments.get(key)
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        types.add(arg, arg_type)
        if (required) {
            this.required.add(arg)
        }
    }

    public func convert_type(arg: String, value: String): Any {
        let type_info = types.get(arg).getOrThrow()
        return match (type_info) {
            case TypeInfo.of<Int64>() => toInt64(value).getOrThrow()
            case TypeInfo.of<Bool>() => 
                if (value == "true") { true } 
                else if (value == "false") { false } 
                else { throw "Invalid boolean value" }
            case TypeInfo.of<String>() => value
            case _ => throw "Unsupported type conversion"
        }
    }
}

