import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ")
        let args_with_values: ArrayList<(String, Option<String>)> = ArrayList<(String, Option<String>)>()

        // Skip "python" and script name
        if (parts.size < 3) {
            return (false, Some<HashSet<String>>(HashSet<String>([])))
        }

        for (i in 2..parts.size) {
            let part = parts[i]
            if (part.startsWith("--")) {
                let key_value = part[2..].split("=")
                if (key_value.size == 1) {
                    args_with_values.add((key_value[0], None<String>()))
                } else {
                    args_with_values.add((key_value[0], Some<String>(key_value[1..].join("="))))
                }
            } else if (part.startsWith("-")) {
                // Handle single dash flags (no values)
                let flags = part[1..].toRuneArray().map { r => String.fromRune(r) }
                for (flag in flags) {
                    args_with_values.add((flag, None<String>()))
                }
            }
        }

        let missing_args = HashSet<String>()
        for (arg_info in args_with_values) {
            let (key, may_value) = arg_info

            if (required.contains(key) && !may_value.hasValue()) {
                missing_args.add(key)
                continue
            }

            match (may_value) {
                case Some(value) => {
                    if (types.contains(key)) {
                        let converted = convert_type(key, value)
                        arguments.add(key, converted)
                    } else {
                        arguments.add(key, value)
                    }
                }
                case None => {
                    arguments.add(key, true) // Flags are true if present
                }
            }
        }

        if (missing_args.size > 0) {
            return (false, Some<HashSet<String>>(missing_args))
        }
        return (true, None<HashSet<String>>())
    }

    public func get_argument(key: String): Any {
        return arguments[key] ?? None<Any>()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            self.required.add(arg)
        }
        self.types.add(arg, arg_type)
    }

    public func convert_type(arg: String, value: String): Any {
        let info = types[arg]
        match (info) {
            case Some(TypeInfo.Int64) => Int64.fromString(value)
            case Some(TypeInfo.Int32) => Int32.fromString(value)
            case Some(TypeInfo.Float64) => Float64.fromString(value)
            case Some(TypeInfo.Bool) => value.toLower() == "true" ? true : false
            case _ => value // Default to String if no type info or unknown type
        }
    }
}

import std.collection.ArrayList

class ArrangementCalculator {
    let datas: ArrayList<Int64>

    public init(datas: ArrayList<Int64>) {
        this.datas = datas
    }

    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let actual_m = m ?? n
        if (actual_m > n || n < 0 || actual_m < 0) {
            return 0
        }
        return factorial(n: n) / factorial(n: n - actual_m)
    }

    public static func count_all(n: Int64): Int64 {
        var sum: Int64 = 0
        for (i in 1..(n + 1)) {
            sum += ArrangementCalculator.count(n: n, m: Some<Int64>(i))
        }
        return sum
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let actual_m = m ?? datas.size
        if (actual_m > datas.size || actual_m < 0 || datas.size < 0) {
            return ArrayList<ArrayList<Int64>>()
        }

        let result = ArrayList<ArrayList<Int64>>()
        let remaining = ArrayList<Int64>(datas)
        select_permutations(ArrayList<Int64>(), remaining, actual_m, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (i in 1..(datas.size + 1)) {
            let permutations = select(Some<Int64>(i))
            for (j in 0..permutations.size) {
                result.add(permutations[j])
            }
        }
        return result
    }

    public static func factorial(n: Int64): Int64 {
        if (n <= 1) {
            return 1
        }
        return n * factorial(n: n - 1)
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m, result)
        }
    }
}

