    public static func count(n: Int64, m: Option<Int64>): Int64 {
        let m_val = m ?? n
        if (m_val <= 0 || n < m_val) {
            return 0
        }
        return factorial(n) / factorial(n - m_val)
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..n + 1) {
            total += factorial(n) / factorial(n - i)
        }
        return total
    }

    public func select(m: Option<Int64>): ArrayList<ArrayList<Int64>> {
        let m_val = m ?? datas.size
        let result = ArrayList<ArrayList<Int64>>()
        if (m_val <= 0 || datas.size < m_val) {
            return result
        }
        for (i in 0..datas.size) {
            let new_prefix = ArrayList<Int64>([datas[i]])
            let new_remaining = ArrayList<Int64>(datas)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m_val - 1, result)
        }
        return sort_select_results(result)
    }

    public func select_all(): ArrayList<ArrayList<Int64>> {
        let result = ArrayList<ArrayList<Int64>>()
        for (m in 1..datas.size + 1) {
            for (i in 0..datas.size) {
                let new_prefix = ArrayList<Int64>([datas[i]])
                let new_remaining = ArrayList<Int64>(datas)
                new_remaining.remove(at: i)
                select_permutations_all(m - 1, new_prefix, new_remaining, result)
            }
        }
        return sort_select_results(result)
    }

    public static func factorial(n: Int64): Int64 {
        var result: Int64 = 1
        if (n <= 1) {
            return 1
        }
        for (i in 2..n + 1) {
            result *= i
        }
        return result
    }

    private func select_permutations(prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, m: Int64, result: ArrayList<ArrayList<Int64>>): Unit {
        if (m == 0) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations(new_prefix, new_remaining, m - 1, result)
        }
    }

    private func select_permutations_all(m: Int64, prefix: ArrayList<Int64>, remaining: ArrayList<Int64>, result: ArrayList<ArrayList<Int64>>): Unit {
        if (prefix.size == m + 1) {
            result.add(ArrayList<Int64>(prefix))
            return
        }
        for (i in 0..remaining.size) {
            let new_prefix = ArrayList<Int64>(prefix)
            new_prefix.add(remaining[i])
            let new_remaining = ArrayList<Int64>(remaining)
            new_remaining.remove(at: i)
            select_permutations_all(m, new_prefix, new_remaining, result)
        }
    }

    private func sort_select_results(results: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Int64>> {
        let sorted_results = ArrayList<ArrayList<Int64>>()
        let key_func = {arr: ArrayList<Int64> => arr.toRuneArray()} // Simplified for permutation sorting
        for (arr in results) {
            let sorted_arr = ArrayList<Int64>(arr)
            // Simple bubble sort for demonstration (in practice use proper sorting)
            for (i in 0..sorted_arr.size) {
                for (j in i + 1..sorted_arr.size) {
                    if (sorted_arr[i] > sorted_arr[j]) {
                        let temp = sorted_arr[i]
                        sorted_arr[i] = sorted_arr[j]
                        sorted_arr[j] = temp
                    }
                }
            }
            sorted_results.add(sorted_arr)
        }

        // Remove duplicates by creating a HashMap (simple approach)
        let unique_map = HashMap<String, Boolean>()
        let final_results = ArrayList<ArrayList<Int64>>()
        for (arr in sorted_results) {
            let key = arr.map({x => x.toString()}).join(",")
            if (!unique_map.contains(key)) {
                unique_map.add(key, true)
                final_results.add(arr)
            }
        }
        return final_results
    }
}

