    public init(text: String) {
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        let result = ArrayList<HashMap<String, String>>()
        let tokens = this.play_text.split(" ")

        for (token in tokens) {
            if (token.isEmpty()) {
                continue
            }

            let length = token.size
            if (length < 2) {
                continue
            }

            let chord = token[0..length-8] // Extract chord part (assuming tune is always 8 digits)
            let tune = token[length-8..length]

            let entry = HashMap<String, String>()
            entry.add("Chord", chord)
            entry.add("Tune", tune)
            result.add(entry)

            if (display) {
                println(this.display(chord, tune))
            }
        }

        return result
    }

    public func display(key: String, value: String): String {
        return "Normal Guitar Playing -- Chord: ${key}, Play Tune: ${value}"
    }
}

