        }

        let parts = trimmedText.split(" ")
        let result = ArrayList<HashMap<String, String>>()

        for (part in parts) {
            let splitPos = 0
            while (splitPos < part.size && !part[splitPos].isDigit()) {
                splitPos += 1
            }

            let chord = if (splitPos > 0) { part[0..<splitPos].join("") } else { "" }
            let tune = if (splitPos < part.size) { part[splitPos..].join("") } else { "" }

            if (!chord.isEmpty() && !tune.isEmpty()) {
                let map = HashMap<String, String>()
                map.add("Chord", chord)
                map.add("Tune", tune)
                result.add(map)

                if (display) {
                    println(this.display(key: chord, value: tune))
                }
            }
        }

        return result
    }

    public func display(key: String, value: String): String {
        return "Normal Guitar Playing -- Chord: ${key}, Play Tune: ${value}"
    }
