            return result
        }

        let parts = trimmed.split(" ")
        for (part in parts) {
            if (part.size < 2) {
                continue
            }

            // Find the first digit to separate chord and tune
            var split_index = 0
            for (i in 0..<part.size) {
                let c = part[i]
                if (c >= r'0' && c <= r'9') {
                    split_index = i
                    break
                }
            }

            let chord_part = part.substring(0, i: split_index)
            let tune_part = part.substring(split_index)

            let map = HashMap<String, String>()
            map.add("Chord", chord_part)
            map.add("Tune", tune_part)
            result.add(map)

            if (display) {
                println(this.display(key: chord_part, value: tune_part))
            }
        }

        return result
    }

