        */
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        /*
        Clears the expression of all characters that are not brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.clear_expr()
        >>> b.expr
        '()'
        */
        var result = ""
        for (c in expr) {
            let char = c.toString()
            if (left_brackets.contains(char) || right_brackets.contains(char)) {
                result += char
            }
        }
        this.expr = result
    }

    public func check_balanced_brackets(): Bool {
        /*
        Checks if the expression has balanced brackets.
        :return: true if the expression has balanced brackets, false otherwise.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        true
        */
        stack.clear()
        for (c in expr) {
            let char = c.toString()
            if (left_brackets.contains(char)) {
                stack.add(char)
            } else if (right_brackets.contains(char)) {
                if (stack.size == 0) {
                    return false
                }
                let top = stack.remove(at: stack.size - 1)
                if (matchBrackets(top, char) == false) {
                    return false
                }
            }
        }
        return stack.size == 0
    }

    private func matchBrackets(left: String, right: String): Bool {
        if (left == "(" && right == ")") {
            return true
        }
        if (left == "{" && right == "}") {
            return true
        }
        if (left == "[" && right == "]") {
            return true
        }
        return false
    }
}

