class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().map { Rune.toInt64($0) }.reversed()
        let arr2 = num2.toRuneArray().map { Rune.toInt64($0) }.reversed()
        let maxLen = max(arr1.size, arr2.size)
        var result = ArrayList<Int64>([])
        var carry: Int64 = 0

        for (i in 0..maxLen:1) {
            let digit1 = if (i < arr1.size) { arr1[i] } else { 0 }
            let digit2 = if (i < arr2.size) { arr2[i] } else { 0 }
            let sum = digit1 + digit2 + carry
            result.add(sum % 10)
            carry = sum / 10
        }

        if (carry > 0) {
            result.add(carry)
        }

        let reversed = result.reversed()
        var str = ""
        for (digit in reversed) {
            str = str + "${digit}"
        }
        return str
    }

    public static func subtract(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().map { Rune.toInt64($0) }.reversed()
        let arr2 = num2.toRuneArray().map { Rune.toInt64($0) }.reversed()
        var result = ArrayList<Int64>([])
        var borrow: Int64 = 0
        var isNegative = false

        let (longer, shorter) = if (arr1.size > arr2.size || 
             (arr1.size == arr2.size && compareReversedDigits(arr1, arr2) >= 0)) {
             (arr1, arr2)
         } else {
             isNegative = true
             (arr2, arr1)
         }

        for (i in 0..longer.size:1) {
            let digit1 = if (i < longer.size) { longer[i] } else { 0 }
            let digit2 = if (i < shorter.size) { shorter[i] } else { 0 }
            var diff = digit1 - digit2 - borrow
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            result.add(diff)
        }

        // Remove leading zeros
        while (result.size > 1 && result[result.size - 1] == 0) {
            result.remove(at: result.size - 1)
        }

        let reversed = result.reversed()
        var str = ""
        for (digit in reversed) {
            str = str + "${digit}"
        }
        return if (isNegative && str != "0") { "-${str}" } else { str }
    }

    private static func compareReversedDigits(arr1: ArrayList<Int64>, arr2: ArrayList<Int64>): Int64 {
        if (arr1.size != arr2.size) {
            return arr1.size - arr2.size
        }
        for (i in 0..arr1.size:1) {
            if (arr1[i] != arr2[i]) {
                return arr1[i] - arr2[i]
            }
        }
        return 0
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let arr1 = num1.toRuneArray().map { Rune.toInt64($0) }.reversed()
        let arr2 = num2.toRuneArray().map { Rune.toInt64($0) }.reversed()
        let result = ArrayList<Int64>(Array.fill(arr1.size + arr2.size, 0))

        for (i in 0..arr1.size:1) {
            for (j in 0..arr2.size:1) {
                result[i + j] = result[i + j] + arr1[i] * arr2[j]
                result[i + j + 1] = result[i + j + 1] + result[i + j] / 10
                result[i + j] = result[i + j] % 10
            }
        }

        // Remove trailing zeros (from multiplication carry)
        while (result.size > 1 && result[result.size - 1] == 0) {
            result.remove(at: result.size - 1)
        }

        let reversedResult = result.reversed()
        var str = ""
        for (digit in reversedResult) {
            str = str + "${digit}"
        }
        return str
    }
}

