class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        var a = num1.toRuneArray().reverse()
        var b = num2.toRuneArray().reverse()
        let max_len = if (a.size > b.size) { a.size } else { b.size }
        let carry = var 0
        let result = ArrayList<Rune>()

        for (i in 0..max_len:1) {
            let digit_a = if (i < a.size) { (a[i].toInt() - '0'.toInt()) } else { 0 }
            let digit_b = if (i < b.size) { (b[i].toInt() - '0'.toInt()) } else { 0 }
            let sum = digit_a + digit_b + carry
            carry = sum / 10
            result.add(r'${sum % 10}'.toChar())
        }

        if (carry > 0) {
            result.add(r'${carry}'.toChar())
        }

        let reversed = ArrayList<Rune>(result.size())
        for (i in 0..result.size():1) {
            reversed.add(result[result.size() - i - 1])
        }
        return reversed.joinToString()
    }

    public static func subtract(num1: String, num2: String): String {
        var a = num1.toRuneArray().reverse()
        var b = num2.toRuneArray().reverse()
        let max_len = if (a.size > b.size) { a.size } else { b.size }
        let borrow = var 0
        let result = ArrayList<Rune>()
        let is_negative = var false

        if (compareStrings(num1, num2) < 0) {
            let temp = a
            a = b
            b = temp
            is_negative = true
        }

        for (i in 0..max_len:1) {
            let digit_a = if (i < a.size) { (a[i].toInt() - '0'.toInt()) } else { 0 }
            let digit_b = if (i < b.size) { (b[i].toInt() - '0'.toInt()) } else { 0 }
            var diff = digit_a - digit_b - borrow

            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.add(r'${diff}'.toChar())
        }

        let reversed = ArrayList<Rune>()
        var leading_zero = true
        for (i in 0..result.size():1) {
            let index = result.size() - i - 1
            if (result[index] != '0'.toInt()) {
                leading_zero = false
            }
            if (!leading_zero) {
                reversed.add(result[index].toRune())
            }
        }

        let str = if (reversed.size() == 0) { "0" } else { reversed.joinToString() }
        return if (is_negative) { "-${str}" } else { str }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let m = num1.size()
        let n = num2.size()
        let result = ArrayList<Int64>(size: m + n, init: { _ => 0 })

        for (i in m-1..-1:-1) {
            for (j in n-1..-1:-1) {
                result[i + j + 1] += (num1[i].toInt() - '0'.toInt()) * (num2[j].toInt() - '0'.toInt())
                result[i + j] += result[i + j + 1] / 10
                result[i + j + 1] = result[i + j + 1] % 10
            }
        }

        var i = 0
        while (i < result.size() && result[i] == 0) {
            i += 1
        }

        let chars = ArrayList<Rune>()
        while (i < result.size()) {
            chars.add(r'${result[i]}'.toChar())
            i += 1
        }

        return chars.joinToString()
    }

    private static func compareStrings(a: String, b: String): Int64 {
        if (a.size() != b.size()) {
            return a.size() - b.size()
        }
        for (i in 0..a.size():1) {
            let diff = (a[i].toInt() - '0'.toInt()) - (b[i].toInt() - '0'.toInt())
            if (diff != 0) {
                return diff
            }
        }
        return 0
    }
}

private extension Rune {
    public func toInt() -> Int64 {
        if (this >= r'0' && this <= r'9') {
            return this.toIntNative() - '0'.toIntNative()
        }
        return 0
    }
}

private extension ArrayList<Int64> {
    public init(size: Int64, init: func(Int64) -> Int64) {
        let arr = ArrayList<Int64>()
        for (i in 0..size:1) {
            arr.add(init(i))
        }
        this = arr
    }
}

private extension ArrayList<Rune> {
    public func joinToString() -> String {
        let sb = StringBuilder()
        for (r in this) {
            sb.append(r.toString())
        }
        return sb.toString()
    }
}

