class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().reverse()
        let arr2 = num2.toRuneArray().reverse()

        var carry = 0
        var result = ArrayList<Rune>()

        let maxLen = max(arr1.size, arr2.size)
        for (i in 0..maxLen) {
            let d1 = if (i < arr1.size) { arr1[i].toInt() } else { 0 }
            let d2 = if (i < arr2.size) { arr2[i].toInt() } else { 0 }

            let sum = d1 + d2 + carry
            carry = sum / 10
            result.add(r'${sum % 10}')
        }

        if (carry > 0) {
            result.add(r'${carry}')
        }

        let reversed = ArrayList<Rune>()
        for (i in (0..<result.size).reverse()) {
            reversed.add(result[i])
        }

        return String.fromRunes(reversed)
    }

    public static func subtract(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().reverse()
        let arr2 = num2.toRuneArray().reverse()

        let negative: Bool
        if (arr1.size < arr2.size || 
            (arr1.size == arr2.size && compareDigits(arr1: arr1, arr2: arr2) < 0)) {
            negative = true
            // Swap for easier calculation
            let temp = arr1
            arr1[0..temp.size] = arr2[0..temp.size]
            arr2[0..arr2.size] = temp[0..arr2.size]
        } else {
            negative = false
        }

        var borrow = 0
        var result = ArrayList<Rune>()

        for (i in 0..arr1.size) {
            let d1 = if (i < arr1.size) { arr1[i].toInt() } else { 0 }
            let d2 = if (i < arr2.size) { arr2[i].toInt() } else { 0 }

            var diff = d1 - borrow - d2
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.add(r'${diff}')
        }

        // Remove leading zeros
        var firstNonZero = 0
        for (i in 0..<result.size) {
            if (result[i].toInt() != 0) {
                firstNonZero = i
                break
            }
        }

        let trimmed = ArrayList<Rune>()
        for (i in firstNonZero..result.size) {
            trimmed.add(result[i])
        }

        let reversed = ArrayList<Rune>()
        for (i in (0..<trimmed.size).reverse()) {
            reversed.add(trimmed[i])
        }

        let finalStr = String.fromRunes(reversed)
        if (finalStr.isEmpty()) {
            return "0"
        }

        return if (negative) { "-${finalStr}" } else { finalStr }
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let arr1 = num1.toRuneArray().reverse()
        let arr2 = num2.toRuneArray().reverse()

        let m = arr1.size
        let n = arr2.size
        var result = ArrayList<Int64>([0] * (m + n))

        for (i in 0..m) {
            for (j in 0..n) {
                let d1 = arr1[i].toInt()
                let d2 = arr2[j].toInt()
                result[i + j] += Int64(d1 * d2)
                result[i + j + 1] += result[i + j] / 10
                result[i + j] %= 10
            }
        }

        // Remove trailing zeros from multiplication (but we want leading zeros in reversed)
        var k = result.size - 1
        while (k >= 0 && result[k] == 0) {
            k -= 1
        }

        let digits = ArrayList<Rune>()
        for (i in 0..k+1) {
            digits.add(r'${result[i]}')
        }

        let reversed = ArrayList<Rune>()
        for (i in (0..<digits.size).reverse()) {
            reversed.add(digits[i])
        }

        return String.fromRunes(reversed)
    }

    private static func compareDigits(arr1: ArrayList<Rune>, arr2: ArrayList<Rune>): Int64 {
        for (i in 0..arr1.size) {
            if (i >= arr2.size) {
                return 1
            }
            let d1 = arr1[i].toInt()
            let d2 = arr2[i].toInt()
            if (d1 != d2) {
                return Int64(d1 - d2)
            }
        }
        return 0
    }
}

extension Rune {
    func toInt(): Int64 {
        match (this) {
            case r'0' => 0
            case r'1' => 1
            case r'2' => 2
            case r'3' => 3
            case r'4' => 4
            case r'5' => 5
            case r'6' => 6
            case r'7' => 7
            case r'8' => 8
            case r'9' => 9
            case _ => 0
        }
    }
}

extension String {
    static func fromRunes(runes: ArrayList<Rune>): String {
        var s = ""
        for (i in 0..runes.size) {
            match (runes[i]) {
                case r'0' => s = "${s}0"
                case r'1' => s = "${s}1"
                case r'2' => s = "${s}2"
                case r'3' => s = "${s}3"
                case r'4' => s = "${s}4"
                case r'5' => s = "${s}5"
                case r'6' => s = "${s}6"
                case r'7' => s = "${s}7"
                case r'8' => s = "${s}8"
                case r'9' => s = "${s}9"
                case _ => s = s
            }
        }
        return s
    }
}

