class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().map { c => RuneToInt(c) }
        let arr2 = num2.toRuneArray().map { c => RuneToInt(c) }

        var i = arr1.size - 1
        var j = arr2.size - 1
        var carry = 0
        let result = ArrayList<Int64>()

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { arr1[i--] } else { 0 }
            let digit2 = if (j >= 0) { arr2[j--] } else { 0 }
            let sum = digit1 + digit2 + carry
            result.add(0, sum % 10)  // prepend digit
            carry = sum / 10
        }

        return IntArrayToString(result)
    }

    public static func subtract(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().map { c => RuneToInt(c) }
        let arr2 = num2.toRuneArray().map { c => RuneToInt(c) }

        var i = arr1.size - 1
        var j = arr2.size - 1
        var borrow = 0
        let result = ArrayList<Int64>()
        var isNegative = false

        // First determine if result is negative
        let cmp = compareBigNums(arr1, arr2)
        if (cmp < 0) {
            isNegative = true
            var temp = arr1
            arr1 = arr2
            arr2 = temp
        }

        while (i >= 0 || j >= 0) {
            let digit1 = if (i >= 0) { arr1[i--] } else { 0 }
            let digit2 = if (j >= 0) { arr2[j--] } else { 0 }

            var diff = digit1 - digit2 - borrow
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.add(0, diff)  // prepend digit
        }

        // Remove leading zeros
        var out = IntArrayToString(result)
        out = stripLeadingZeros(out)

        if (isNegative) {
            out = "-" + out
        }

        return out
    }

    public static func multiply(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().map { c => RuneToInt(c) }
        let arr2 = num2.toRuneArray().map { c => RuneToInt(c) }

        let m = arr1.size
        let n = arr2.size
        let result = ArrayList<Int64>(Array<Int64>.fill(m + n, 0))

        for (i in m - 1..-1) {
            for (j in n - 1..-1) {
                let product = arr1[i] * arr2[j]
                let pos1 = i + j
                let pos2 = i + j + 1
                let sum = product + result[pos2]

                result[pos2] = sum % 10
                result[pos1] += sum / 10
            }
        }

        var out = IntArrayToString(result)
        out = stripLeadingZeros(out)
        return out
    }

    // Helper functions
    private static func RuneToInt(r: Rune): Int64 {
        return r.toString().toInt64() ?? 0
    }

    private static func IntArrayToString(arr: ArrayList<Int64>): String {
        // Filter out leading zeros and join
        var digits = ArrayList<String>()
        var leadingZero = true
        for (i in 0..arr.size) {
            let digit = arr[i].toString()
            if (leadingZero && digit == "0") {
                continue
            }
            leadingZero = false
            digits.add(digit)
        }

        // Handle case where result is zero
        if (digits.size == 0) {
            return "0"
        }

        digits.reverse()
        return digits.join("")
    }

    private static func stripLeadingZeros(s: String): String {
        var i = 0
        while (i < s.size && s[i] == '0') {
            i += 1
        }
        return if (i == s.size) { "0" } else { s.substring(i, s.size - i) }
    }

    private static func compareBigNums(a: ArrayList<Int64>, b: ArrayList<Int64>): Int64 {
        if (a.size != b.size) {
            return a.size - b.size
        }
        for (i in 0..a.size - 1) {
            if (a[i] != b[i]) {
                return a[i] - b[i]
            }
        }
        return 0
    }
}

