class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let arr1 = num1.toRuneArray().map({r: Rune => r.toInt()!}) // Convert each char to digit value
        let arr2 = num2.toRuneArray().map({r: Rune => r.toInt()!})

        var res: ArrayList<Int64> = ArrayList<Int64>()
        var i = arr1.size - 1
        var j = arr2.size - 1
        var carry = 0

        while (i >= 0 || j >= 0 || carry > 0) {
            let digit1 = if (i >= 0) { arr1[i] } else { 0 }
            let digit2 = if (j >= 0) { arr2[j] } else { 0 }

            let sum = digit1 + digit2 + carry
            carry = sum / 10
            res.add(0, (sum % 10).toInt64())

            i -= 1
            j -= 1
        }

        // Convert result array to string
        var result = ""
        for (digit in res) {
            result += digit.toString()
        }

        return result
    }

    public static func subtract(num1: String, num2: String): String {
        // Helper function to compare two number strings
        func isGreater(a: String, b: String): Bool {
            if (a.size != b.size) {
                return a.size > b.size
            }
            let arrA = a.toRuneArray().map({r: Rune => r.toInt()!})
            let arrB = b.toRuneArray().map({r: Rune => r.toInt()!})
            for (k in 0..<arrA.size.step) {
                if (arrA[k] != arrB[k]) {
                    return arrA[k] > arrB[k]
                }
            }
            return false
        }

        let a = num1
        let b = num2
        let isNegative = !isGreater(a, b) && a != b
        let (larger, smaller) = if (isGreater(a, b)) { (a, b) } else { (b, a) }

        let arrLarger = larger.toRuneArray().map({r: Rune => r.toInt()!})
        let arrSmaller = smaller.toRuneArray().map({r: Rune => r.toInt()!})

        var res: ArrayList<Int64> = ArrayList<Int64>()
        var i = arrLarger.size - 1
        var j = arrSmaller.size - 1
        var borrow = 0

        while (i >= 0) {
            let digitLarger = arrLarger[i]
            let digitSmaller = if (j >= 0) { arrSmaller[j] } else { 0 }

            var diff = digitLarger - digitSmaller - borrow
            if (diff < 0) {
                diff += 10
                borrow = 1
            } else {
                borrow = 0
            }

            res.add(0, diff.toInt64())
            i -= 1
            j -= 1
        }

        // Convert result array to string
        var result = ""
        var leadingZero = true
        for (digit in res) {
            if (leadingZero && digit == 0 && res[0] != digit) {
                continue
            }
            leadingZero = false
            result += digit.toString()
        }

        if (result == "") {
            return "0"
        }

        if (isNegative) {
            return "-" + result
        }
        return result
    }

    public static func multiply(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") {
            return "0"
        }

        let arr1 = num1.toRuneArray().map({r: Rune => r.toInt()!}).reversed()
        let arr2 = num2.toRuneArray().map({r: Rune => r.toInt()!}).reversed()

        var res = ArrayList<Int64>([0] * (arr1.size + arr2.size))

        for (i in 0..<arr1.size.step) {
            for (j in 0..<arr2.size.step) {
                res[i + j] += (arr1[i].toInt64() * arr2[j].toInt64())
                res[i + j + 1] += res[i + j] / 10
