        while (bits.size > 0) {
            let chunk = bits.substring(0, min(8, bits.size))
            // Pad with zeros if needed (though input should be byte-aligned)
            let padded = if (chunk.size < 8) {
                String((0..<(8 - chunk.size)).map {_ => "0"}.join("")) + chunk
            } else {
                chunk
            }
            // Convert from binary string to ASCII character
            let char_code = padded.toUInt64(2)?.getOrThrow().toInt8()
            result.add(String(Rune(char_code)))
            bits = bits.substring(min(8, bits.size))
        }

