        var cleaned = ""
        let runes = this.binary_string.runes()
        for (r in runes) {
            if (r == r'0' || r == r'1') {
                cleaned = cleaned + String.fromRune(r)
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let runes = this.binary_string.runes()
        var zeroes = 0
        var ones = 0
        for (r in runes) {
            if (r == r'0') {
                zeroes = zeroes + 1
            } else if (r == r'1') {
                ones = ones + 1
            }
        }
        let total = Float64(zeroes + ones)
        let zero_percent = if (total != 0.0) { zeroes / total } else { 0.0 }
        let one_percent = if (total != 0.0) { ones / total } else { 0.0 }

        let result = HashMap<String, Float64>()
        result.add("Zeroes", zero_percent)
        result.add("Ones", one_percent)
        result.add("Bit length", total)
        return result
    }

    public func convert_to_ascii(): String {
        let runes = this.binary_string.toRuneArray()
        var result = ""
        var current_byte = ""

        for (i in 0..runes.size) {
            if (i % 8 == 0 && i != 0) {
                if (let value = parseInt(current_byte, radix: 2) as Option<Int64>) {
                    if (let ch = value.getOrThrow() as? UInt8) {
                        result = result + String.fromCharCode(ch)
                    }
                }
                current_byte = ""
            }
            if (i < runes.size) {
                current_byte = current_byte + String.fromRune(runes[i])
            }
        }

        // Handle the last byte if it's complete
        if (current_byte.size == 8) {
            if (let value = parseInt(current_byte, radix: 2) as Option<Int64>) {
                if (let ch = value.getOrThrow() as? UInt8) {
                    result = result + String.fromCharCode(ch)
                }
            }
        }

        return result
    }

    public func convert_to_utf8(): String {
        // UTF-8 conversion in Cangjie would follow similar binary pattern,
        // but for simplicity, we'll handle it the same way as ASCII for 8-bit codes
        // In a real implementation, we'd need to handle multi-byte UTF-8 sequences
        return this.convert_to_ascii()
    }
}

