        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned: String = ""
        for (r in this.binary_string.runes()) {
            match (Rune(r)) {
                case r'0' => cleaned += "0"
                case r'1' => cleaned += "1"
                case _ => continue
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let zeros: Int64 = 0
        let ones: Int64 = 0
        for (r in this.binary_string.runes()) {
            match (Rune(r)) {
                case r'0' => zeros += 1
                case r'1' => ones += 1
                case _ => {}
            }
        }
        let total: Float64 = Float64(zeros + ones)
        let zero_perc: Float64 = total == 0.0 ? 0.0 : (Float64(zeros) / total)
        let ones_perc: Float64 = total == 0.0 ? 0.0 : (Float64(ones) / total)

        let info = HashMap<String, Float64>()
        info.add("Zeroes", zero_perc)
        info.add("Ones", ones_perc)
        info.add("Bit length", total)
        return info
    }

    public func convert_to_ascii(): String {
        let cleaned = this.binary_string
        if (cleaned.size % 8 != 0) {
            return "" // Invalid binary string for ASCII conversion
        }
        var result = ""
        for (i in 0..cleaned.size:8) {
            let byte_str = cleaned[i..i+8]
            let num = byte_str.toRadix(base: 2) ?? 0
            let char = Rune(num).toChar() ?? r'?'
            result += String(char)
        }
        return result
    }

    public func convert_to_utf8(): String {
        // UTF-8 conversion can be handled similarly to ASCII
        // since ASCII is a subset of UTF-8 (for 7-bit values)
        // For multi-byte UTF-8 characters, we'd need more complex parsing
        // This simple implementation just treats the binary as ASCII/UTF-8 bytes
        return this.convert_to_ascii()
    }
