class BoyerMooreSearch {
    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        let target = char[0] // Convert string to first character (String can be treated as rune array)
        var rightmost = -1
        for (i in 0..patLen) {
            if (pattern[i] == target) {
                rightmost = i
            }
        }
        return rightmost
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        var mismatchPos = -1
        let maxLen = this.patLen < (this.textLen - currentPos) ? this.patLen : (this.textLen - currentPos)
        for (i in 0..maxLen) {
            if (pattern[i] != text[currentPos + i]) {
                mismatchPos = currentPos + i
                break
            }
        }
        return mismatchPos
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        var positions = ArrayList<Int64>()
        for (i in 0..(textLen - patLen + 1)) {
            var found = true
            for (j in 0..patLen) {
                if (text[i + j] != pattern[j]) {
                    found = false
                    var badCharShift = 1
                    // Find last occurrence of text[i+patLen-1] in pattern
                    let badChar = text[i + patLen - 1]
                    var lastOccurrence = -1
                    for (k in 0..patLen) {
                        if (pattern[k] == badChar) {
                            lastOccurrence = k
                        }
                    }
                    if (lastOccurrence != -1) {
                        badCharShift = patLen - lastOccurrence - 1
                    }
                    i += badCharShift - 1 // -1 because of i++ in loop
                    break
                }
            }
            if (found) {
                positions.add(i)
                // Skip full pattern match length for next search
                i += patLen - 1 // -1 because of i++ in loop
            }
        }
        return positions
    }

    /* Optimized version combining both helper functions */
    public func search(): ArrayList<Int64> {
        var positions = ArrayList<Int64>()
        if (patLen == 0) return positions

        for (i in 0..(textLen - patLen + 1)) {
            let mismatchPos = mismatch_in_text(currentPos: i)
            if (mismatchPos == -1) {
                positions.add(i)
                continue
            }
            // Boyer-Moore bad character heuristic
            let mismatchChar = text[mismatchPos]
            let badCharShift = match_in_pattern(char: mismatchChar.toRune().toString())
            var shift = 1
            if (badCharShift != -1) {
                shift = mismatchPos - i - badCharShift
            }
            i += shift > 1 ? shift - 1 : 0 // -1 because of i++ in loop
        }
        return positions
    }
}

import std.collection.ArrayList

class BoyerMooreSearch {

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        this.text = text
        this.pattern = pattern
        this.textLen = text.size.toInt64()
        this.patLen = pattern.size.toInt64()
    }

    public func match_in_pattern(char: String): Int64 {
        // Convert String to Rune since we're checking single characters
        // Note: This assumes char is a single character string
        let charRune = char.toRuneArray()[0]
        for (i in 0..this.patLen.toInt() - 1) {
            if (this.pattern.toRuneArray()[i] == charRune) {
                return i.toInt64()
            }
        }
        return -1.toInt64()
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        // Check each character in the pattern against text at currentPos
        for (i in 0..this.patLen.toInt()) {
            let textChar = this.text.toRuneArray()[currentPos.toInt() + i]
            let patChar = this.pattern.toRuneArray()[i]
            if (textChar != patChar) {
                return (currentPos.toInt() + i).toInt64()
            }
        }
        return -1.toInt64()
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        let result = ArrayList<Int64>()
        // Preprocess the bad character shift table
        var badCharShift = HashMap<Rune, Int64>()
        for (i in 0..this.patLen.toInt() - 1) {
            let char = this.pattern.toRuneArray()[i]
            badCharShift[char] = (this.patLen.toInt() - 1 - i).toInt64()
        }

        var s: Int64 = 0  // starting index in text
        while (s <= (this.textLen - this.patLen)) {
            var j: Int64 = this.patLen - 1
            while (j >= 0 && this.pattern.toRuneArray()[j.toInt()] == this.text.toRuneArray()[(s + j).toInt()]) {
                j -= 1.toInt64()
            }
            if (j < 0) {
                // Pattern found
                result.add(s)
                // Could also shift by pattern length for better performance
                let charShift = badCharShift.get(this.text.toRuneArray()[(s + this.patLen).toInt()]) ?? 1.toInt64()
                s += charShift
            } else {
                // Shift by bad character heuristic
                let badChar = this.text.toRuneArray()[(s + j).toInt()]
                let shift = badCharShift.get(badChar) ?? this.patLen
                s += shift
            }
        }
        return result
    }
}

