class Calculator {
    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let tokens = this.tokenize(expression)
        var operandStack = ArrayList<Float64>()
        var operatorStack = ArrayList<String>()

        for (token in tokens) {
            if (token.toFloat64().isSome()) {
                operandStack.add(token.toFloat64().getOrThrow())
            } else if (token == "(") {
                operatorStack.add(token)
            } else if (token == ")") {
                while (operatorStack.size != 0 && operatorStack.last() != "(") {
                    var result = this.apply_operator(operandStack, operatorStack)
                    operandStack = result[0]
                    operatorStack = result[1]
                }
                operatorStack.remove(at: operatorStack.size - 1)  // Remove '('
            } else {
                while (operatorStack.size != 0 && 
                       operatorStack.last() != "(" && 
                       this.precedence(operatorStack.last()) >= this.precedence(token)) {
                    var result = this.apply_operator(operandStack, operatorStack)
                    operandStack = result[0]
                    operatorStack = result[1]
                }
                operatorStack.add(token)
            }
        }

        while (operatorStack.size != 0) {
            var result = this.apply_operator(operandStack, operatorStack)
            operandStack = result[0]
            operatorStack = result[1]
        }

        if (operandStack.size == 1) {
            return Some<Float64>(operandStack[0])
        } else {
            return None<Float64>
        }
    }

    private func tokenize(expression: String): ArrayList<String> {
        var tokens = ArrayList<String>()
        var i = 0
        let n = expression.size

        while (i < n) {
            let c = expression[i]
            if (c == ' ') {
                i += 1
                continue
            }
            if (c == '+' || c == '-' || c == '*' || c == '/' || c == '^' || c == '(' || c == ')') {
                tokens.add(String(c))
                i += 1
            } else {
                var num = ""
                while (i < n && (expression[i].isDigit() || expression[i] == '.')) {
                    num += expression[i]
                    i += 1
                }
                tokens.add(num)
            }
        }
        return tokens
    }

    public func precedence(op: String): Int64 {
        if (op == "^") {
            return 3
