        operand_stack.remove(at: operand_stack.size - 1)
        operand_stack.remove(at: operand_stack.size - 1)

        let result = operators[op] ?? {a: Float64, b: Float64 => 0.0}(x, y)
        operand_stack.add(result)

        if (!operator_stack.isEmpty) {
            operator_stack.remove(at: operator_stack.size - 1)
        }

        return (operand_stack, operator_stack)
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        this.operators.add("+", {x: Float64, y: Float64 => x + y})
        this.operators.add("-", {x: Float64, y: Float64 => x - y})
        this.operators.add("*", {x: Float64, y: Float64 => x * y})
        this.operators.add("/", {x: Float64, y: Float64 => x / y})
        this.operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let tokens = this.tokenize(expression)
        if (tokens.size == 0) {
            return None<Float64>()
        }

        var operand_stack = ArrayList<Float64>()
        var operator_stack = ArrayList<String>()

        for (i in 0..tokens.size) {
            let token = tokens[i]
            if (i == tokens.size) {
                // Process remaining operators
                while (operator_stack.size > 0) {
                    let (new_operand, new_operator) = this.apply_operator(operand_stack, operator_stack)
                    operand_stack = new_operand
                    operator_stack = new_operator
                }
                break
            }

            if (token.isNumeric()) {
                let num = token.toFloat64()
                operand_stack.add(num)
            } else if (token == "(") {
                operator_stack.add(token)
            } else if (token == ")") {
                while (operator_stack[operator_stack.size - 1] != "(") {
                    let (new_operand, new_operator) = this.apply_operator(operand_stack, operator_stack)
                    operand_stack = new_operand
                    operator_stack = new_operator
                }
                // Remove '(' from stack
                operator_stack.remove(at: operator_stack.size - 1)
            } else if (["+", "-", "*", "/", "^"].contains(token)) {
                while (operator_stack.size > 0 && 
                       operator_stack[operator_stack.size - 1] != "(" && 
                       this.precedence(operator_stack[operator_stack.size - 1]) >= this.precedence(token)) {
                    let (new_operand, new_operator) = this.apply_operator(operand_stack, operator_stack)
                    operand_stack = new_operand
                    operator_stack = new_operator
                }
                operator_stack.add(token)
            }
        }

        return if (operand_stack.size == 1) {
            Some<Float64>(operand_stack[0])
        } else {
            None<Float64>()
        }
    }

    private func tokenize(expression: String): ArrayList<String> {
        var tokens = ArrayList<String>()
        var current_num = ""

        for (i in 0..expression.size) {
            let c = expression[i]
            if (c.isDigit() || c == '.') {
                current_num += c.toString()
            } else {
                if (current_num != "") {
                    tokens.add(current_num)
                    current_num = ""
                }
                if (["+", "-", "*", "/", "^", "(", ")"].contains(c)) {
                    tokens.add(c.toString())
                }
            }
        }

        // Add last number if there was one
        if (current_num != "") {
            tokens.add(current_num)
        }

        return tokens
    }

    public func precedence(op: String): Int64 {
        return match (op) {
            case "+" | "-" => 1
            case "*" | "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        if (operand_stack.size < 2 || operator_stack.size == 0) {
            return (operand_stack, operator_stack)
        }

        let op = operator_stack[operator_stack.size - 1]
        let y = operand_stack[operand_stack.size - 1]
        let x = operand_stack[operand_stack.size - 2]

        // Remove last two operands and last operator
        operand_stack.remove(at: operand_stack.size - 1)
        operand_stack.remove(at: operand_stack.size - 1)
        operator_stack.remove(at: operator_stack.size - 1)

        // Perform the operation
        if (this.operators.contains(op)) {
            let func_ptr = this.operators[op].getOrThrow()
            let result = func_ptr(x, y)
            operand_stack.add(result)
        }

        return (operand_stack, operator_stack)
    }
}

