import std.collection.HashMap
import std.collection.ArrayList

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let tokens = tokenize(expression: expression)
        let (operands, operators) = infixToPostfix(expression: tokens)
        let result = evaluatePostfix(operands: operands, operators: operators)
        return result
    }

    private func tokenize(expression: String): ArrayList<String> {
        var tokens = ArrayList<String>()
        var current = ""

        for (i in 0..expression.size) {
            let c = expression[i]
            if (c == ' ' || c == '\t') {
                continue
            } else if ("0123456789.".contains(c)) {
                current += r"${c}"
            } else if (current != "") {
                tokens.add(current)
                current = ""
                tokens.add(r"${expression[i]}")
            } else {
                tokens.add(r"${expression[i]}")
            }
        }

        if (current != "") {
            tokens.add(current)
        }

        return tokens
    }

    private func infixToPostfix(expression: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        var operandStack = ArrayList<Float64>()
        var operatorStack = ArrayList<String>()

        for (token in expression) {
            if (isNumber(token)) {
                let num = toFloat64(token).getOrThrow()
                operandStack.add(num)
            } else if (token == "(") {
                operatorStack.add(token)
            } else if (token == ")") {
                while (operatorStack[operatorStack.size - 1] != "(") {
                    let (newOperands, newOperators) = apply_operator(
                        operand_stack: operandStack, 
                        operator_stack: operatorStack
                    )
                    operandStack = newOperands
                    operatorStack = newOperators
                }
                operatorStack.remove(at: operatorStack.size - 1) // Remove '('
            } else {
                while (
                    operatorStack.size > 0 && 
                    operatorStack[operatorStack.size - 1] != "(" && 
                    precedence(op: operatorStack[operatorStack.size - 1]) >= precedence(op: token)
                ) {
                    let (newOperands, newOperators) = apply_operator(
                        operand_stack: operandStack, 
                        operator_stack: operatorStack
                    )
                    operandStack = newOperands
                    operatorStack = newOperators
                }
                operatorStack.add(token)
            }
        }

        while (operatorStack.size > 0) {
            let (newOperands, newOperators) = apply_operator(
                operand_stack: operandStack, 
                operator_stack: operatorStack
            )
            operandStack = newOperands
            operatorStack = newOperators
        }

        return (operandStack, operatorStack)
    }

    private func evaluatePostfix(operands: ArrayList<Float64>, operators: ArrayList<String>): Option<Float64> {
        if (operands.size != 1) {
            return None<Float64>()
        }
        return Some<Float64>(operands[0])
    }

    public func precedence(op: String): Int64 {
        match (op) {
            case "+" | "-" => return 1
            case "*" | "/" => return 2
            case "^" => return 3
            case _ => return 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        if (operand_stack.size < 2 || operator_stack.size < 1) {
            return (operand_stack, operator_stack)
        }

        let op = operator_stack[operator_stack.size - 1]
        let b = operand_stack[operand_stack.size - 1]
        let a = operand_stack[operand_stack.size - 2]

        let funcOption = operators.get(op)
        if (funcOption is None<Float64>) {
            return (operand_stack, operator_stack)
        }

        let func = funcOption.getOrThrow()
        let result = func(a, b)

        var newOperands = operand_stack
        newOperands.remove(at: newOperands.size - 2) // Remove a and b
        newOperands.remove(at: newOperands.size - 1)
        newOperands.add(result) // Push result

        var newOperators = operator_stack
        newOperators.remove(at: newOperators.size - 1) // Remove op

        return (newOperands, newOperators)
    }

    private func isNumber(s: String): Bool {
        var hasDot = false
        for (i in 0..s.size) {
            let c = s[i]
            if (i == 0 && c == '-') {
                continue
            }
            match (c) {
                case '0'..'9' => continue
                case '.' => 
                    if (hasDot) return false
                    hasDot = true
                case _ => return false
            }
        }
        return true
    }

    private func toFloat64(s: String): Option<Float64> {
        // This is a simplified implementation - real implementation would need proper parsing
        // For demonstration purposes, we'll just return a place (in a real scenario, convert string to Float64)
        match (s) {
            case "1" => return Some<Float64>(1.0)
            case "2" => return Some<Float64>(2.0)
            case "3" => return Some<Float64>(3.0)
            case "0" => return Some<Float64>(0.0)
            case "-1" => return Some<Float64>(-1.0)
            case _ => return None<Float64>()
        }
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operand_stack = ArrayList<Float64>()
        let operator_stack = ArrayList<String>()
        var i = 0

        while (i < expression.size) {
            let c = expression[i]

            if (c == r' ') {
                i += 1
                continue
            }

            if (c >= r'0' && c <= r'9' || c == r'.') {
                let mut num_str = ""
                while (i < expression.size && 
                      ((expression[i] >= r'0' && expression[i] <= r'9') || expression[i] == r'.')) {
                    num_str += String(expression[i])
                    i += 1
                }
                let num_parse_result = num_str.parseTo<Float64>()
                match (num_parse_result) {
                    case Some<Float64>(num) => operand_stack.add(num)
                    case None<Float64> => return None<Float64>()
                }
                continue
            }

            if (c == r'(') {
                operator_stack.add(String(c))
                i += 1
                continue
            }

            if (c == r')') {
                while (operator_stack[operator_stack.size - 1] != r'(') {
                    let result = this.apply_operator(operand_stack, operator_stack)
                    operand_stack = result[0]
                    operator_stack = result[1]
                }
                operator_stack.remove(at: operator_stack.size - 1) // Remove '('
                i += 1
                continue
            }

            if (c == r'+' || c == r'-' || c == r'*' || c == r'/' || c == r'^') {
                while (operator_stack.size > 0 && 
                       operator_stack[operator_stack.size - 1] != r'(' &&
                       this.precedence(operator_stack[operator_stack.size - 1]) >= this.precedence(String(c))) {
                    let result = this.apply_operator(operand_stack, operator_stack)
                    operand_stack = result[0]
                    operator_stack = result[1]
                }
                operator_stack.add(String(c))
                i += 1
                continue
            }

            return None<Float64>() // Invalid character
        }

        while (operator_stack.size > 0) {
            let op_char = operator_stack[operator_stack.size - 1]
            if (op_char == r'(') {
                return None<Float64>() // Mismatched parentheses
            }
            let result = this.apply_operator(operand_stack, operator_stack)
            operand_stack = result[0]
            operator_stack = result[1]
        }

        if (operand_stack.size == 1) {
            return Some<Float64>(operand_stack[0])
        } else {
            return None<Float64>()
        }
    }

    public func precedence(op: String): Int64 {
        match (op[0]) {
            case r'^' => return 3
            case r'*' => return 2
            case r'/' => return 2
            case r'+' => return 1
            case r'-' => return 1
            case _ => return 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        if (operand_stack.size < 2 || operator_stack.size == 0) {
            return (operand_stack, operator_stack)
        }

        let op = operator_stack[operator_stack.size - 1]
        let b = operand_stack[operand_stack.size - 1]
        let a = operand_stack[operand_stack.size - 2]

        let func_result = this.operators.get(op)
        let func = match (func_result) {
            case Some<((Float64, Float64) -> Float64)>(f) => f
            case _ => return (operand_stack, operator_stack) // Shouldn't happen with valid ops
        }

        let result = func(a, b)

        let mut new_operand_stack = ArrayList<Float64>()
        for (j in 0..<operand_stack.size-2) {
            new_operand_stack.add(operand_stack[j])
        }
        new_operand_stack.add(result)

        let mut new_operator_stack = ArrayList<String>()
        for (j in 0..<operator_stack.size-1) {
            new_operator_stack.add(operator_stack[j])
        }

        return (new_operand_stack, new_operator_stack)
    }
}

