            if (start_time < event.end_time && end_time > event.start_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let day_start = DateTime.of(
            year: date.year, 
            month: date.month, 
            dayOfMonth: date.dayOfMonth, 
            hour: 0, 
            minute: 0
        )
        let day_end = DateTime.of(
            year: date.year, 
            month: date.month, 
            dayOfMonth: date.dayOfMonth, 
            hour: 23, 
            minute: 59
        )

        let events_on_date = this.get_events(date)
        sort(events_on_date, key: {e => e.start_time})

        let available_slots = ArrayList<(DateTime, DateTime)>()
        var current_end = day_start

        for (event in events_on_date) {
            if (current_end < event.start_time) {
                available_slots.add((current_end, event.start_time))
            }
            if (event.end_time > current_end) {
                current_end = event.end_time
            }
        }

        if (current_end < day_end) {
            available_slots.add((current_end, day_end.add(hours: 1)))
        }

        return available_slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming_events = ArrayList<Event>()

        for (event in this.events) {
            if (event.start_time >= now) {
                upcoming_events.add(event)
            }
        }

        sort(upcoming_events, key: {e => e.start_time})

        let result = ArrayList<Event>()
        for (i in 0..num_events) {
            if (i < upcoming_events.size) {
                result.add(upcoming_events[i])
            }
        }

        return result
    }
}

