    }

    public func remove_event(event: Event): Unit {
        for (i in 0..this.events.size) {
            if (this.events[i] == event) {
                this.events.remove(at: i)
                return
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (i in 0..this.events.size) {
            let event = this.events[i]
            if (event.date.year == date.year && 
                event.date.month == date.month && 
                event.date.dayOfMonth == date.dayOfMonth) {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (i in 0..this.events.size) {
            let event = this.events[i]
            if (!((end_time <= event.start_time) || (start_time >= event.end_time))) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let result = ArrayList<(DateTime, DateTime)>()
        let day_start = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let day_end = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 23, minute: 59)
        var current = day_start

        // First get all events on this date and sort them
        let date_events = this.get_events(date: date)
        let sorted_events = ArrayList<Event>()
        for (e in date_events) {
            sorted_events.add(e)
        }

        let compare_events = {l: Event, r: Event => l.start_time < r.start_time}
        sort(sorted_events, lessThan: compare_events)

        // Find gaps between events
        for (e in sorted_events) {
            if (current < e.start_time) {
                result.add((current, e.start_time))
            }
            current = if (e.end_time > current) { e.end_time } else { current }
        }

        // Add time after last event
        if (current < day_end) {
            result.add((current, day_end))
        }

        return result
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()

        // Filter future events
        for (i in 0..this.events.size) {
            let event = this.events[i]
            if (event.end_time > now) {
                upcoming.add(event)
            }
        }

        // Sort by start time
        let compare_events = {l: Event, r: Event => l.start_time < r.start_time}
        sort(upcoming, lessThan: compare_events)

        // Return requested number of events
        let result = ArrayList<Event>()
        let n = if (num_events < upcoming.size) { num_events } else { Int64(upcoming.size) }
        for (i in 0..n) {
            result.add(upcoming[Int64(i)])
        }
        return result
    }
}

