class CalendarUtil {
    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(element: event)
    }

    public func remove_event(event: Event): Unit {
        for (i in 0..this.events.size) {
            if (this.events[i] == event) {
                this.events.remove(at: i)
                return
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for (event in this.events) {
            if (event.date.isSameDay(other: date)) {
                result.add(element: event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for (event in this.events) {
            let has_overlap = (start_time <= event.end_time && end_time >= event.start_time)
            if (has_overlap) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        // Assuming 30-minute intervals and 9am-5pm working day for simplicity
        // This is a basic implementation - real world would need more sophisticated handling
        let slots = ArrayList<(DateTime, DateTime)>()
        var current_start = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 9, minute: 0)
        let end_of_day = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 17, minute: 0)

        while (current_start < end_of_day) {
            let current_end = current_start.add(minutes: 30)
            if (this.is_available(start_time: current_start, end_time: current_end)) {
                slots.add(element: (current_start, current_end))
            }
            current_start = current_end
        }

        // Also add slots after last event until end of day
        let events_on_day = this.get_events(date: date)
        if (events_on_day.size == 0) {
            slots.add(element: (DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 9, minute: 0), end_of_day))
            return slots
        }

        // Sort events by start time
        let lessThan = { l: Event, r: Event => l.start_time < r.start_time }
        sort(events_on_day, lessThan: lessThan)

        // Check space before first event
        let first_event = events_on_day[0]
        if (first_event.start_time > DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 9, minute: 0)) {
            slots.add(element: (
                DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 9, minute: 0),
                first_event.start_time
            ))
        }

        // Check spaces between events
        for (i in 0..events_on_day.size-1) {
            let current_end = events_on_day[i].end_time
            let next_start = events_on_day[i+1].start_time
            if (next_start > current_end) {
                slots.add(element: (current_end, next_start))
            }
        }

        // Check space after last event
        let last_event = events_on_day[events_on_day.size-1]
        if (last_event.end_time < end_of_day) {
            slots.add(element: (last_event.end_time, end_of_day))
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        if (this.events.size == 0) {
            return ArrayList<Event>()
        }

        let now = DateTime.now()
        let upcoming_events = ArrayList<Event>()

        for (event in this.events) {
            if (event.start_time >= now) {
                upcoming_events.add(element: event)
            }
        }

        let lessThan = { l: Event, r: Event => l.start_time < r.start_time }
        sort(upcoming_events, lessThan: lessThan)

        let result = ArrayList<Event>()
        let count = min(num_events, upcoming_events.size)
        for (i in 0..count) {
            result.add(element: upcoming_events[i])
        }

        return result
    }
}

