        let lessThan = {l: Event, r: Event => l.start_time < r.start_time}
        sort(sortedEvents, lessThan: lessThan)

        let slots = ArrayList<(DateTime, DateTime)>()
        var lastEndTime = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)

