                                  dayOfMonth: date.dayOfMonth + 1)))
            return slots
        }

        // Sort events by start time
        sort(events_on_date, key: {event => event.start_time})

        // Check before first event
        let first_start = events_on_date[0].start_time
        if (DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth) < first_start) {
            slots.add((DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth), first_start))
        }

        // Check between events
        var i = 0
        while (i < events_on_date.size - 1) {
            let current_end = events_on_date[i].end_time
            let next_start = events_on_date[i+1].start_time
            if (current_end < next_start) {
                slots.add((current_end, next_start))
            }
            i += 1
        }

        // Check after last event
        let last_end = events_on_date[events_on_date.size-1].end_time
        let end_of_day = DateTime.of(year: date.year, month: date.month, 
                                    dayOfMonth: date.dayOfMonth + 1)
        if (last_end < end_of_day) {
            slots.add((last_end, end_of_day))
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()

        for (event in events) {
            if (event.start_time >= now) {
                upcoming.add(event)
            }
        }

        sort(upcoming, key: {event => event.start_time})

        let result = ArrayList<Event>()
        var count = 0
        for (event in upcoming) {
            if (count >= num_events) break
            result.add(event)
            count += 1
        }

        return result
    }
