    public init() {
        _data = HashMap<String, Any>()
    }

    private static func _to_camel_case_helper(word: String, is_first: Bool): String {
        if word.size == 0 {
            return ""
        }

        let runes = word.toRuneArray()
        var result = ""
        for i in 0..runes.size {
            let r = runes[i]
            let char = String.fromRune(r)
            if char == "_" {
                continue
            }
            if i == 0 && !is_first {
                result += char.uppercase()
            } else if i > 0 && runes[i-1] == r'_' {
                result += char.uppercase()
            } else {
                result += char.lowercase()
            }
        }
        return result
    }

    public static func _to_camel_case(key: String): String {
        var parts = ArrayList<String>()
        var current_word = ""
        var in_word = false

        for c in key.runes() {
            let s = String.fromRune(c)
            if s == "_" {
                if current_word.size > 0 && in_word {
                    parts.add(current_word)
                    current_word = ""
                }
                in_word = false
            } else {
                current_word += s
                in_word = true
            }
        }

        if current_word.size > 0 {
            parts.add(current_word)
        }

        if parts.size == 0 {
            return ""
        }

        var result = _to_camel_case_helper(word: parts[0], is_first: true)
        for i in 1..parts.size {
            result += _to_camel_case_helper(word: parts[i], is_first: false)
        }

        return result
    }

    public func _convert_key(key: Any): Any {
        match (key) {
            case Some<String>(k) => return String(_to_camel_case(key: k))
