            if (this.time_in_range(check_time: check_time, start_time: course.start_time, end_time: course.end_time)) {
                return false
            }
        }
        return true
    }

    private func time_in_range(check_time: String, start_time: String, end_time: String): Bool {
        let check_dt = DateTime.parse(date: check_time, format: "yyyy/MM/dd HH:mm")
        let start_dt = DateTime.parse(date: start_time, format: "yyyy/MM/dd HH:mm")
        let end_dt = DateTime.parse(date: end_time, format: "yyyy/MM/dd HH:mm")
        return check_dt >= start_dt && check_dt <= end_dt
    }

    public func check_course_conflict(new_course: Course): Bool {
        for (i in 0..<this.courses.size) {
            let existing_course = this.courses[i]
            if (this.courses_conflict(course1: existing_course, course2: new_course)) {
                return false
            }
        }
        return true
    }

    private func courses_conflict(course1: Course, course2: Course): Bool {
        let start1 = DateTime.parse(date: course1.start_time, format: "yyyy/MM/dd HH:mm")
        let end1 = DateTime.parse(date: course1.end_time, format: "yyyy/MM/dd HH:mm")
        let start2 = DateTime.parse(date: course2.start_time, format: "yyyy/MM/dd HH:mm")
        let end2 = DateTime.parse(date: course2.end_time, format: "yyyy/MM/dd HH:mm")

        return !(end1 < start2 || start1 > end2)
    }
}

