    let courses: ArrayList<Course>

    public init(id: Int64) {
        this.id = id
        this.courses = ArrayList<Course>()
    }

    public func add_course(course: Course): Unit {
        if (!this.check_course_conflict(new_course: course)) {
            return
        }
        var i = 0
        while (i < this.courses.size) {
            if (this.courses[i] == course) {
                return
            }
            i = i + 1
        }
        this.courses.add(course)
    }

    public func remove_course(course: Course): Unit {
        var i = 0
        while (i < this.courses.size) {
            if (this.courses[i] == course) {
                this.courses.remove(at: i)
                return
            }
            i = i + 1
        }
    }

    public func is_free_at(check_time: String): Bool {
        var i = 0
        while (i < this.courses.size) {
            let course = this.courses[i]
            if (this.check_time_conflict(
                check_time: check_time, 
                course_start: course.start_time, 
                course_end: course.end_time
            )) {
                return false
            }
            i = i + 1
        }
        return true
    }

    public func check_course_conflict(new_course: Course): Bool {
        var i = 0
        while (i < this.courses.size) {
            let existing = this.courses[i]
            if (this.check_time_conflict(
                check_time: new_course.start_time,
                course_start: existing.start_time,
                course_end: existing.end_time
            ) || this.check_time_conflict(
                check_time: new_course.end_time,
                course_start: existing.start_time,
                course_end: existing.end_time
            )) {
                return false
            }

            if (this.check_time_conflict(
                check_time: existing.start_time,
                course_start: new_course.start_time,
                course_end: new_course.end_time
            ) || this.check_time_conflict(
                check_time: existing.end_time,
                course_start: new_course.start_time,
                course_end: new_course.end_time
            )) {
                return false
            }
            i = i + 1
        }
        return true
    }

    private func check_time_conflict(check_time: String, course_start: String, course_end: String): Bool {
        let dt_check = DateTime.parse(format: "yyyy/MM/dd HH:mm", time_str: check_time)
        let dt_start = DateTime.parse(format: "yyyy/MM/dd HH:mm", time_str: course_start)
        let dt_end = DateTime.parse(format: "yyyy/MM/dd HH:mm", time_str: course_end)

        return (dt_check >= dt_start && dt_check < dt_end)
    }
}

