class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        let name = student["name"] ?? ""
        for (i in 0..this.students.size) {
            let s = this.students[i]
            if (s["name"] == name) {
                return 0
            }
        }
        this.students.add(student)
        this.students_registration_classes.add(name, ArrayList<String>())
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        let class_list = this.students_registration_classes.get(student_name)
        if (class_list != None) {
            let actual_list = class_list.getOrThrow()
            // Check if already registered (optional)
            var already_registered = false
            for (i in 0..actual_list.size) {
                if (actual_list[i] == class_name) {
                    already_registered = true
                    break
                }
            }
            if (!already_registered) {
                actual_list.add(class_name)
            }
            return actual_list
        }
        return ArrayList<String>()
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let result = ArrayList<String>()
        for (i in 0..this.students.size) {
            let student = this.students[i]
            if (student["major"] == major) {
                result.add(student["name"] ?? "")
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = HashSet<String>()
        for (i in 0..this.students.size) {
            let student = this.students[i]
            let major = student["major"] ?? ""
            majors.add(major)
        }
        let result = ArrayList<String>()
        // Convert HashSet to ArrayList
        for (major in majors) {
            result.add(major)
        }
        return result
    }

    public func get_most_popular_class_in_major(major: String): String {
        let class_counts = HashMap<String, Int64>()

        // First collect all classes from students in the major
        for (i in 0..this.students.size) {
            let student = this.students[i]
            if (student["major"] != major) {
                continue
            }
            let name = student["name"] ?? ""
            let class_list_opt = this.students_registration_classes.get(name)
            if (class_list_opt != None) {
                let class_list = class_list_opt.getOrThrow()
                for (j in 0..class_list.size) {
                    let class_name = class_list[j]
                    let count_opt = class_counts.get(class_name)
                    let count = count_opt ?? None
                    if (count != None) {
                        let current_count = count.getOrThrow()
                        class_counts.add(class_name, current_count + 1)
                    } else {
                        class_counts.add(class_name, 1)
                    }
                }
            }
        }

        // Find the class with maximum count
        var max_count: Int64 = 0
        var most_popular = ""
        for (class_name in class_counts) {
            let count_opt = class_counts.get(class_name)
            if (count_opt != None) {
                let count = count_opt.getOrThrow()
                if (count > max_count) {
                    max_count = count
                    most_popular = class_name
                }
            }
        }
        return most_popular
    }
}

