        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        /* Check if student already exists by name */
        let name = student["name"] ?? ""
        var found = false
        for (student_map in this.students) {
            if (student_map["name"] == name) {
                found = true
                break
            }
        }

        if (found) {
            return 0
        } else {
            this.students.add(student)
            /* Initialize empty class list for new student */
            this.students_registration_classes[name] = ArrayList<String>()
            return 1
        }
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        /* Ensure student exists */
        if (!this.students_registration_classes.contains(student_name)) {
            return ArrayList<String>()
        }

        /* Get or create student's class list */
        let class_list = this.students_registration_classes[student_name] ?? ArrayList<String>()
        class_list.add(class_name)
        this.students_registration_classes[student_name] = class_list
        return class_list
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        let result = ArrayList<String>()
        for (student in this.students) {
            if (student["major"] == major) {
                result.add(student["name"] ?? "")
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        let majors = ArrayList<String>()
        let seen = HashSet<String>()

        for (student in this.students) {
            let major = student["major"] ?? ""
            if (!seen.contains(major)) {
                seen.add(major)
                majors.add(major)
            }
        }
        return majors
    }

    public func get_most_popular_class_in_major(major: String): String {
        let class_counts = HashMap<String, Int64>()

        /* First find all students in the major */
        let student_names = this.get_students_by_major(major: major)

        /* Count class occurrences */
        for (name in student_names) {
            let classes = this.students_registration_classes[name] ?? ArrayList<String>()
            for (cls in classes) {
                let count = class_counts[cls] ?? 0
                class_counts[cls] = count + 1
            }
        }

        if (class_counts.size == 0) {
            return ""
        }

        /* Find class with max count */
        var max_class = ""
        var max_count: Int64 = 0
        for (entry in class_counts) {
            if (entry.value > max_count) {
                max_count = entry.value
                max_class = entry.key
            }
        }

        return max_class
    }
}

