import std.collection.ArrayList

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) {
            return 0
        }
        // n choose m = n! / (m! * (n-m)!)
        let numerator = factorial(n)
        let denominator = factorial(m) * factorial(n - m)
        return numerator / denominator
    }

    public static func count_all(n: Int64): Int64 {
        var total: Int64 = 0
        for (i in 1..n + 1) {
            total += count(n, i)
            // Check for overflow before adding
            if (total < 0) { // If adding made it negative (unlikely but possible with large n)
                return Int64.Max
            }
        }
        return total
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        if (m <= 0 || m > datas.size) {
            return result
        }
        let temp = ArrayList<String>()
        _select(0, temp, m, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (i in 1..datas.size + 1) {
            result.addAll(select(i))
        }
        return result
    }

    public func _select(dataIndex: Int64, tempList: ArrayList<String>, 
                       remaining: Int64, result: ArrayList<ArrayList<String>>): Unit {
        if (remaining == 0) {
            result.add(ArrayList<String>(tempList))
            return
        }

        for (i in dataIndex..datas.size) {
            tempList.add(datas[i])
            _select(i + 1, tempList, remaining - 1, result)
            tempList.remove(at: tempList.size - 1)
        }
    }
}

