    public static func factorial(n: Int64): Int64 {
        var result = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m < 0 || m > n) {
            return 0
        }
        let num = factorial(n)
        let denom = factorial(n - m) * factorial(m)
        return num / denom
    }

    public static func count_all(n: Int64): Int64 {
        if (n < 0) {
            return 0
        }
        // Sum of C(n,0) + C(n,1) + ... + C(n,n) = 2^n
        // But we need to check for overflow before calculating
        if (n > 62) {  // 2^63-1 is max Int64
            return Int64.MAX
        }
        let result = 1 << n
        if (result < 0) {  // Check for overflow (though this would require n=63)
            return Int64.MAX
        }
        return result - 1  // Exclude empty combination if desired, or keep as is for all subsets
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        if (m < 0 || m > datas.size) {
            return result
        }
        let current = ArrayList<String>()
        this._select(0, current, m, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let allCombinations = ArrayList<ArrayList<String>>()
        for (i in 1..this.datas.size + 1) {
            let combinations = this.select(i)
            for (j in 0..combinations.size) {
                allCombinations.add(combinations[j])
            }
        }
        return allCombinations
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, m: Int64, result: ArrayList<ArrayList<String>>): Unit {
