class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let content = File.readAllText(file_name)
        let lines = content.split("\n").filter({!it.isEmpty()})
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        for (i in 0..lines.size) {
            let parts = lines[i].split(",").map({it.trim()})
            if (i == 0) {
                title = ArrayList<String>(parts)
            } else {
                data.add(ArrayList<String>(parts))
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        if (data.size == 0) {
            return 0
        }

        var content = ""
        for (i in 0..data.size) {
            let row = data[i]
            let line = row.join(",")
            content += line
            if (i != data.size - 1) {
                content += "\n"
            }
        }

        try {
            File.writeAllText(file_name, content)
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = this.read_csv(save_file_name)
        if (data.size == 0 || N < 0 || N >= title.size) {
            return 0
        }

        var new_data = ArrayList<ArrayList<String>>()
        var new_title = ArrayList<String>([title[N]])

        for (row in data) {
            if (N < row.size) {
                let element = row[N].toUpperString()
                new_data.add(ArrayList<String>([element]))
            }
        }

        let new_file_name = save_file_name.replace(".csv", "") + "_process.csv"
        return this.write_csv(
            data: ArrayList<ArrayList<String>>([new_title].concat(new_data)),
            file_name: new_file_name
        )
    }
}

import std.collection.ArrayList
