class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file_content = File(file_name).readAsString()
        let lines = file_content.split('\n')
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        if (lines.size > 0) {
            let header = lines[0].split(',')
            for (col in header) {
                title.add(col.trim())
            }

            for (i in 1..lines.size) {
                let line = lines[i]
                if (line.isEmpty()) {
                    continue
                }
                let row = line.split(',')
                var row_data = ArrayList<String>()
                for (col in row) {
                    row_data.add(col.trim())
                }
                data.add(row_data)
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        if (data.size == 0 || data[0].size == 0) {
            return 0
        }

        var content = ArrayList<String>()
        // Write header (first row)
        let header = data[0]
        var header_line = ""
        for (i in 0..header.size) {
            header_line += header[i]
            if (i < header.size - 1) {
                header_line += ","
            }
        }
        content.add(header_line)

        // Write data rows
        for (i in 1..data.size) {
            let row = data[i]
            var row_line = ""
            for (j in 0..row.size) {
                row_line += row[j]
                if (j < row.size - 1) {
                    row_line += ","
                }
            }
            content.add(row_line)
        }

        let file = File(file_name)
        var success = 1 /* default success */
        try {
            file.write(content.join("\n"))
        } catch {
            success = 0
        }

        return success
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = this.read_csv(save_file_name)

        if (N < 0 || N >= title.size || data.size == 0) {
            return 0
        }

        var new_title = ArrayList<String>()
        new_title.add(title[N])

        var new_data = ArrayList<ArrayList<String>>()
        new_data.add(new_title) // header

        for (row in data) {
            if (N < row.size) {
                var new_row = ArrayList<String>()
                new_row.add(row[N].toUpper())
                new_data.add(new_row)
            }
        }

        let process_file_name = save_file_name.replace(".csv", "_process.csv")
        return this.write_csv(new_data, process_file_name)
    }
}

