import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {
    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let content = File.readAllText(file_name)
        let lines = content.split('\n')

        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        for (i, line) in lines.enumerate() {
            if (i == 0 && line.trim().size != 0) {
                // First line is title
                title = parse_csv_line(line)
            } else if (line.trim().size != 0) {
                // Other lines are data
                let row = parse_csv_line(line)
                if (row.size != 0) {
                    data.add(row)
                }
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        if (data.size == 0) {
            return 0
        }

        let title_row = data[0]
        let title_line = join_csv_line(title_row)
        var lines = ArrayList<String>()
        lines.add(title_line)

        for (i in 1..data.size) {
            let row = data[i]
            let line = join_csv_line(row)
            lines.add(line)
        }

        let content = lines.join('\n')
        try {
            File.writeAllText(file_name, content)
            return 1
        } catch {
            return 0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        // Read original file with _process suffix to avoid overwriting during processing
        let original_name = save_file_name.replace(".csv", "")
        let processed_name = "${original_name}_process.csv"

        let (title, data) = this.read_csv(save_file_name)
        if (title.size == 0 || data.size == 0 || N < 0 || N >= title.size) {
            return 0
        }

        var new_data = ArrayList<ArrayList<String>>()

        // Add modified title (only keep selected column header)
        let new_title = ArrayList<String>()
        new_title.add(title[N].toUpper())
        new_data.add(new_title)

        // Process each row's Nth column
        for (row in data) {
            if (N < row.size) {
                let value = row[N].toUpper()
                let new_row = ArrayList<String>()
                new_row.add(value)
                new_data.add(new_row)
            }
        }

        return this.write_csv(new_data, processed_name)
    }

    private func parse_csv_line(line: String): ArrayList<String> {
        var fields = ArrayList<String>()
        var current_field = ArrayList<Rune>()
        var in_quotes = false

        for (r in line.runes()) {
            if (r == r'"') {
                in_quotes = !in_quotes
            } else if (r == r',' && !in_quotes) {
                fields.add(String(current_field))
                current_field = ArrayList<Rune>()
            } else {
                current_field.add(r)
            }
        }

        fields.add(String(current_field))
        return fields
    }

    private func join_csv_line(fields: ArrayList<String>): String {
        return fields.join(',')
    }
}

