class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file = File.open(file_name, mode: FileMode.Read) ?? return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        defer { file.close() }

        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()
        var is_title = true

        for line in file.lines() {
            let trimmed_line = line.trim()
            if trimmed_line.isEmpty() {
                continue
            }

            let fields = ArrayList<String>()
            var current_field = ""
            var in_quotes = false

            for c in trimmed_line.runes() {
                if c == r'"' {
                    in_quotes = !in_quotes
                } else if c == r',' && !in_quotes {
                    fields.add(current_field.trim())
                    current_field = ""
                } else {
                    current_field += String.fromRune(c)
                }
            }

            fields.add(current_field.trim())

            if is_title {
                title = fields
                is_title = false
            } else {
                data.add(fields)
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File.open(file_name, mode: FileMode.Write) ?? return 0
        defer { file.close() }

        for (i, row) in data.iter().enumerate() {
            var line = ""
            for (j, field) in row.iter().enumerate() {
                if j > 0 {
                    line += ","
                }
                line += r"""${field}"""
            }
            file.writeLine(line)
        }

        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = this.read_csv(save_file_name)
        if title.size <= 0 || data.size <= 0 {
            return 0
        }

        if N < 0 || N >= title.size {
            return 0
        }

        let new_title = ArrayList<String>([title[N]])
        let new_data = ArrayList<ArrayList<String>>()

        for row in data {
            if N >= row.size {
                continue
            }
            let capitalized = row[N].toUpper()
            let new_row = ArrayList<String>([capitalized])
            new_data.add(new_row)
        }

        let processed_name = save_file_name.split(".")[0] + "_process.csv"
        return this.write_csv(
            data: ArrayList<ArrayList<String>>([new_title].append(new_data)),
            file_name: processed_name
        )
    }
}

