        if (!file.exists()) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let content = file.readAllText()
        let lines = content.split('\n').filter { it != "" }

        let titles = ArrayList<String>(lines[0].split(',').map { it.trim() })
        var data = ArrayList<ArrayList<String>>()

        for (i in 1..lines.size) {
            let row = ArrayList<String>(lines[i].split(',').map { it.trim() })
            data.add(row)
        }

        return (titles, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File(file_name)
            if (file.exists()) {
                file.delete()
            }
            file.createNewFile()

            var csv_content = ""
            for (i in 0..data.size) {
                let row = data[i]
                csv_content += row.map { it }.join(",")
                if (i != data.size - 1) {
                    csv_content += "\n"
                }
            }

            file.writeAllText(csv_content)
            return 1
        } catch {
            return 0
        }
