        let file = File(file_name)
        if (!file.exists()) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let content = file.readToString()?.split('\n')
        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        if (content == None) {
            return (title, data)
        }

        let lines = content.getOrThrow()
        for (i, line) in lines.enumerate() {
            if (i == 0) {
                title = ArrayList<String>(line.split(','))
            } else {
                let row = ArrayList<String>(line.split(','))
                if (row.size > 0) {
                    data.add(row)
                }
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        if (data.size == 0) {
            return 0
        }

        let file = File(file_name)
        if (file.exists()) {
            file.delete()
        }

        let writer = FileWriter(file_name)
        for (i, row) in data.enumerate() {
            let line = row.join(',')
            if (i < data.size - 1) {
                writer.writeLine(line)
            } else {
                writer.write(line)
            }
        }
        writer.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = this.read_csv(save_file_name)
