            if (N < row.size) {
                let value = row[N].toUpperCase()
                processed_row.add(value)
            }
        }
        new_data.add(processed_row)

        let new_file_name = save_file_name.replace(".csv", "_process.csv")
        return this.write_csv(new_data, new_file_name)
    }
}

import std.collection.ArrayList
