import std.unicode.UnicodeStringExtension

class CSVProcessor {
    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file_path = FilePath(file_name)
        let file = openFile(file_path, FileMode.Read)
        defer { file.close() }

        let content = readAllText(file)
        let lines = content.split('\n').filter({line => line.size() > 0})

        var title = ArrayList<String>()
        var data = ArrayList<ArrayList<String>>()

        for (i in 0..lines.size()) {
            let columns = lines[i].split(',').map({col => col.trim()})
            if (i == 0) {
                title = ArrayList<String>(columns)
            } else {
                data.add(ArrayList<String>(columns))
            }
        }

        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file_path = FilePath(file_name)
        let file = openFile(file_path, FileMode.Write)
        defer { file.close() }

        var output = ""
        for (row in data) {
            let line = row.map({cell => cell}).join(',')
            output = "${output}${line}\n"
        }

        let bytes_written = writeAllText(file, output)
        return if (bytes_written > 0) { 1 } else { 0 }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = this.read_csv(save_file_name)

        let new_title = ArrayList<String>()
        new_title.add(title[N])

        let new_data = ArrayList<ArrayList<String>>()
        for (row in data) {
            if (N < row.size()) {
                let processed_cell = row[N].toUpperCase()
                new_data.add(ArrayList<String>([processed_cell]))
            }
        }

        let output_file_name = "${save_file_name}_process.csv"
        return this.write_csv(
            data = ArrayList<ArrayList<String>>([new_title].concat(new_data)),
            file_name = output_file_name
        )
    }
}

