import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.sort.*

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        if (data1.size != data2.size || data1.size == 0) {
            return 0.0
        }

        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0
        var sum1_sq: Float64 = 0.0
        var sum2_sq: Float64 = 0.0
        var p_sum: Float64 = 0.0

        for (i in 0..data1.size) {
            let x = data1[i]
            let y = data2[i]
            sum1 += x
            sum2 += y
            sum1_sq += x * x
            sum2_sq += y * y
            p_sum += x * y
        }

        let n = data1.size.toFloat64()
        let num = p_sum - (sum1 * sum2 / n)
        let den1 = sqrt((sum1_sq - sum1 * sum1 / n) * (sum2_sq - sum2 * sum2 / n))

        if (den1 == 0.0) {
            return 0.0
        }

        return num / den1
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }

        let n = data.size.toFloat64()
        let mean = data.reduce({acc, x => acc + x}, initial: 0.0).toFloat64() / n

        var m2: Float64 = 0.0
        var m3: Float64 = 0.0

        for (i in 0..data.size) {
            let dev = data[i] - mean
            m2 += dev * dev
            m3 += dev * dev * dev
        }

        m2 = m2 / n
        if (m2 == 0.0) {
            return 0.0
        }

        let m3_normalized = m3 / n
        return m3_normalized / (m2 * sqrt(m2))
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }

        let n = data.size.toFloat64()
        let mean = data.reduce({acc, x => acc + x}, initial: 0.0).toFloat64() / n

        var m2: Float64 = 0.0
        var m4: Float64 = 0.0

        for (i in 0..data.size) {
            let dev = data[i] - mean
            m2 += dev * dev
            m4 += dev * dev * dev * dev
        }

        m2 = m2 / n
        if (m2 == 0.0) {
            return 0.0
        }

        let m4_normalized = m4 / n
        let m2_sq = m2 * m2
        return m4_normalized / (m2_sq) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let inv_sqrt_2pi = 1.0 / sqrt(2.0 * 3.141592653589793)
        let sigma_sq = sigma * sigma

        for (i in 0..data.size) {
            let x = data[i]
            let norm = -((x - mu) * (x - mu)) / (2.0 * sigma_sq)
            let pdf_val = exp(norm) * inv_sqrt_2pi / sigma
            result.add(pdf_val)
        }

        return result
    }
}

