class DataStatistics4 {
    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        if (data1.size != data2.size || data1.size == 0) {
            return 0.0
        }

        var sum1 = 0.0
        var sum2 = 0.0
        var sum1_sq = 0.0
        var sum2_sq = 0.0
        var p_sum = 0.0

        for (i in 0..data1.size) {
            let x = data1[i]
            let y = data2[i]
            sum1 += x
            sum2 += y
            sum1_sq += x * x
            sum2_sq += y * y
            p_sum += x * y
        }

        let n = Float64(data1.size)
        let num = p_sum - (sum1 * sum2 / n)
        let den1 = sqrt((sum1_sq - (sum1 * sum1 / n)) * (sum2_sq - (sum2 * sum2 / n)))

        if (den1 == 0.0) {
            return 0.0
        }
        return num / den1
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }

        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        let mean = sum / Float64(data.size)

        var sum_diff_cubed = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            sum_diff_cubed += diff * diff * diff
        }

        let n = Float64(data.size)
        let stddev = sqrt(variance(data))
        if (stddev == 0.0) {
            return 0.0
        }
        return (sum_diff_cubed / n) / (stddev * stddev * stddev) * (n / (n - 1.0)) * (n / (n - 2.0))
    }

    private static func variance(data: ArrayList<Float64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }

        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        let mean = sum / Float64(data.size)

        var sum_diff_squared = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            sum_diff_squared += diff * diff
        }

        return sum_diff_squared / Float64(data.size - 1)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }

        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        let mean = sum / Float64(data.size)

        var sum_diff_pow4 = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            sum_diff_pow4 += diff * diff * diff * diff
        }

        let n = Float64(data.size)
        let stddev = sqrt(variance(data))
        if (stddev == 0.0) {
            return 0.0
        }

        let numerator = (sum_diff_pow4 / n)
        let denom_pow4 = stddev * stddev * stddev * stddev
        let kurt = numerator / denom_pow4 - 3.0

        // Correct for sample bias
        return kurt * (Float64(data.size - 1) * (data.size - 1)) / 
               ((data.size - 2) * (data.size - 3))
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let sigma_sq = sigma * sigma
        let norm_const = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))

        for (i in 0..data.size) {
            let x = data[i]
            let exponent = -((x - mu) * (x - mu)) / (2.0 * sigma_sq)
            let value = norm_const * exp(exponent)
            result.add(value)
        }

        return result
    }
}

