        if (n < 3) {
            return 0.0
        }

        var sum = 0.0
        for (i in 0..n) {
            sum += data[i]
        }
        let mean = sum / n as Float64

        var sum_sq = 0.0
        for (i in 0..n) {
            sum_sq += (data[i] - mean) * (data[i] - mean)
        }
        let variance = sum_sq / n as Float64
        let stddev = sqrt(variance)

        if (stddev == 0.0) {
            return 0.0
        }

        var sum_cube = 0.0
        for (i in 0..n) {
            sum_cube += (data[i] - mean) * (data[i] - mean) * (data[i] - mean)
