        let n = data.size.toFloat64()
        var sum = 0.0
        var sum_sq = 0.0
        var sum_cu = 0.0

        for (i in 0..data.size) {
            let val = data[i]
            sum += val
            sum_sq += val * val
            sum_cu += val * val * val
        }

        let mean = sum / n
        let m2 = sum_sq / n - (mean * mean)
        let m3 = sum_cu / n - 3.0 * (sum_sq / n) * mean + 2.0 * (mean * mean * mean)

        if (m2 == 0.0) {
            return 0.0
        } else {
            return (m3) / sqrt(m2 * m2 * m2) * (n / (n - 1.0) * (n - 2.0)).sqrt()
        }
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        if (data.size < 4) {
            return 0.0
        }

        let n = data.size.toFloat64()
        var sum = 0.0
        var sum_sq = 0.0
        var sum_qu = 0.0

        for (i in 0..data.size) {
            let val = data[i]
            sum += val
            sum_sq += val * val
            sum_qu += val * val * val * val
        }

        let mean = sum / n
        let m2 = sum_sq / n - (mean * mean)
        let m4 = sum_qu / n - 4.0 * (sum_sq / n) * mean + 6.0 * (sum / n) * (mean * mean) - 3.0 * (mean * mean * mean * mean)

        if (m2 == 0.0) {
            return 0.0
        } else {
            let adjusted = (n * n - 1.0) / ((n - 2.0) * (n - 3.0))
            return (m4 / (m2 * m2)) - 3.0 * adjusted
        }
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let variance = sigma * sigma
        let factor = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793)) // pi approximation

        for (i in 0..data.size) {
            let val = data[i]
            let exponent = -((val - mu) * (val - mu)) / (2.0 * variance)
            result.add(factor * exp(exponent))
        }

        return result
    }
}

