class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        /*
        Calculate the correlation coefficient of two sets of data.
        */
        if (data1.size != data2.size || data1.size == 0) {
            return 0.0
        }

        var sum1 = 0.0
        var sum2 = 0.0
        var sum1_sq = 0.0
        var sum2_sq = 0.0
        var p_sum = 0.0

        for (i in 0..data1.size) {
            let val1 = data1[i]
            let val2 = data2[i]
            sum1 += val1
            sum2 += val2
            sum1_sq += val1 * val1
            sum2_sq += val2 * val2
            p_sum += val1 * val2
        }

        let n = data1.size.toFloat64()
        let num = p_sum - (sum1 * sum2 / n)
        let den1 = sqrt((sum1_sq - (sum1 * sum1 / n)) * (sum2_sq - (sum2 * sum2 / n)))

        if (den1 == 0.0) {
            return 0.0
        }

        return num / den1
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the skewness of a set of data.
        */
        if (data.size == 0) {
            return 0.0
        }

        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        let mean = sum / data.size.toFloat64()

        var variance_sum = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            variance_sum += diff * diff
        }
        let variance = variance_sum / data.size.toFloat64()

        if (variance == 0.0) {
            return 0.0
        }

        let std_dev = sqrt(variance)
        var skew_sum = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            skew_sum += (diff * diff * diff)
        }

        return (skew_sum / data.size.toFloat64()) / (std_dev * std_dev * std_dev)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the kurtosis of a set of data.
        */
        if (data.size == 0) {
            return 0.0
        }

        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i]
        }
        let mean = sum / data.size.toFloat64()

        var variance_sum = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            variance_sum += diff * diff
        }
        let variance = variance_sum / data.size.toFloat64()

        if (variance == 0.0) {
            return 0.0
        }

        let std_dev = sqrt(variance)
        var kurt_sum = 0.0
        for (i in 0..data.size) {
            let diff = data[i] - mean
            kurt_sum += (diff * diff * diff * diff)
        }

        let n = data.size.toFloat64()
        return ((kurt_sum / n) / (std_dev * std_dev * std_dev * std_dev)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        /*
        Calculate the probability density function (PDF) of a set of data under a normal distribution.
        */
        let result = ArrayList<Float64>()
        let sigma_sq = sigma * sigma
        let inv_sqrt_2pi_sigma = 1.0 / (sqrt(2.0 * 3.141592653589793 * sigma_sq))
        let exponent_denom = 2.0 * sigma_sq

        for (i in 0..data.size) {
            let diff = data[i] - mu
            let exponent = -(diff * diff) / exponent_denom
            let pdf_val = inv_sqrt_2pi_sigma * exp(exponent)
            result.add(pdf_val)
        }

        return result
    }
}

