        let n = data.size.toFloat64()
        if (n < 3) {
            return 0.0
        }

        var mean = 0.0
        for (i in 0..<data.size) {
            mean += data[i]
        }
        mean /= n

        var variance = 0.0
        for (i in 0..<data.size) {
            variance += (data[i] - mean) * (data[i] - mean)
        }
        variance /= n

        let std_dev = sqrt(variance)
        if (std_dev == 0.0) {
            return 0.0
        }

        var skew = 0.0
        for (i in 0..<data.size) {
            let z = (data[i] - mean) / std_dev
            skew += z * z * z
        }

        return skew / n
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size.toFloat64()
        if (n < 4) {
            return 0.0
        }

        var mean = 0.0
        for (i in 0..<data.size) {
            mean += data[i]
        }
        mean /= n

        var variance = 0.0
        for (i in 0..<data.size) {
            variance += (data[i] - mean) * (data[i] - mean)
        }
        variance /= n

        let std_dev = sqrt(variance)
        if (std_dev == 0.0) {
            return 0.0
        }

        var kurt = 0.0
        for (i in 0..<data.size) {
            let z = (data[i] - mean) / std_dev
            kurt += z * z * z * z
        }

        return kurt / n - 3.0  // Excess kurtosis
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let inv_sqrt_2pi = 1.0 / sqrt(2.0 * 3.141592653589793)
