        }

        for (i in 0..<data.size) {
            let x = data[i]
            let z = (x - mu) / sigma
            let pdf_val = inv_sqrt_2pi * exp(-0.5 * z * z) / sigma
            result.add(pdf_val)
        }

        return result
    }
}

