    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 3) {
            return 0.0
        }

        // Calculate mean
        var sum = 0.0
        for (i in 0..n) {
            sum += data[i]
        }
        let mean = sum / n as Float64

        // Calculate variance and m3
        var m2 = 0.0 // second moment
        var m3 = 0.0 // third moment
        for (i in 0..n) {
            let dev = data[i] - mean
            let dev2 = dev * dev
            m2 += dev2
            m3 += dev * dev2
        }

        let variance = m2 / n as Float64
        let stdDev = sqrt(variance)

        if (stdDev == 0.0) {
            return 0.0
        }

        // Adjust for sample skewness (unbiased estimator)
        let skew = (n as Float64 / ((n as Float64 - 1.0) * (n as Float64 - 2.0))) * 
                   (m3 / pow(stdDev, 3))
        return skew
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        if (n < 4) {
            return 0.0
        }

        // Calculate mean
        var sum = 0.0
        for (i in 0..n) {
            sum += data[i]
        }
        let mean = sum / n as Float64

        // Calculate moments
        var m2 = 0.0 // second moment
        var m4 = 0.0 // fourth moment
        for (i in 0..n) {
            let dev = data[i] - mean
            let dev2 = dev * dev
            m2 += dev2
            m4 += dev2 * dev2
        }

        let variance = m2 / n as Float64
        let stdDev = sqrt(variance)

        if (stdDev == 0.0) {
