    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let runes = ciphertext.toRuneArray()
        let result = ArrayList<Rune>()
        for (i in 0..runes.size) {
            let c = runes[i]
            if (c >= r'a' && c <= r'z') {
                let shifted = (c - r'a' - shift) % 26
                let adjusted = if (shifted < 0) { shifted + 26 } else { shifted }
                result.add(adjusted + r'a')
            } else if (c >= r'A' && c <= r'Z') {
                let shifted = (c - r'A' - shift) % 26
                let adjusted = if (shifted < 0) { shifted + 26 } else { shifted }
                result.add(adjusted + r'A')
            } else {
                result.add(c)
            }
        }
        return String.fromRuneArray(result.toArray())
    }

    public func vigenere_decipher(ciphertext: String): String {
        let key_runes = this.key.toRuneArray()
        let cipher_runes = ciphertext.toRuneArray()
        let result = ArrayList<Rune>()
        var key_index = 0
        for (i in 0..cipher_runes.size) {
            let c = cipher_runes[i]
            if (key_index >= key_runes.size) {
                key_index = 0
            }
            let key_char = key_runes[key_index]
            let shift = if (key_char >= r'a' && key_char <= r'z') { 
                key_char - r'a' 
            } else { 
                key_char - r'A' 
            }

            if (c >= r'a' && c <= r'z') {
                let shifted = (c - r'a' - shift) % 26
                let adjusted = if (shifted < 0) { shifted + 26 } else { shifted }
                result.add(adjusted + r'a')
                key_index++
            } else if (c >= r'A' && c <= r'Z') {
                let shifted = (c - r'A' - shift) % 26
                let adjusted = if (shifted < 0) { shifted + 26 } else { shifted }
                result.add(adjusted + r'A')
                key_index++
            } else {
                result.add(c)
            }
        }
        return String.fromRuneArray(result.toArray())
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let len = encrypted_text.size
        let rail_pattern = ArrayList<ArrayList<Int64>>()
        for (i in 0..rails) {
            rail_pattern.add(ArrayList<Int64>())
        }

        // Generate the rail pattern indices
        var rail = 0
        var direction = 1
        let indices = ArrayList<Int64>()
        for (i in 0..len) {
            indices.add(rail.toInt64())
            if (rail == 0) {
                direction = 1
            } else if (rail == rails - 1) {
                direction = -1
            }
            rail += direction
        }

        // Count characters per rail
        let counts = ArrayList<Int64>()
        for (i in 0..rails) {
            counts.add(0)
        }
        for (i in 0..len) {
            let r = indices[i]
            counts[r.toInt64()]++
        }

        // Split encrypted text into rails
        let rail_chars = ArrayList<ArrayList<Rune>>()
        var current_pos = 0
        for (i in 0..rails) {
            let count = counts[i.toInt64()]
            let rail_text = ArrayList<Rune>()
            for (j in 0..count) {
                rail_text.add(encrypted_text.toRuneArray()[current_pos])
                current_pos++
            }
            rail_chars.add(rail_text)
        }

        // Reconstruct original text
        let result = ArrayList<Rune>()
        var rail_positions = ArrayList<Int64>()
        for (i in 0..rails) {
            rail_positions.add(0)
        }
        rail = 0
        direction = 1
        for (i in 0..len) {
            let pos = rail_positions[rail.toInt64()]
            result.add(rail_chars[rail.toInt64()][pos.toInt64()])
            rail_positions[rail.toInt64()]++

            if (rail == 0) {
                direction = 1
            } else if (rail == rails - 1) {
                direction = -1
            }
            rail += direction
        }

        return String.fromRuneArray(result.toArray())
    }
