import std.collection.ArrayList

class DecryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        var result = ArrayList<Rune>()
        for (c in ciphertext.runes()) {
            if (c >= r'a' && c <= r'z') {
                let shift_c = (c.toInt() - r'a'.toInt() - (shift % 26) + 26) % 26 + r'a'.toInt()
                result.add(Rune(shift_c.toChar()))
            } else if (c >= r'A' && c <= r'Z') {
                let shift_c = (c.toInt() - r'A'.toInt() - (shift % 26) + 26) % 26 + r'A'.toInt()
                result.add(Rune(shift_c.toChar()))
            } else {
                result.add(c)
            }
        }
        return result.toArray().toRuneString()
    }

    public func vigenere_decipher(ciphertext: String): String {
        var result = ArrayList<Rune>()
        let key_runes = this.key.toRuneArray()
        var key_index = 0

        for (c in ciphertext.runes()) {
            if (c >= r'a' && c <= r'z') {
                let key_rune = if (key_index < key_runes.size) { key_runes[key_index] %% r'a' } else { r'a' }
                let shift = key_rune.toInt() - r'a'.toInt()
                let shift_c = (c.toInt() - r'a'.toInt() - shift + 26) % 26 + r'a'.toInt()
                result.add(Rune(shift_c.toChar()))
                key_index = (key_index + 1) % key_runes.size
            } else if (c >= r'A' && c <= r'Z') {
                let key_rune = if (key_index < key_runes.size) { key_runes[key_index] %% r'A' } else { r'A' }
                let shift = key_rune.toInt() - r'A'.toInt()
                let shift_c = (c.toInt() - r'A'.toInt() - shift + 26) % 26 + r'A'.toInt()
                result.add(Rune(shift_c.toChar()))
                key_index = (key_index + 1) % key_runes.size
            } else {
                result.add(c)
            }
        }
        return result.toArray().toRuneString()
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let len = encrypted_text.length()
        let rail_pattern = ArrayList<Int64>()

        // Generate rail pattern
        var down = false
        var row = 0
        var pattern = ArrayList<Int64>()

        for (i in 0..<len:1) {
            pattern.add(row)
            if (row == 0 || row == rails - 1) {
                down = !down
            }
            row += if (down) { 1 } else { -1 }
        }

        // Create rails array
        var rails_arr = ArrayList<ArrayList<Rune>>()
        for (i in 0..<rails:1) {
            rails_arr.add(ArrayList<Rune>())
        }

        // Assign characters to rails
        var encrypted_runes = encrypted_text.toRuneArray()
        for (i in 0..<len:1) {
            rails_arr[pattern[i]].add(encrypted_runes[i])
        }

        // Reconstruct the original text
        var result = ArrayList<Rune>()
        row = 0
        down = false
        var rail_indices = ArrayList<Int64>()
        for (i in 0..<rails:1) {
            rail_indices.add(0)
        }

        for (i in 0..<len:1) {
            let current_rail = if (row == rails - 1) { rails - 1 } else { 
                if (down) { row } else { rails - 1 - row } 
            }
            result.add(rails_arr[current_rail][rail_indices[current_rail]])
            rail_indices[current_rail] += 1

            if (row == 0) {
                down = true
            } else if (row == rails - 1) {
                down = false
            }
            row += if (down) { 1 } else { -1 }
        }

        return result.toArray().toRuneString()
    }
}

