    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        // Should never happen in valid 8-puzzle
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = this.find_blank(state: state)
        var new_state = ArrayList<ArrayList<Int64>>()
        for (k in 0..3) {
            new_state.add(ArrayList<Int64>(state[k].toRuneArray()))
        }

        switch (direction) {
            case "up" when i > 0 => {
                new_state[i][j] = new_state[i-1][j]
                new_state[i-1][j] = 0
            }
            case "down" when i < 2 => {
                new_state[i][j] = new_state[i+1][j]
                new_state[i+1][j] = 0
            }
            case "left" when j > 0 => {
                new_state[i][j] = new_state[i][j-1]
                new_state[i][j-1] = 0
            }
            case "right" when j < 2 => {
                new_state[i][j] = new_state[i][j+1]
                new_state[i][j+1] = 0
            }
            default => {
                // Invalid move, return original state (though shouldn't happen with proper validation)
                return state
            }
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (i, j) = this.find_blank(state: state)
        var moves = ArrayList<String>()
        if (i > 0) moves.add("up")
        if (i < 2) moves.add("down")
        if (j > 0) moves.add("left")
        if (j < 2) moves.add("right")
        return moves
    }

    public func solve(): ArrayList<String> {
        let mut open_list = ArrayList<ArrayList<ArrayList<Int64>>>()
        let mut path_map = HashMap<String, ArrayList<String>>()
        let mut visited = HashSet<String>()

        let initial_key = this.state_to_key(state: this.initial_state)
        path_map.add(initial_key, ArrayList<String>())
        open_list.add(this.initial_state)
        visited.add(initial_key)

        while (open_list.size > 0) {
            let current_state = open_list[0]
            open_list.remove(at: 0)

            if (this.is_goal_state(state: current_state)) {
                let key = this.state_to_key(state: current_state)
                return path_map[key] ?? ArrayList<String>()
            }

            let possible_moves = this.get_possible_moves(state: current_state)
            for (move in possible_moves) {
                let new_state = this.move(state: current_state, direction: move)
                let new_key = this.state_to_key(state: new_state)

                if (!visited.contains(new_key)) {
                    visited.add(new_key)
                    let mut new_path = ArrayList<String>()
                    let current_key = this.state_to_key(state: current_state)
                    let existing_path = path_map[current_key] ?? ArrayList<String>()
                    for (m in existing_path) {
                        new_path.add(m)
                    }
                    new_path.add(move)
                    path_map.add(new_key, new_path)
                    open_list.add(new_state)
                }
            }
        }

        return ArrayList<String>() // No solution found
    }

    private func state_to_key(state: ArrayList<ArrayList<Int64>>): String {
        var key = ""
        for (i in 0..3) {
            for (j in 0..3) {
                key = key + state[i][j].toString() + ","
            }
        }
        return key
    }

    private func is_goal_state(state: ArrayList<ArrayList<Int64>>): Bool {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] != this.goal_state[i][j]) {
                    return false
                }
            }
        }
        return true
    }
}

