    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = find_blank(state: state)
        let state_copy = deep_copy(state: state)

        match (direction) {
            case "up"    => if (i > 0) { swap(&state_copy, i, j, i-1, j) }
            case "down"  => if (i < 2) { swap(&state_copy, i, j, i+1, j) }
            case "left"  => if (j > 0) { swap(&state_copy, i, j, i, j-1) }
            case "right" => if (j < 2) { swap(&state_copy, i, j, i, j+1) }
        }

        return state_copy
    }

    private func deep_copy(state: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Int64>> {
        let copy = ArrayList<ArrayList<Int64>>()
        for (i in 0..3) {
            let new_row = ArrayList<Int64>()
            for (j in 0..3) {
                new_row.add(state[i][j])
            }
            copy.add(new_row)
        }
        return copy
    }

    private func swap(state: &ArrayList<ArrayList<Int64>>, i1: Int64, j1: Int64, i2: Int64, j2: Int64) {
        let temp = state[i1][j1]
        state[i1].set(j1, state[i2][j2])
        state[i2].set(j2, temp)
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let (i, j) = find_blank(state: state)
        let moves = ArrayList<String>()

        if (i > 0) { moves.add("up") }
        if (i < 2) { moves.add("down") }
        if (j > 0) { moves.add("left") }
        if (j < 2) { moves.add("right") }

        return moves
    }

    public func solve(): ArrayList<String> {
        import std.collection.HashMap
        import std.collection.HashSet

        struct Node {
            let state: ArrayList<ArrayList<Int64>>
            let path: ArrayList<String>
            let depth: Int64
        }

        let open_set = ArrayList<Node>()
        let visited = HashSet<ArrayList<ArrayList<Int64>>>()

        open_set.add(Node(state: initial_state, path: ArrayList<String>(), depth: 0))

        while (open_set.size > 0) {
            sort(open_set, {l: Node, r: Node => l.depth < r.depth})  // Simple BFS with sorting for fair evaluation
            let current = open_set.remove(at: 0)

            if (current.state == goal_state) {
                return current.path
            }

            if (visited.contains(current.state)) { continue }
            visited.add(current.state)

            let possible_moves = get_possible_moves(state: current.state)
            for (move in possible_moves) {
                let new_state = move(state: current.state, direction: move)
                let new_path = deep_copy_path(path: current.path)
                new_path.add(move)

                if (!visited.contains(new_state)) {
                    open_set.add(Node(state: new_state, path: new_path, depth: current.depth + 1))
                }
            }
        }

        return ArrayList<String>()  // No solution found
    }

    private func deep_copy_path(path: ArrayList<String>): ArrayList<String> {
        let copy = ArrayList<String>()
        for (move in path) {
            copy.add(move)
        }
        return copy
    }
}

