            for (m in moves) {
                let new_state = this.move(state: current, direction: m)
                let new_key = this.state_to_key(state: new_state)

                if (!came_from.contains(new_key)) {
                    open_list.add(ArrayList<ArrayList<Int64>>([new_state]), at: open_list.size)
