                email["state"] = "read" as Any
                // Return a copy to maintain immutability of stored emails
                let result = HashMap<String, Any>()
                for (key in email.keys) {
                    result[key] = email[key]!
                }
                return result
            }
        }
        panic("No unread emails")
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        return (this.get_occupied_size() + size) > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var total = 0 as Int64
        for (i in 0..inbox.size) {
            total = total + (inbox[i]["size"] as Int64)
        }
        return total
    }

    public func clear_inbox(size: Int64): Unit {
        if (this.capacity - this.get_occupied_size() >= size) {
            return
        }

        // Sort emails by time (oldest first)
        let emails = inbox.toRuneArray() // Temporary array for sorting
        // Create a mutable copy for sorting
        let mutable_emails = ArrayList<HashMap<String, Any>>()
        for (i in 0..inbox.size) {
            mutable_emails.add(inbox[i])
        }

        // Sort by time (convert time string to timestamp for proper comparison)
        let key_func = {email: HashMap<String, Any> => 
            DateTime.parse(email["time"] as String, "yyyy-MM-dd HH:mm:ss").toTimestamp()
        }
        sort(mutable_emails, key: key_func)

        var remaining_needed = size - (this.capacity - this.get_occupied_size())
        while (remaining_needed > 0 && mutable_emails.size > 0) {
            let oldest = mutable_emails.remove(at: 0)
            remaining_needed = remaining_needed - (oldest["size"] as Int64)
        }

        this.inbox = mutable_emails
    }
}

