        let plainRunes = plaintext.toRuneArray()
        for (r in plainRunes) {
            let originalPos = r - r'a'
            let newPos = (originalPos + shift) % 26
            let shiftedRune = r'a' + newPos
            result.add(shiftedRune)
        }
        return String.fromRuneArray(result.toArray())
    }

    public func vigenere_cipher(plain_text: String): String {
