        let plainRunes = plain_text.toRuneArray()
        let keyRunes = this.key.toRuneArray()
        var keyIndex = 0
        for (r in plainRunes) {
            let originalPos = r - r'a'
            let keyChar = keyRunes[keyIndex % keyRunes.size]
            let keyShift = keyChar - r'a'
            let newPos = (originalPos + keyShift) % 26
            let shiftedRune = r'a' + newPos
            result.add(shiftedRune)
            keyIndex++
        }
        return String.fromRuneArray(result.toArray())
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if rails <= 1 {
            return plain_text
        }

        // Create rail matrix
        let chars = plain_text.toRuneArray()
