        var railMatrix = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            railMatrix.add(ArrayList<Rune>())
            for (j in 0..railSize) {
                railMatrix[i].add(r'\0')
            }
        }

        // Fill rail matrix
        var dirDown = false
        var row = 0
        for (i in 0..railSize) {
            railMatrix[row].set(i, chars[i])
            if (row == 0) || (row == rails - 1) {
                dirDown = !dirDown
            }
            row += dirDown ? 1 : -1
        }

        // Read rail matrix
        var result = ArrayList<Rune>()
        for (i in 0..rails) {
            for (j in 0..railSize) {
                let r = railMatrix[i].get(j)
                if r != r'\0' {
                    result.add(r)
                }
            }
        }
        return String.fromRuneArray(result.toArray())
    }
