        var key_index = 0
        for (r in plain_text.runes()) {
            var shift: Int64 = 0
            if (key_index < this.key.size) {
                let key_char = this.key[key_index]
                if (key_char >= r'a' && key_char <= r'z') {
                    shift = key_char - r'a'
                } else if (key_char >= r'A' && key_char <= r'Z') {
                    shift = key_char - r'A'
                }
            }
            if (r >= r'a' && r <= r'z') {
                let shifted = r'a' + (r - r'a' + shift) % 26
                result.add(shifted >= r'z' ? shifted - 26 : shifted)
                key_index = (key_index + 1) % this.key.size
            } else if (r >= r'A' && r <= r'Z') {
