        let key_runes = this.key.toRuneArray()
        var key_index = 0

        for (c in plain_text.runes()) {
            var shift = 0
            if (key_index >= key_runes.size) {
                key_index = 0
            }
            let key_char = key_runes[key_index]
            if (c >= r'a' && c <= r'z') {
                shift = (key_char - r'a') % 26
                let offset = (c - r'a' + shift) % 26
                let new_char = r'a' + offset
                result.add(new_char)
                key_index++
            } else if (c >= r'A' && c <= r'Z') {
                shift = (key_char - r'A') % 26
                let offset = (c - r'A' + shift) % 26
                let new_char = r'A' + offset
                result.add(new_char)
                key_index++
            } else {
                result.add(c)
            }
        }
        let runes = result.toRuneArray()
        return String.fromRuneArray(runes)
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        // Create an array of arrays to represent each rail
        var rail_arrays = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails) {
            rail_arrays.add(ArrayList<Rune>())
        }

        var current_rail = 0
        var going_down = false

        for (c in plain_text.runes()) {
            rail_arrays[current_rail].add(c)
            if (current_rail == 0 || current_rail == rails - 1) {
                going_down = !going_down
            }
            current_rail += going_down ? 1 : -1
        }

        // Read off the characters in order
        var result = ArrayList<Rune>()
        for (rail in rail_arrays) {
            for (c in rail.runes()) {
                result.add(c)
            }
        }

        let runes = result.toRuneArray()
        return String.fromRuneArray(runes)
    }
}

import std.collection.ArrayList

class EncryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var result = ArrayList<Rune>()
        for (r in plaintext.runes()) {
            if (r >= r'a' && r <= r'z') {
                let shifted = ((r - r'a' + shift) % 26 + 26) % 26 + r'a'
                result.add(shifted)
            } else if (r >= r'A' && r <= r'Z') {
                let shifted = ((r - r'A' + shift) % 26 + 26) % 26 + r'A'
                result.add(shifted)
            } else {
                result.add(r)
            }
        }
        return result.map({c: Rune => String.fromRune(c)}).join("")
    }

    public func vigenere_cipher(plain_text: String): String {
        var result = ArrayList<Rune>()
        let key_runes = this.key.toRuneArray()
        var key_index: Int64 = 0
        for (r in plain_text.runes()) {
            if (r >= r'a' && r <= r'z') {
                let key_char = key_runes[key_index % key_runes.size] - r'a'
                let shifted = (r - r'a' + key_char) % 26 + r'a'
                result.add(shifted)
                key_index++
            } else if (r >= r'A' && r <= r'Z') {
                let key_char = key_runes[key_index % key_runes.size] - r'A'
                let shifted = (r - r'A' + key_char) % 26 + r'A'
                result.add(shifted)
                key_index++
            } else {
                result.add(r)
            }
        }
        return result.map({c: Rune => String.fromRune(c)}).join("")
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if (rails <= 1) {
            return plain_text
        }

        // Create rails
        let rail_lists = ArrayList<ArrayList<Rune>>()
        for (i in 0..rails:1) {
            rail_lists.add(ArrayList<Rune>())
        }

        // Fill rails
        var current_rail: Int64 = 0
        var going_down: Bool = true
        for (r in plain_text.runes()) {
            rail_lists[current_rail].add(r)
            if (going_down) {
                current_rail++
                if (current_rail == rails - 1) {
                    going_down = false
                }
            } else {
                current_rail--
                if (current_rail == 0) {
                    going_down = true
                }
            }
        }

        // Read rails
        var result = ArrayList<Rune>()
        for (rail in rail_lists) {
            for (r in rail) {
                result.add(r)
            }
        }

        return result.map({c: Rune => String.fromRune(c)}).join("")
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2]) // Maps to operator order: +,-,*,/, (, ), %, 
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        */
        let infix = transform(expression: expression)
        prepare(expression: infix)
        let postfix = this.postfix_stack
        var operand_stack: ArrayList<Decimal> = ArrayList<Decimal>()

        for (i in 0..postfix.size) {
            let token = postfix[i]
            if (!ExpressionCalculator.is_operator(c: token)) {
                operand_stack.add(Decimal.parse(token))
            } else {
                let right = operand_stack.remove(at: operand_stack.size - 1)
                let left = operand_stack.remove(at: operand_stack.size - 1)
                let result = ExpressionCalculator._calculate(first_value: left, second_value: right, current_op: token)
                operand_stack.add(result)
            }
        }

        return operand_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        /*
        Convert infix expression to postfix notation using shunting-yard algorithm
        */
        this.postfix_stack = ArrayList<String>()
        let operator_stack: ArrayList<String> = ArrayList<String>()
        let op_order: HashMap<String, Int64> = HashMap<String, Int64>([
            ("+", 1), ("-", 1), ("*", 2), ("/", 2), ("%", 3), 
            ("(", 0), (")", 0)
        ])

        var i = 0
        while (i < expression.size) {
            let c = expression[i].toString()
            if (c.matches(Regex("[0-9]"))) {
                var num_str = c
                while (i + 1 < expression.size && expression[i + 1].toString().matches(Regex("[0-9]"))) {
                    i += 1
                    num_str += expression[i].toString()
                }
                postfix_stack.add(num_str)
            } else if (ExpressionCalculator.is_operator(c: c)) {
                while (operator_stack.size > 0 && 
                       ExpressionCalculator.is_operator(c: operator_stack[operator_stack.size - 1]) && 
                       (this.compare(cur: c, peek: operator_stack[operator_stack.size - 1]) || 
                        !(c == "(" && operator_stack[operator_stack.size - 1] == ")"))) {
                    postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                operator_stack.add(c)
            } else if (c == "(") {
                operator_stack.add(c)
            } else if (c == ")") {
                while (operator_stack.size > 0 && operator_stack[operator_stack.size - 1] != "(") {
                    postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                if (operator_stack.size > 0) {
                    operator_stack.remove(at: operator_stack.size - 1) // Remove '('
                }
            }
            i += 1
        }

        while (operator_stack.size > 0) {
            postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        */
        let operators = HashSet<String>(["+", "-", "*", "/", "(", ")", "%"])
        return operators.contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare operator precedence using pre-defined priority mapping
        */
        let precedence: HashMap<String, Int64> = HashMap<String, Int64>([
            ("+", 1), ("-", 1), ("*", 2), ("/", 2), ("%", 3)
        ])

        if (!ExpressionCalculator.is_operator(c: peek)) {
            return true // Special case for ')'
        }

        return precedence.get(cur) ?? 0 >= precedence.get(peek) ?? 0
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        */
        return match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => Decimal(0) // Should never happen with proper input
        }
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion (remove spaces)
        */
        var result = ""
        for (i in 0..expression.size) {
            let c = expression[i]
            if (c != ' ') {
                result += c.toString()
            }
        }
        return result
    }
}

