class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2]) // Maps operators to priorities: +(3), -(3), *(2), /(2), %(2), ((0), )(1)
    }

    public func calculate(expression: String): Float64 {
        let transformed = ExpressionCalculator.transform(expression)
        self.prepare(expression: transformed)

        let ops = ArrayList<String>()
        let vals = ArrayList<Decimal>()

        for token in self.postfix_stack {
            if ExpressionCalculator.is_operator(c: token) {
                let val2 = vals.remove(at: vals.size - 1)
                let val1 = vals.remove(at: vals.size - 1)
                let result = ExpressionCalculator._calculate(first_value: val1, second_value: val2, current_op: token)
                vals.add(result)
            } else {
                let decimal_val = Decimal.fromString(token) ?? Decimal.zero()
                vals.add(decimal_val)
            }
        }

        return vals[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        let tokens = expression.split(by: Regex(r"\s+"))
        let ops = ArrayList<String>()
        self.postfix_stack.clear()

        for token in tokens {
            if token == "(" {
                ops.add(token)
            } else if token == ")" {
                while ops.size > 0 && ops[ops.size - 1] != "(" {
                    self.postfix_stack.add(ops.remove(at: ops.size - 1))
                }
                ops.remove(at: ops.size - 1) // Remove '('
            } else if ExpressionCalculator.is_operator(c: token) {
                while ops.size > 0 && ops[ops.size - 1] != "(" && 
                      ExpressionCalculator.compare(cur: token, peek: ops[ops.size - 1]) {
                    self.postfix_stack.add(ops.remove(at: ops.size - 1))
                }
                ops.add(token)
            } else {
                self.postfix_stack.add(token)
            }
        }

        while ops.size > 0 {
            self.postfix_stack.add(ops.remove(at: ops.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        return ["+", "-", "*", "/", "(", ")", "%"].contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let op_index = { op: String => 
            match(op) {
                case "+" => 0
                case "-" => 1
                case "*" => 2
                case "/" => 3
                case "%" => 4
                case "(" => 5
                case ")" => 6
                case _ => 7
            }
        }()
        let peer_index = { op: String => 
            match(op) {
                case "+" => 0
                case "-" => 1
                case "*" => 2
                case "/" => 3
                case "%" => 4
                case "(" => 5
                case ")" => 6
                case _ => 7
            }
        }()

        let current_priority = self.operat_priority[op_index(cur)]
        let peer_priority = self.operat_priority[peer_index(peek)]

        return current_priority >= peer_priority
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match(current_op) {
            case "+" => return first_value.add(second_value)
            case "-" => return first_value.subtract(second_value)
            case "*" => return first_value.multiply(second_value)
            case "/" => return first_value.divide(second_value)
            case "%" => return first_value.modulo(second_value)
            case _ => return Decimal.zero()
        }
    }

    public static func transform(expression: String): String {
        let regex = Regex(r"\s+")
        return regex.replace(in: expression, with: "")
    }
}

