    }

    public func calculate(expression: String): Float64 {
        let prepared = transform(expression: expression)
        prepare(expression: prepared)

        let op_stack = ArrayList<String>()
        let num_stack = ArrayList<Decimal>()

        for (token in postfix_stack) {
            if (ExpressionCalculator.is_operator(c: token)) {
                if (num_stack.size < 2) {
                    throw "Invalid expression"
                }
                let right = num_stack.remove(at: num_stack.size - 1)
                let left = num_stack.remove(at: num_stack.size - 1)
                let result = ExpressionCalculator._calculate(left, right, token)
                num_stack.add(result)
            } else {
                // Convert string to Decimal (assuming valid numeric input)
                let num = Decimal(token) ?? 0.0
                num_stack.add(num)
            }
        }

        if (num_stack.size != 1 || !op_stack.isEmpty) {
            throw "Invalid expression"
        }

        return num_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        let tokens = expression.split(Regex(r"\s*")) // Remove all whitespace
        let operator_stack = ArrayList<String>()

        for (token in tokens) {
            if (ExpressionCalculator.is_operator(c: token)) {
                while (!operator_stack.isEmpty && 
                       operator_stack[operator_stack.size - 1] != "(" && 
                       (compare(operator_stack[operator_stack.size - 1], token) || 
                        (operator_stack[operator_stack.size - 1] != "(" && token != ")"))) {
                    postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                }
                if (token == ")") {
                    while (operator_stack[operator_stack.size - 1] != "(") {
                        postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
                    }
                    operator_stack.remove(at: operator_stack.size - 1) // Remove '('
                } else {
                    operator_stack.add(token)
                }
            } else {
                postfix_stack.add(token)
            }
        }

        while (!operator_stack.isEmpty) {
            postfix_stack.add(operator_stack.remove(at: operator_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        match (c) {
            case "+" => true
            case "-" => true
            case "*" => true
            case "/" => true
            case "(" => true
            case ")" => true
            case "%" => true
            case _ => false
        }
    }

    public func compare(cur: String, peek: String): Bool {
