        let priority_map = HashMap<String, Int64>([
            ("(", 0),
            ("*", 1),
            ("/", 2),
            ("%", 3),
            (")", 4),
            ("+", 5),
            ("-", 6),
            ("$", 7) // hypothetical end marker
        ])

        let cur_prio = priority_map.get(cur) ?? 7
        let peek_prio = priority_map.get(peek) ?? 7

        return operat_priority[cur_prio.toInt()] >= operat_priority[peek_prio.toInt()]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => throw "Unknown operator"
        }
    }

    public static func transform(expression: String): String {
        let stripped = expression.replaceAll(Regex(r"\s+"), "")
        return stripped
    }
}

