        self.prepare(expression: transformed)

        let operator_stack: ArrayList<String> = ArrayList<String>()
        let output: ArrayList<Decimal> = ArrayList<Decimal>()

        for (i in 0..postfix_stack.size) {
            let token = postfix_stack[i]

            if !ExpressionCalculator.is_operator(c: token) && token != "(" && token != ")" {
                output.add(Decimal(token)!)
            } else if token == "(" {
                operator_stack.add(token)
            } else if token == ")" {
                while operator_stack[operator_stack.size-1] != "(" {
                    let op = operator_stack.remove(at: operator_stack.size-1)
                    let second = output.remove(at: output.size-1)
                    let first = output.remove(at: output.size-1)
                    let result = ExpressionCalculator._calculate(first_value: first, second_value: second, current_op: op)
                    output.add(result)
                }
                operator_stack.remove(at: operator_stack.size-1) // Remove "("
            } else { // Operator
                while operator_stack.size > 0 && 
                      operator_stack[operator_stack.size-1] != "(" && 
                      self.compare(cur: token, peek: operator_stack[operator_stack.size-1]) {
