                    let second = output.remove(at: output.size-1)
                    let first = output.remove(at: output.size-1)
                    let result = ExpressionCalculator._calculate(first_value: first, second_value: second, current_op: op)
                    output.add(result)
                }
                operator_stack.add(token)
            }
        }

        while operator_stack.size > 0 {
            let op = operator_stack.remove(at: operator_stack.size-1)
            if op != "(" && op != ")" {
                let second = output.remove(at: output.size-1)
                let first = output.remove(at: output.size-1)
                let result = ExpressionCalculator._calculate(first_value: first, second_value: second, current_op: op)
