import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.sort.*

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>
    let operator_order: HashMap<String, Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
        // Map operators to their priority index (+, -, *, /, (, ), %)
        operator_order = HashMap<String, Int64>([
            ("+", 1), ("-", 1), 
            ("*", 2), ("/", 2), 
            ("%", 2), 
            ("(", 0), (")", -1)
        ])
    }

    public func calculate(expression: String): Float64 {
        let cleaned = transform(expression: expression)
        prepare(expression: cleaned)
        return eval_postfix()
    }

    private func eval_postfix(): Float64 {
        let stack = ArrayList<Decimal>()

        for (token in postfix_stack) {
            if (self.is_operator(c: token)) {
                let b = stack.remove(at: stack.size - 1)
                let a = stack.remove(at: stack.size - 1)
                let result = self._calculate(first_value: a, second_value: b, current_op: token)
                stack.add(result)
            } else {
                stack.add(Decimal.fromString(token) ?? Decimal(0))
            }
        }

        return Decimal.toFloat64(stack[0])
    }

    public func prepare(expression: String): Unit {
        let tokens = expression.split(Regex.fromString("[\\s+]*"))
        let stack = ArrayList<String>()
        postfix_stack.clear()

        for (token in tokens) {
            if (self.is_operator(c: token)) {
                while (!stack.isEmpty() && 
                       (this.compare(cur: token, peek: stack[stack.size - 1])) && 
                       token != ")") {
                    let op = stack.remove(at: stack.size - 1)
                    if (op != "(") {
                        postfix_stack.add(op)
                    }
                }
                if (token != ")") {
                    stack.add(token)
                } else {
                    stack.remove(at: stack.size - 1) // pop '('
                }
            } else {
                postfix_stack.add(token)
            }
        }

        while (!stack.isEmpty()) {
            let op = stack.remove(at: stack.size - 1)
            if (op != "(") {
                postfix_stack.add(op)
            }
        }
    }

    public static func is_operator(c: String): Bool {
        let operators = ["+", "-", "*", "/", "(", ")", "%"]
        return operators.contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_priority = operator_order.get(cur) ?? -1
        let peek_priority = operator_order.get(peek) ?? -1

        if (peek == "(") {
            return false
        }
        if (cur == ")") {
            return false
        }
