import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList
import std.collection.HashMap
import std.collection.Stack

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>
    let precedence_map: HashMap<String, Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2]) // Maps to operators in order +, -, *, /, (, ), %, space

        // Initialize precedence map (operator -> index in operat_priority)
        precedence_map = HashMap<String, Int64>()
        let operators = ["+", "-", "*", "/", "(", ")", "%"]
        for (i, op) in operators.enumerate() {
            precedence_map.add(op, Int64(i))
        }
    }

    public func calculate(expression: String): Float64 {
        let postfix = transform_to_postfix(ExpressionCalculator.transform(expression))
        let stack = Stack<Decimal>()

        for token in postfix.split(" ") {
            if (ExpressionCalculator.is_operator(token)) {
                let second = stack.pop().getOrThrow()
                let first = stack.pop().getOrThrow()
                let result = ExpressionCalculator._calculate(first, second, token)
                stack.push(result)
            } else {
                stack.push(Decimal(token).getOrThrow())
            }
        }

        return stack.pop().getOrThrow().toFloat64().getOrThrow()
    }

    public func prepare(expression: String): Unit {
        // This method is essentially handled by transform_to_postfix
        // The example comment seems to show postfix notation which is what calculate() expects
    }

    public static func is_operator(c: String): Bool {
        let ops = ["+", "-", "*", "/", "(", ")", "%"]
        for op in ops {
            if (op == c) {
                return true
            }
        }
        return false
    }

    public func compare(cur: String, peek: String): Bool {
        if (!ExpressionCalculator.is_operator(cur) || !ExpressionCalculator.is_operator(peek)) {
            return false
        }

        let cur_idx = precedence_map[cur].getOrThrow()
        let peek_idx = precedence_map[peek].getOrThrow()

        // For associativity (left to right for same precedence)
        // Return true if current has >= precedence than peek
        return operat_priority[cur_idx] >= operat_priority[peek_idx]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => second_value + first_value
            case "-" => second_value - first_value
            case "*" => second_value * first_value
            case "/" => second_value / first_value
            case "%" => second_value % first_value
            case _ => Decimal("0").getOrThrow()
        }
    }

    public static func transform(expression: String): String {
        // Remove all whitespace
        var result = ""
        for c in expression {
            if (c != r' ') {
                result = result + String(c)
            }
        }
        return result
    }

    private func transform_to_postfix(expression: String): String {
        let operator_stack = Stack<String>()
        var output = ""
        var i = 0

        while (i < expression.size) {
            let c = expression[i]

            if (c >= r'0' && c <= r'9') {
                // Number - collect all consecutive digits
                var num = String(c)
                while (i + 1 < expression.size && (expression[i+1] >= r'0' && expression[i+1] <= r'9' || expression[i+1] == r'.')) {
                    i = i + 1
                    num = num + String(expression[i])
                }
                output = output + num + " "
            } else if (c == r'(') {
                operator_stack.push(String(c))
            } else if (c == r')') {
                while (!operator_stack.isEmpty() && operator_stack.peek() != "(") {
                    output = output + operator_stack.pop().getOrThrow() + " "
                }
                operator_stack.pop() // Remove the '('
            } else if (ExpressionCalculator.is_operator(String(c))) {
                let op = String(c)
                while (!operator_stack.isEmpty() && operator_stack.peek() != "(" && 
                       compare(operator_stack.peek(), op)) {
                    output = output + operator_stack.pop().getOrThrow() + " "
                }
                operator_stack.push(op)
            }
            i = i + 1
        }

        // Pop remaining operators
        while (!operator_stack.isEmpty()) {
            output = output + operator_stack.pop().getOrThrow() + " "
        }

        return output
    }
}

