class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([
            0,    // (default)
            3,    // *
            2,    // /
            1,    // +
            -1,   // (
            1,    // -
            0,    // )
            2     // %
        ])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression: transform(expression: expression))
        let temp_stack = ArrayList<Decimal>()
        let op_map = HashMap<String, Int64>([
            ("+", 1), ("-", 2), ("*", 3), 
            ("/", 4), ("%", 5)
        ])

        for element in postfix_stack {
            if !ExpressionCalculator.is_operator(c: element) {
                temp_stack.add(Decimal(element) ?? Decimal("0"))
            } else {
                let second_value = temp_stack.remove(at: temp_stack.size - 1)
                let first_value = temp_stack.remove(at: temp_stack.size - 1)
                let result = ExpressionCalculator._calculate(
                    first_value: first_value,
                    second_value: second_value,
                    current_op: element
                )
                temp_stack.add(result)
            }
        }

        return temp_stack[0].toFloat64() ?? 0.0
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let op_stack = ArrayList<String>()
        let op_precedence = HashMap<String, Int64>([
            ("+", 1), ("-", 1), ("*", 2), 
            ("/", 2), ("%", 2)
        ])

        var i = 0
        while (i < expression.size) {
            let char = expression[i].toString()

            if char.matches(Regex("^[0-9]$")) {
                let num = StringBuilder()
                while (i < expression.size && expression[i].matches(Regex("^[0-9]$"))) {
                    num.append(expression[i])
                    i += 1
                }
                postfix_stack.add(num.toString())
                continue
            }

            if ExpressionCalculator.is_operator(c: char) {
                while (!op_stack.isEmpty && 
                      !(char == "(" && op_stack[op_stack.size - 1] == ")") &&
                      (op_precedence.get(char) ?? 0) <= (op_precedence.get(op_stack[op_stack.size - 1]) ?? 0)) {
                    postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                }
                op_stack.add(char)
            } else if char == "(" {
                op_stack.add(char)
            } else if char == ")" {
                while (op_stack[op_stack.size - 1] != "(") {
                    postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
                }
                op_stack.remove(at: op_stack.size - 1) // Remove '('
            }
            i += 1
        }

        while (!op_stack.isEmpty) {
            postfix_stack.add(op_stack.remove(at: op_stack.size - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        let ops = HashSet<String>(["+", "-", "*", "/", "(", ")", "%"])
        return ops.contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let op_precedence = HashMap<String, Int64>([
            ("+", 1), ("-", 1), ("*", 2), 
            ("/", 2), ("%", 2), ("(", -1), (")", 0)
        ])
        return (op_precedence.get(cur) ?? 0) >= (op_precedence.get(peek) ?? 0)
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => Decimal("0")
        }
    }

    public static func transform(expression: String): String {
        let transformed = StringBuilder()
        let op_chars = HashSet<Rune>([r'+', r'-', r'*', r'/', r'(', r')', r'%'])

        var i = 0
        while (i < expression.size) {
            if expression[i].toString() == " " {
                i += 1
                continue
            }

            if op_chars.contains(expression[i]) {
                transformed.append(expression[i].toString())
            } else {
                let num = StringBuilder()
                while (i < expression.size && 
                      !(op_chars.contains(expression[i]) || expression[i].toString() == " ")) {
                    num.append(expression[i])
                    i += 1
                }
                transformed.append(num.toString())
                continue
            }
            i += 1
        }

        return transformed.toString()
    }
}

