        let infix = self.transform(expression: expression)
        self.prepare(expression: infix)
        let postfix = self.convertToPostfix()
        return self.evaluatePostfix(postfix: postfix)
    }

    private func convertToPostfix() -> String {
        let output = ArrayList<String>()
        let operator_stack = ArrayList<String>()

        for token in self.postfix_stack {
            if !ExpressionCalculator.is_operator(c: token) && token != "(" && token != ")" {
                output.add(token)
            } else if token == "(" {
                operator_stack.add(token)
