import std.collection.ArrayList
import std.option.Option
import std.option.None
import std.option.Some

class GomokuGame {
    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board_size || col < 0 || col >= board_size || board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        current_player = if (current_player == "X") { "O" } else { "X" }
        return true
    }

    public func check_winner(): Option<String> {
        for (i in 0..board_size) {
            for (j in 0..board_size) {
                if (board[i][j] != " ") {
                    if (_check_five_in_a_row(i, j, (1, 0))) { return Some(board[i][j]) }  // horizontal
                    if (_check_five_in_a_row(i, j, (0, 1))) { return Some(board[i][j]) }  // vertical
                    if (_check_five_in_a_row(i, j, (1, 1))) { return Some(board[i][j]) }  // diagonal right
                    if (_check_five_in_a_row(i, j, (1, -1))) { return Some(board[i][j]) } // diagonal left
                }
            }
        }
        return None<String>()
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let symbol = board[row][col]
        var count = 1

        // Check positive direction
        var r = row + dx
        var c = col + dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == symbol) {
            count += 1
            if (count >= 5) { return true }
            r += dx
            c += dy
        }

        // Check negative direction
        r = row - dx
        c = col - dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == symbol) {
            count += 1
            if (count >= 5) { return true }
            r -= dx
            c -= dy
        }

        return false
    }
}

