import std.collection.HashMap

class Hotel {
    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        let available_count = this.available_rooms.get(room_type) ?? 0

        if (available_count == 0) {
            // Check if room_type exists at all (even with 0 available)
            if (!this.available_rooms.contains(room_type)) {
                return "false"
            } else {
                return "0"
            }
        }

        if (room_number > available_count) {
            return available_count.toString()
        }

        // Initialize nested HashMap if doesn't exist
        if (!this.booked_rooms.contains(room_type)) {
            this.booked_rooms.add(room_type, HashMap<String, Int64>())
        }

        // Update booked_rooms
        let guest_booking = this.booked_rooms[room_type].get(name) ?? 0
        this.booked_rooms[room_type].add(name, guest_booking + room_number)

        // Update available_rooms
        this.available_rooms.add(room_type, available_count - room_number)

        return "Success!"
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if (!this.booked_rooms.contains(room_type)) {
            return false
        }

        let guest_booking = this.booked_rooms[room_type].get(name)
        if (guest_booking == None<Int64>()) {
            return false
        }

        let booked_count = guest_booking.getOrThrow()
        if (room_number > booked_count) {
            return false
        }

        if (room_number == booked_count) {
            // Remove the guest entry completely
            this.booked_rooms[room_type].remove(name)
            // Clean up empty room types
