                    let remaining = avail - room_number
                    this.available_rooms.remove(room_type)
                    if (remaining > 0) {
                        this.available_rooms.add(room_type, remaining)
                    }

                    let guest_map = this.booked_rooms.get(room_type)
                    match (guest_map) {
                        case None<HashMap<String, Int64>> => {
                            let new_map = HashMap<String, Int64>([(name, room_number)])
                            this.booked_rooms.add(room_type, new_map)
                        }
                        case Some<HashMap<String, Int64>>(map) => {
                            let current = match (map.get(name)) {
                                case None<Int64> => 0
                                case Some<Int64>(num) => num
                            }
                            map.remove(name)
                            let new_num = current + room_number
                            map.add(name, new_num)
                            this.booked_rooms.remove(room_type)
                            this.booked_rooms.add(room_type, map)
                        }
                    }
                    return "Success!"
                } else {
                    return avail.toString()
                }
            }
        }
    }

