                    guest_map.remove(name)
                    if (remaining > 0) {
                        guest_map.add(name, remaining)
                    }
                    this.booked_rooms.remove(room_type)
                    this.booked_rooms.add(room_type, guest_map)
                    return true
                } else {
                    return false
                }
            }
