import std.collection.HashMap

class Hotel {
    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        // Check if room type exists
        let available_option = this.available_rooms.get(room_type)
        let available = match (available_option) {
            case Some<Int64>(count) => count
            case None<Int64> => {
                return "false"
            }
        }

        if (room_number > available) {
            if (available == 0) {
                return "false"
            } else {
                return available.toString()
            }
        }

        // Update available rooms
        this.available_rooms.add(room_type, available - room_number)

        // Update booked rooms
        let guest_rooms_option = this.booked_rooms.get(room_type)
        match (guest_rooms_option) {
            case Some<HashMap<String, Int64>>(guest_rooms) => {
                let existing_count_option = guest_rooms.get(name)
                match (existing_count_option) {
                    case Some<Int64>(existing_count) => {
                        guest_rooms.add(name, existing_count + room_number)
                    }
                    case None<Int64> => {
                        guest_rooms.add(name, room_number)
                    }
                }
            }
            case None<HashMap<String, Int64>> => {
                let new_guest_rooms = HashMap<String, Int64>([(name, room_number)])
                this.booked_rooms.add(room_type, new_guest_rooms)
            }
        }

        return "Success!"
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        let booked_rooms_option = this.booked_rooms.get(room_type)
        match (booked_rooms_option) {
            case None<HashMap<String, Int64>> => {
                return false
            }
            case Some<HashMap<String, Int64>>(guest_rooms) => {
                let existing_count_option = guest_rooms.get(name)
                match (existing_count_option) {
                    case None<Int64> => {
                        return false
                    }
                    case Some<Int64>(existing_count) => {
                        if (room_number > existing_count) {
                            return false
                        }

                        if (room_number == existing_count) {
                            guest_rooms.remove(name)
                            if (guest_rooms.size == 0) {
                                this.booked_rooms.remove(room_type)
                            }
                        } else {
                            guest_rooms.add(name, existing_count - room_number)
                        }

                        return true
                    }
                }
            }
        }
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        let available_option = this.available_rooms.get(room_type)
        let available = match (available_option) {
            case Some<Int64>(count) => count
            case None<Int64> => 0
        }

        this.available_rooms.add(room_type, available + room_number)
    }

    public func get_available_rooms(room_type: String): Int64 {
        let available_option = this.available_rooms.get(room_type)
        return match (available_option) {
            case Some<Int64>(count) => count
            case None<Int64> => 0
        }
    }
}

