import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            var lower = 0
            var upper = x.size - 1

            // Find the interval containing xi
            while (lower < upper) {
                let mid = (lower + upper) / 2
                if (x[mid] < xi) {
                    lower = mid + 1
                } else {
                    upper = mid
                }
            }

            // Handle boundary cases
            if (lower == 0) {
                result.add(y[0])
                continue
            }
            if (lower == x.size) {
                result.add(y[y.size - 1])
                continue
            }

            // Extract the two surrounding points
            let x0 = x[lower - 1]
            let x1 = x[lower]
            let y0 = y[lower - 1]
            let y1 = y[lower]

            // Linear interpolation formula
            let t = (xi - x0) / (x1 - x0)
            let yi = y0 + t * (y1 - y0)
            result.add(yi)
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()

        // Interpolate for each (xi, yi) pair
        for (i in 0..x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // Find x interval (same as in 1D case)
            var x_lower = 0
            var x_upper = x.size - 1
            while (x_lower < x_upper) {
                let mid = (x_lower + x_upper) / 2
                if (x[mid] < xi) {
                    x_lower = mid + 1
                } else {
                    x_upper = mid
                }
            }
            if (x_lower == 0 || x_lower == x.size) {
                // Handle boundary cases by using nearest y row
                let row_idx = match (x_lower) {
                    case 0 => 0
                    case _ => z.size - 1
                }
                // Now find y interval in this row
                var y_lower = 0
                var y_upper = y.size - 1
                while (y_lower < y_upper) {
                    let mid = (y_lower + y_upper) / 2
                    if (y[mid] < yi) {
                        y_lower = mid + 1
                    } else {
                        y_upper = mid
                    }
                }
                if (y_lower == 0 || y_lower == y.size) {
                    result.add(z[row_idx][match (y_lower) {
                        case 0 => 0
                        case _ => z[0].size - 1
                    }])
                    continue
                }

                // Linear interpolation in y direction only
                let y0 = y[y_lower - 1]
                let y1 = y[y_lower]
                let z0 = z[row_idx][y_lower - 1]
                let z1 = z[row_idx][y_lower]
                let t = (yi - y0) / (y1 - y0)
                let zi = z0 + t * (z1 - z0)
                result.add(zi)
                continue
            }

            // For points inside the grid, perform bilinear interpolation
            let x0 = x[x_lower - 1]
            let x1 = x[x_lower]

            // Find y intervals for both surrounding x rows
            let find_y_interval = { target_y: Float64 =>
                var lower = 0
                var upper = y.size - 1
                while (lower < upper) {
                    let mid = (lower + upper) / 2
                    if (y[mid] < target_y) {
                        lower = mid + 1
                    } else {
                        upper = mid
                    }
                }
                lower
            }

            let y_lower0 = find_y_interval(yi)
            let y_lower1 = y_lower0 // Same y interval for both x rows in regular grid

            // Handle y boundary cases
            if (y_lower0 == 0 || y_lower0 == y.size) {
                // Just take value from nearby x row
                let zi = z[x_lower - 1][match (y_lower0) {
                    case 0 => 0
                    case _ => z[0].size - 1
                }]
                result.add(zi)
                continue
            }

            // Get the four corner points
            let y0 = y[y_lower0 - 1]
            let y1 = y[y_lower0]

            // Z values at corners
            let z00 = z[x_lower - 1][y_lower0 - 1]
            let z01 = z[x_lower - 1][y_lower0]
            let z10 = z[x_lower][y_lower0 - 1]
            let z11 = z[x_lower][y_lower0]

            // Percentage along x and y axes
            let tx = (xi - x0) / (x1 - x0)
            let ty = (yi - y0) / (y1 - y0)

            // Bilinear interpolation formula
            let zi = (1 - tx) * (1 - ty) * z00 + 
                     (1 - tx) * ty * z01 + 
                     tx * (1 - ty) * z10 + 
                     tx * ty * z11
            result.add(zi)
        }
        return result
    }
}

import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..x_interp.size) {
            let x_val = x_interp[i]
            var j = 0
            var k = x.size - 1
            while (j <= k) {
                let m = (j + k) / 2
                if (x[m] < x_val) {
                    j = m + 1
                } else if (x[m] > x_val) {
                    k = m - 1
                } else {
                    j = m
                    break
                }
            }
            if (j == 0) {
                result.add(y[0])
            } else if (j == x.size) {
                result.add(y[x.size - 1])
            } else {
                let x_left = x[j - 1]
                let x_right = x[j]
                let y_left = y[j - 1]
                let y_right = y[j]
                let t = (x_val - x_left) / (x_right - x_left)
                result.add(y_left + t * (y_right - y_left))
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..x_interp.size) {
            let x_val = x_interp[i]
            var j = 0
            var k = x.size - 1
            while (j <= k) {
                let m = (j + k) / 2
                if (x[m] < x_val) {
                    j = m + 1
                } else if (x[m] > x_val) {
                    k = m - 1
                } else {
                    j = m
                    break
                }
            }
            if (j == 0) {
                let y_vals = interpolate_1d(y, z[0], y_interp)
                result.add(y_vals[i])
            } else if (j == x.size) {
                let y_vals = interpolate_1d(y, z[x.size - 1], y_interp)
                result.add(y_vals[i])
            } else {
                let x_left = x[j - 1]
                let x_right = x[j]
                let z_left = z[j - 1]
                let z_right = z[j]
                for (i2 in 0..y_interp.size) {
                    let y_val = y_interp[i2]
                    var l = 0
                    var r = y.size - 1
                    while (l <= r) {
                        let m = (l + r) / 2
                        if (y[m] < y_val) {
                            l = m + 1
                        } else if (y[m] > y_val) {
                            r = m - 1
                        } else {
                            l = m
                            break
                        }
                    }
                    if (l == 0) {
                        let v = z_left[0] + (x_val - x_left) / (x_right - x_left) * (z_right[0] - z_left[0])
                        if (i >= result.size) {
                            result.add(v)
                        } else {
                            // This case shouldn't happen with proper coordination
                            result[i] = v
                        }
                    } else if (l == y.size) {
                        let v = z_left[y.size - 1] + (x_val - x_left) / (x_right - x_left) * (z_right[y.size - 1] - z_left[y.size - 1])
                        if (i >= result.size) {
                            result.add(v)
                        } else {
                            result[i] = v
                        }
                    } else {
                        let y_left_val = y[l - 1]
                        let y_right_val = y[l]
                        let z_ll = z_left[l - 1]
                        let z_lr = z_left[l]
                        let z_rl = z_right[l - 1]
                        let z_rr = z_right[l]

                        let t_x = (x_val - x_left) / (x_right - x_left)
                        let t_y = (y_val - y_left_val) / (y_right_val - y_left_val)

                        let z0 = z_ll + t_y * (z_lr - z_ll)
                        let z1 = z_rl + t_y * (z_rr - z_rl)
                        let z_val = z0 + t_x * (z1 - z0)

                        if (i >= result.size) {
                            result.add(z_val)
                        } else {
                            result[i] = z_val
                        }
                    }
                }
            }
        }
        return result
    }
}

