class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        // Validate input lengths
        if (x.size != y.size) {
            throw "x and y must have the same size"
        }

        let result = ArrayList<Float64>()
        for (x_val in x_interp) {
            // Find the interval containing x_val
            var found = false
            for (i in 0..x.size-1) {
                if (x[i] <= x_val && x_val <= x[i+1]) {
                    // Linear interpolation formula: y = y0 + (y1-y0)*(x-x0)/(x1-x0)
                    let t = (x_val - x[i]) / (x[i+1] - x[i])
                    let y_val = y[i] + t * (y[i+1] - y[i])
                    result.add(y_val)
                    found = true
                    break
                }
            }
            if (!found) {
                throw "x_val ${x_val} is out of interpolation range"
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        // Validate input lengths
        if (x.size != z.size || y.size != z[0].size) {
            throw "Invalid dimensions for interpolation"
        }

        let results = ArrayList<Float64>()
        for (x_val in x_interp) {
            for (y_val in y_interp) {
                // Find x bracket (x[i] <= x_val <= x[i+1])
                var x_index = -1
                for (i in 0..x.size-1) {
                    if (x[i] <= x_val && x_val <= x[i+1]) {
                        x_index = i
                        break
                    }
                }
                if (x_index == -1) {
                    throw "x_val ${x_val} is out of x range"
                }

                // Find y bracket (y[j] <= y_val <= y[j+1])
                var y_index = -1
                for (j in 0..y.size-1) {
                    if (y[j] <= y_val && y_val <= y[j+1]) {
                        y_index = j
                        break
                    }
                }
                if (y_index == -1) {
                    throw "y_val ${y_val} is out of y range"
                }

                // Get the 4 surrounding points
                let z00 = z[x_index][y_index]
                let z01 = z[x_index][y_index+1]
                let z10 = z[x_index+1][y_index]
                let z11 = z[x_index+1][y_index+1]

                // Calculate interpolation weights
                let tx = (x_val - x[x_index]) / (x[x_index+1] - x[x_index])
                let ty = (y_val - y[y_index]) / (y[y_index+1] - y[y_index])

                // Bilinear interpolation formula
                let z_val = (1-tx)*(1-ty)*z00 + (1-tx)*ty*z01 + tx*(1-ty)*z10 + tx*ty*z11
                results.add(z_val)
            }
        }
        return results
    }
}

