                    else if (kx == x.size) z[x.size - 1][ky]
                    else z[kx][ky]
                } else { z[kx][ky] }

                // Bilinear interpolation
                let q11 = z11 + (yj - y0) * (z12 - z11) / (y1 - y0)
                let q12 = z21 + (yj - y0) * (z22 - z21) / (y1 - y0)
