class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (xi in x_interp) {
            var found = false
            for (i in 0..<x.size-1) {
                if (x[i] <= xi && xi <= x[i+1]) {
                    let t = (xi - x[i]) / (x[i+1] - x[i])
                    let yi = y[i] + t * (y[i+1] - y[i])
                    result.add(yi)
                    found = true
                    break
                }
            }
            if (!found) {
                // Handle out-of-bounds (extrapolation not shown in example)
                result.add(0.0)
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..<x_interp.size) {
            let xi = x_interp[i]
            let yi = y_interp[i]

            // Find x positions
            var x0 = 0
            var x1 = 0
            for (j in 0..<x.size-1) {
                if (x[j] <= xi && xi <= x[j+1]) {
                    x0 = j
                    x1 = j+1
                    break
                }
            }

            // Find y positions in z rows
            var y0 = 0
            var y1 = 0
            for (j in 0..<y.size-1) {
                if (y[j] <= yi && yi <= y[j+1]) {
                    y0 = j
                    y1 = j+1
                    break
                }
            }

            // Get four surrounding points
            let q11 = z[x0][y0]
            let q12 = z[x0][y1]
            let q21 = z[x1][y0]
            let q22 = z[x1][y1]

            // Calculate weights
            let rx = (xi - x[x0]) / (x[x1] - x[x0])
            let ry = (yi - y[y0]) / (y[y1] - y[y0])

            // Bilinear interpolation
            let zi = q11*(1-rx)*(1-ry) + q21*rx*(1-ry) + q12*(1-rx)*ry + q22*rx*ry
            result.add(zi)
        }
        return result
    }
}

