class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        let N = testData.size
        if (N == 0) {
            return 0.0
        }

        var observedAgreement = 0.0
        var sumP = 0.0

        // Calculate marginal sums for each category
        for (i in 0..k) {
            var categorySum = 0
            for (j in 0..N) {
                categorySum += if (j < testData.size && i < testData[j].size) {
                    testData[j][i]
                } else {
                    0
                }
            }
            let p = categorySum.toFloat64() / (N * k.toFloat64()) // Assuming all ratings should sum to N*k for Cohen's
            sumP += p * p
        }

        // Calculate total agreements
        var totalAgreements = 0
        for (i in 0..N) {
            var rowSum = 0
            var rowCount = 0
            for (j in 0..k) {
                if (j < testData[i].size) {
                    let val = testData[i][j]
                    rowSum += val
                    rowCount += 1
                }
            }
            // For Cohen's kappa, we compare each rater pair (simplified approach)
            // This is a simplified implementation - real Cohen's would need pairwise comparisons
            totalAgreements += rowSum // This is a placeholder for actual agreement counting
        }

        // Simplified observed agreement (would need actual pairwise comparisons in a full implementation)
        observedAgreement = totalAgreements.toFloat64() / (N * k.toFloat64())

        let randomAgreement = sumP
        if (randomAgreement == 1.0) {
            return 0.0
        }

        return (observedAgreement - randomAgreement) / (1.0 - randomAgreement)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        let categoryCounts = Array<Int64>([0].repeat(k))

        // Count occurrences of each category across all raters for each subject
        for (i in 0..N) {
            let subjectRatings = testData[i]
            for (j in 0..k) {
                if (j < subjectRatings.size) {
                    categoryCounts[j] += subjectRatings[j]
                }
            }
        }

        // Calculate marginal probabilities
        let marginalProbabilities = Array<Float64>([0.0].repeat(k))
        for (j in 0..k) {
            marginalProbabilities[j] = categoryCounts[j].toFloat64() / (N * n.toFloat64())
        }

        // Calculate Pj (proportion of items assigned to category j)
        let PjSum = marginalProbabilities.reduce({acc, x => acc + x * x}, 0.0)

        // Calculate A (observed agreement)
        var A = 0.0
        for (i in 0..N) {
            let subjectRatings = testData[i]
            var subjectTotal = 0
            for (j in 0..subjectRatings.size) {
                if (j < subjectRatings.size) {
                    subjectTotal += subjectRatings[j]
                }
            }
            var Pe = 0
            for (j in 0..k) {
                if (j < subjectRatings.size) {
                    let val = subjectRatings[j].toFloat64()
                    Pe += (val * val) / (n.toFloat64() * n.toFloat64())
                }
            }
            A += Pe
        }
        A = A / N.toFloat64()

        let kappa = (A - PjSum) / (1.0 - PjSum)
        return kappa
    }
}

