    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Calculate category counts (n_j)
        var n_j = ArrayList<Int64>()
        for _ in 0..k { n_j.add(0) }

        for i in 0..testData.size {
            for j in 0..testData[i].size {
                let val = testData[i][j]
                if val >= 0 && val < k {
                    n_j[val.toInt()] += 1
                }
            }
        }

        // Calculate sum of squares of category counts
        var sumSq: Float64 = 0.0
        for i in 0..n_j.size {
            let p_j = n_j[i].toFloat64() / (N * n).toFloat64()
            sumSq += p_j * p_j
        }

        // Calculate P_o (observed agreement)
        var P_o: Float64 = 0.0
        for i in 0..testData.size {
            var sum: Int64 = 0
            var maxCount: Int64 = 0
            for j in 0..testData[i].size {
                sum += testData[i][j]
                // This is a simplified count - in reality would need to track per-category counts
