                }
            }
            P_o += maxCount.toFloat64() / (N * n).toFloat64()
        }
        P_o /= N.toFloat64()

        // Calculate P_e (expected agreement)
        let P_e = sumSq

        // Calculate Fleiss' kappa
        return (P_o - P_e) / (1.0 - P_e)
    }
