                    marginalSums[j] = marginalSums[j] + testData[i][j]
                }
            }
        }

        let totalFloat: Float64 = total.toFloat64()
        var Pe: Float64 = 1.0
        for (i in 0..k) {
            let p: Float64 = marginalSums[i].toFloat64() / totalFloat
            Pe = Pe * p
        }
        Pe = Pe * k.toFloat64()

        // Calculate kappa
        let kappaValue: Float64 = (Po - Pe) / (1.0 - Pe)
        return kappaValue
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
