        var totalRatings: Int64 = 0
        for (i in 0..N) {
            for (j in 0..k) {
                totalRatings = totalRatings + testData[i][j]
            }
        }

        // Calculate marginal sums for each category
        var categorySums: ArrayList<Int64> = ArrayList<Int64>()
        for (j in 0..k) {
            var sum: Int64 = 0
            for (i in 0..N) {
                sum = sum + testData[i][j]
            }
            categorySums.add(sum)
        }

        // Calculate proportion of ratings for each category (p_j)
        var proportions: ArrayList<Float64> = ArrayList<Float64>()
        for (j in 0..k) {
            proportions.add(categorySums[j].toFloat64() / totalRatings.toFloat64())
        }

        // Calculate expected agreement (Pe)
        var Pe: Float64 = 0.0
        for (j in 0..k) {
            Pe = Pe + proportions[j] * proportions[j]
        }

        // Calculate observed agreement (Po)
        var Po: Float64 = 0.0
        for (i in 0..N) {
            var sumSquares: Int64 = 0
            for (j in 0..k) {
                sumSquares = sumSquares + testData[i][j] * testData[i][j]
            }
            Po = Po + sumSquares.toFloat64()
        }
        Po = Po / (n.toFloat64() * totalRatings.toFloat64())

        // Calculate Fleiss' kappa
