            for (j in 0..n) {
                freq += testData[j].get(i) ?? 0.0 // Assuming single column per category
            }
            freq_sum.add(freq)
        }

        var chance: Float64 = 0.0
        let total: Float64 = freq_sum.reduce(0.0, {acc, x => acc + x})
        if (total > 0) {
            for (i in 0..k) {
                let p_i = freq_sum[i] / total
                chance += p_i * p_i
            }
        }

        return (observed - chance) / (1.0 - chance)
    }

