            Pe += Pj[j] * Pj[j]
        }

        // Calculate Po (observed agreement)
        var Po = 0.0
        for (i in 0..N.toInt()) {
            var sum_pi = 0.0
            for (j in 0..k.toInt()) {
                let count = testData[i][j].toFloat64()
                if (count > 0) {
