            for (j in 0..N:1) {
                colSum += testData[j][i].toFloat64()
            }
            let expected = (rowSums.fold(0, {acc, x => acc + x}) * colSum) / (N * k).toFloat64() / N.toFloat64()
            expectedAgreement += expected * colSum / (N * k).toFloat64()
        }

        return (observedAgreement - expectedAgreement) / (1.0 - expectedAgreement)
