class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var observedAgreement: Float64 = 0.0
        var expectedAgreement: Float64 = 0.0
        let n = testData.size

        // Calculate row and column sums (assuming square matrix for Cohen's kappa)
        var rowSums = ArrayList<Float64>()
        var colSums = ArrayList<Float64>()

        for _ in 0..k {
            rowSums.add(0.0)
            colSums.add(0.0)
        }

        for i in 0..n {
            var rowSum: Float64 = 0.0
            let row = testData[i]
            for j in 0..k {
                let val = row[j].toFloat64()
                rowSum += val
                colSums[j] += val
            }
            rowSums[i] = rowSum
        }

        let total: Float64 = {
            var sum: Float64 = 0.0
            for row in testData {
                for val in row {
                    sum += val.toFloat64()
                }
            }
            sum
        }.call()

        let grandTotalSquared = total * total

        // Calculate observed agreement
        var diagonalSum: Float64 = 0.0
        for i in 0..n {
            diagonalSum += testData[i][i].toFloat64()
        }
        observedAgreement = diagonalSum / total

        // Calculate expected agreement
        var expectedDiagonalSum: Float64 = 0.0
        for i in 0..k {
            let pi = colSums[i] / total
            let rowMarginal: Float64 = {
                var sum: Float64 = 0.0
                for row in testData {
                    sum += row[i].toFloat64()
                }
                sum
            }.call()

            // Simplified expected agreement calculation (assuming same marginals for rows)
            expectedDiagonalSum += pi * pi
        }
        expectedAgreement = expectedDiagonalSum

        // Calculate Cohen's kappa
        if expectedAgreement == 1.0 {
            return 1.0
        }
        return (observedAgreement - expectedAgreement) / (1.0 - expectedAgreement)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Calculate category counts
        let categoryCounts = ArrayList<Float64>()
        for _ in 0..k {
            categoryCounts.add(0.0)
        }

        for i in 0..N {
            let row = testData[i]
            for j in 0..k {
                categoryCounts[j] += row[j].toFloat64()
            }
        }

        // Calculate agreement probabilities
        var pj = ArrayList<Float64>()
        for j in 0..k {
            pj.add(categoryCounts[j] / (n * N))
        }

        // Calculate P (observed agreement)
        var P: Float64 = 0.0
        for i in 0..N {
            let row = testData[i]
            var nij = 0.0
            for j in 0..k {
                let val = row[j].toFloat64()
                if val != 0 {
                    nij += val * (val - 1.0)
                }
            }
            P += nij / (n * (n - 1.0))
        }
        P = P / N.toFloat64()

        // Calculate Pe (expected agreement)
        var Pe: Float64 = 0.0
        for j in 0..k {
            let val = pj[j]
            Pe += val * val
        }

        // Calculate Fleiss' kappa
        if Pe == 1.0 {
            return 1.0
        }
        return (P - Pe) / (1.0 - Pe)
    }
}

