class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Calculate observed agreement
        var sumObserved: Float64 = 0.0
        var total: Float64 = 0.0

        for (i in 0..testData.size) {
            for (j in 0..testData[i].size) {
                if (i == j) {
                    sumObserved += Float64(testData[i][j])
                }
                total += Float64(testData[i][j])
            }
        }
        let observed: Float64 = sumObserved / total

        // Calculate expected agreement
        var sumExpectedRaters: Float64 = 0.0
        for (i in 0..testData.size) {
            var sumRow: Float64 = 0.0
            for (j in 0..testData[i].size) {
                sumRow += Float64(testData[i][j])
            }
            sumExpectedRaters += sumRow * sumRow
        }
        var sumExpectedCases: Float64 = 0.0
        for (j in 0..k) {
            var sumCol: Float64 = 0.0
            for (i in 0..testData.size) {
                sumCol += Float64(testData[i][Int64(j)])
            }
            sumExpectedCases += sumCol * sumCol
        }
        let expected: Float64 = (sumExpectedRaters + sumExpectedCases) / (total * total)

        // Calculate Cohen's Kappa
        return (observed - expected) / (1.0 - expected)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Calculate marginal probabilities
        var marginalSums: ArrayList<Float64> = ArrayList<Float64>()
        for (j in 0..k) {
            var colSum: Float64 = 0.0
            for (i in 0..N) {
                colSum += Float64(testData[Int64(i)][j])
            }
            marginalSums.add(colSum)
        }

        // Calculate P_j (proportion of items assigned to category j across all raters)
        var pJs: ArrayList<Float64> = ArrayList<Float64>()
        for (j in 0..k) {
            pJs.add(marginalSums[j] / Float64(n * N))
        }

        // Calculate P_o (observed agreement)
        var pO: Float64 = 0.0
        for (i in 0..N) {
            var njj: Float64 = 0.0
            for (j in 0..k) {
                njj += Float64(testData[Int64(i)][j]) * Float64(testData[Int64(i)][j])
            }
            pO += njj - Float64(n)
        }
        pO = pO / (Float64(n) * (Float64(n) - 1.0) * Float64(N))

        // Calculate P_e (expected agreement by chance)
        var pE: Float64 = 0.0
        for (j in 0..k) {
            pE += pJs[j] * pJs[j]
        }

        // Calculate Fleiss' Kappa
        return (pO - pE) / (1.0 - pE)
    }
}

