class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var observedAgreement: Float64 = 0.0
        var chanceAgreement: Float64 = 0.0
        let n = testData.size

        // Calculate marginal sums for each rater
        var raterSums = ArrayList<Float64>([0.0; k])
        for i in 0..n {
            for j in 0..k {
                raterSums[j] += testData[i][j].toFloat64()
            }
        }

        // Calculate overall agreement
        let total = raterSums.fold({acc, x => acc + x}, init: 0.0)
        let grandMean = total / (n.toFloat64() * k)

        // Calculate observed agreement
        for i in 0..n {
            let rowTotal = testData[i].fold({acc, x => acc + x}, init: 0.toFloat64())
            observedAgreement += (rowTotal * rowTotal).toFloat64()
        }
        observedAgreement = observedAgreement / (total * total)

        // Calculate chance agreement
        var chanceSum: Float64 = 0.0
        for sum in raterSums {
            let p = sum / total
            chanceSum += p * p
        }

        chanceAgreement = grandMean * grandMean * k * k * chanceSum

        return (observedAgreement - chanceAgreement) / (1.0 - chanceAgreement)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var categoryCounts = ArrayList<Int64>([0; k])

        // Count occurrences of each category
        for i in 0..N {
            for j in 0..k {
                categoryCounts[j] += testData[i][j]
            }
        }

        // Calculate marginal probabilities
        var marginalProbs = ArrayList<Float64>([0.0; k])
        let total = n * N
        for i in 0..k {
            marginalProbs[i] = categoryCounts[i].toFloat64() / total.toFloat64()
        }

        // Calculate Pj (proportion of agreements)
        var Pj: Float64 = 0.0
        for i in 0..N {
            let rowSum = testData[i].fold({acc, x => acc + x}, init: 0.toFloat64()).toFloat64()
            var rowTerm: Float64 = 0.0
            for j in 0..k {
                let p = testData[i][j].toFloat64() / rowSum
                rowTerm += p * p
            }
            Pj += rowTerm
        }
        Pj = Pj / N.toFloat64()

        // Calculate Pe (expected agreement by chance)
        var Pe: Float64 = 0.0
        for p in marginalProbs {
            Pe += p * p
        }

        return (Pj - Pe) / (1.0 - Pe)
    }
}

