class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Calculate row and column marginals
        let N = testData.size
        var rowSums = ArrayList<Int64>([])
        var colSums = ArrayList<Int64>([])

        // Initialize column sums with zeros
        for _ in 0..k {
            colSums.add(0)
        }

        // Calculate row sums and update column sums
        for i in 0..N {
            let row = testData[i]
            var sum: Int64 = 0
            for j in 0..k {
                sum += row[j]
                colSums[j] += row[j]
            }
            rowSums.add(sum)
        }

        // Calculate total sum
        let totalSum: Int64 = rowSums.reduce({sum, val => sum + val}, 0)

        // Calculate observed agreement (Po)
        var observed: Float64 = 0.0
        for i in 0..N {
            for j in 0..k {
                if (testData[i][j] != 0) {
                    observed += (testData[i][j] * testData[i][j]) as Float64
                }
            }
        }
        observed = observed / (totalSum * totalSum)

        // Calculate expected agreement (Pe)
        var expected: Float64 = 0.0
        for j in 0..k {
            let prob = colSums[j] as Float64 / totalSum as Float64
            expected += prob * prob
        }

        // Calculate Cohen's Kappa
        return (observed - expected) / (1.0 - expected)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Calculate category proportions (Pj)
        var colSums = ArrayList<Int64>([])
        for _ in 0..k {
            colSums.add(0)
        }

        // Sum each category across all raters for all patients
        for i in 0..N {
            let row = testData[i]
            for j in 0..k {
                colSums[j] += row[j]
            }
        }

        // Calculate proportions
        var proportions = ArrayList<Float64>([])
        for j in 0..k {
            proportions.add(colSums[j] as Float64 / (N * n) as Float64)
        }

        // Calculate Pi (observed agreement)
        var Pi: Float64 = 0.0
        for i in 0..N {
            let row = testData[i]
            var sumSquares: Float64 = 0.0
            for j in 0..k {
                let prob = row[j] as Float64 / n as Float64
                sumSquares += prob * prob
            }
            Pi += sumSquares / N as Float64
        }

        // Calculate Pe (expected agreement)
        var Pe: Float64 = 0.0
        for j in 0..k {
            Pe += proportions[j] * proportions[j]
        }

        // Calculate Fleiss' Kappa
        return (Pi - Pe) / (1.0 - Pe)
    }
}

