import std.collection.ArrayList
import std.random.Random

class MahjongConnect {
    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = this.create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]
        let board = ArrayList<ArrayList<String>>()
        let rand = Random()

        for (i in 0..rows) {
            let row = ArrayList<String>()
            for (j in 0..cols) {
                let icon_index = rand.nextInt(range: 0..ICONS.size)
                row.add(ICONS[icon_index])
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        // Check if positions are valid
        if (x1 < 0 || x1 >= BOARD_SIZE[0] || y1 < 0 || y1 >= BOARD_SIZE[1] ||
            x2 < 0 || x2 >= BOARD_SIZE[0] || y2 < 0 || y2 >= BOARD_SIZE[1] ||
            pos1 == pos2) {
            return false
        }

        // Check if icons match
        if (this.board[x1][y1] != this.board[x2][y2]) {
            return false
        }

        // Check if there's a path
        return this.has_path(pos1: pos1, pos2: pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let directions = [(0, 1), (1, 0), (0, -1), (-1, 0)] // right, down, left, up
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let visited = ArrayList<(Int64, Int64)>()

        // Try direct path (0 or 1 turn)
        if (this.check_direct_path(pos1: pos1, pos2: pos2)) {
            return true
        }

        // BFS for path with one corner
        let queue = ArrayList<(Int64, Int64)>()
        queue.add(pos1)
        visited.add(pos1)

        while (queue.size > 0) {
            let current = queue.remove(at: 0)
            let (cx, cy) = current

            for (dx, dy) in directions {
                let (nx, ny) = (cx + dx, cy + dy)
                let new_pos = (nx, ny)

                // Skip if out of bounds or already visited
                if (nx < 0 || nx >= BOARD_SIZE[0] || ny < 0 || ny >= BOARD_SIZE[1] || 
                    MahjongConnect.contains(visited: visited, pos: new_pos)) {
                    continue
                }

                // Skip if blocked by different icon
                if (nx != x2 && ny != y2 && this.board[nx][ny] != " ") {
                    continue
                }

                // Check if reached destination
                if (new_pos == pos2) {
                    return true
                }

                // Check for valid L-shape path
                if (this.is_valid_corner(current: current, new_pos: new_pos, target: pos2)) {
                    return true
                }

                // Continue BFS
                visited.add(new_pos)
                queue.add(new_pos)
            }
        }

        return false
    }

    private func is_valid_corner(current: (Int64, Int64), new_pos: (Int64, Int64), target: (Int64, Int64)): Bool {
        let (cx, cy) = current
        let (nx, ny) = new_pos
        let (tx, ty) = target

        // Check for L-shape: current -> new_pos -> target
        // either x or y matches target, and other coordinate is in between
        if ((nx == tx || ny == ty) && 
            (cx == tx || cy == ty) && 
            (this.board[nx][ny] == " " || new_pos == target)) {
            // Check if the path is clear
            if (nx == tx) { // vertical then horizontal
                let step = if (ny < ty) { 1 } else { -1 }
                for (y in ny+step..ty step step) {
                    if (this.board[nx][y] != " ") {
                        return false
                    }
                }
            } else { // horizontal then vertical
                let step = if (nx < tx) { 1 } else { -1 }
                for (x in nx+step..tx step step) {
                    if (this.board[x][ny] != " ") {
                        return false
                    }
                }
            }
            return true
        }
        return false
    }

    private func check_direct_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        // Same row or same column with clear path
        if (x1 == x2) { // same row
            let step = if (y1 < y2) { 1 } else { -1 }
            for (y in y1+step..y2 step step) {
                if (this.board[x1][y] != " ") {
                    return false
                }
            }
            return true
        } else if (y1 == y2) { // same column
            let step = if (x1 < x2) { 1 } else { -1 }
            for (x in x1+step..x2 step step) {
                if (this.board[x][y1] != " ") {
                    return false
                }
            }
            return true
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v[0] == pos[0] && v[1] == pos[1]) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        this.board[x1][y1] = " "
        this.board[x2][y2] = " "
    }

    public func is_game_over(): Bool {
        for (i in 0..BOARD_SIZE[0]) {
            for (j in 0..BOARD_SIZE[1]) {
                if (this.board[i][j] != " ") {
                    return false
                }
            }
        }
        return true
    }
}

