        let cols = BOARD_SIZE[1]
        var result = ArrayList<ArrayList<String>>()
        let rand = Random()

        for (i in 0..rows) {
            var row = ArrayList<String>()
            for (j in 0..cols) {
                let index = rand.nextInt() % ICONS.size
                row.add(ICONS[(index + j) % ICONS.size])
            }
            result.add(row)
        }
        return result
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
