        if (x1 < 0 || x1 >= BOARD_SIZE[0] || y1 < 0 || y1 >= BOARD_SIZE[1] ||
            x2 < 0 || x2 >= BOARD_SIZE[0] || y2 < 0 || y2 >= BOARD_SIZE[1]) {
            return false
        }

        // Check positions are different
        if (pos1 == pos2) {
            return false
        }

        // Check icons match
        if (board[x1 as Int32][y1 as Int32] != board[x2 as Int32][y2 as Int32]) {
            return false
        }

        // Check path exists
        return has_path(pos1: pos1, pos2: pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        if (pos1 == pos2) {
            return false
        }

        var visited = ArrayList<(Int64, Int64)>()
        return bfs(pos1: pos1, pos2: pos2, visited: visited)
    }

    private func bfs(pos1: (Int64, Int64), pos2: (Int64, Int64), visited: ArrayList<(Int64, Int64)>): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        var queue = ArrayList<(Int64, Int64)>()
        queue.add(pos1)
        visited.add(pos1)

        while (queue.size > 0) {
            let current = queue.remove(at: 0)
            let (cx, cy) = current

            // Check adjacent cells (4-directional)
            let directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
            for (dx, dy) in directions {
                let nx = cx + dx
                let ny = cy + dy
                let np = (nx, ny)

                // Skip if out of bounds
                if (nx < 0 || nx >= BOARD_SIZE[0] || ny < 0 || ny >= BOARD_SIZE[1]) {
                    continue
                }

                // Skip if visited
                if (MahjongConnect.contains(visited: visited, pos: np)) {
                    continue
                }

                // skip if blocked (not empty - though in normal gameplay this wouldn't matter)
                if (board[nx as Int32][ny as Int32] != " ") {
                    // Check if this is the target position with same icon
                    if (np == pos2 && board[nx as Int32][ny as Int32] == board[x1 as Int32][y1 as Int32]) {
                        return true
                    }
                    continue
                }

                // Can move through empty spaces in one straight line
                // For true Mahjong connect rules, we'd need to check for straight paths without turns
                // This is a simplified version that just checks adjacency
                visited.add(np)
                queue.add(np)
            }
        }

        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v[0] == pos[0] && v[1] == pos[1]) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        // Simple implementation - just sets positions to empty space
        // In a real game, you might want to fill empty spaces from above
        if (x1 >= 0 && x1 < BOARD_SIZE[0] && y1 >= 0 && y1 < BOARD_SIZE[1]) {
            board[x1 as Int32][y1 as Int32] = " "
        }
        if (x2 >= 0 && x2 < BOARD_SIZE[0] && y2 >= 0 && y2 < BOARD_SIZE[1]) {
            board[x2 as Int32][y2 as Int32] = " "
        }
    }

    public func is_game_over(): Bool {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        for (i in 0..rows) {
            for (j in 0..cols) {
                if (board[i as Int32][j as Int32] != " ") {
                    return false
                }
            }
        }
        return true
    }
