        if ((x1 == x2 && simple_path_line(pos1, pos2, 0, 1)) ||  // horizontal
            (y1 == y2 && simple_path_line(pos1, pos2, 1, 0))) {  // vertical
            return true
        }

        // Check L-shape (1 turn)
        // Check horizontal then vertical
        if (x1 == x2) {  // need to turn vertically
            let x_turn = x2
            let y_mid = y1
            let pos_mid = if (y1 < y2) (x1, y1 + 1) else (x1, y1 - 1)
