        }

        // Check if positions are different and icons match
        if ((x1 == x2 && y1 == y2) || board[x1][y1] != board[x2][y2]) {
            return false
        }

        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        let directions = ArrayList<((Int64, Int64))>([(0, 1), (1, 0), (0, -1), (-1, 0)])
        var visited = ArrayList<(Int64, Int64)>()
        var queue = ArrayList<(Int64, Int64)>()

        queue.add(pos1)
        visited.add(pos1)

        while (queue.size > 0) {
            let current = queue[0]
            queue.remove(at: 0)

            if (current == pos2) {
                return true
            }

            for (dir in directions) {
                let (dx, dy) = dir
                let (nx, ny) = (current[0] + dx, current[1] + dy)
                let next_pos: (Int64, Int64) = (nx, ny)

                // Check bounds and not visiting same icon
                if (nx >= 0 && nx < BOARD_SIZE[0] && ny >= 0 && ny < BOARD_SIZE[1] &&
                    board[nx][ny] == board[x1][y1] && !contains(visited, next_pos)) {

                    visited.add(next_pos)
                    queue.add(next_pos)
                }
