                let (y_min, y_max) = if (y1 < y2) (y1, y2) else (y2, y1)
                let mut valid = true
                for (y in y_min+1..y_max) {
                    if (y != y1 && y != y2 && board[x1][y] != " ") {
                        valid = false
                        break
                    }
                }
                if (valid) return true
