            if (y1 == y2) {
                let (x_min, x_max) = if (x1 < x2) (x1, x2) else (x2, x1)
                let mut valid = true
                for (x in x_min+1..x_max) {
                    if (x != x1 && x != x2 && board[x][y1] != " ") {
                        valid = false
                        break
                    }
                }
                if (valid) return true
            }

            // L-shaped path (one turn)
            // Case 1: horizontal then vertical
            if (board[x1][y2] == " " && board[x2][y1] == " ") {
                // Path x1,y1 -> x1,y2 -> x2,y2
                let mut valid = true
                for (y in y1+1..y2) {
                    if (board[x1][y] != " ") {
                        valid = false
                        break
                    }
                }
                if (valid) return true

                // Path x1,y1 -> x2,y1 -> x2,y2
                valid = true
                for (x in x1+1..x2) {
                    if (board[x][y1] != " ") {
                        valid = false
                        break
                    }
                }
                if (valid) return true
            }
        }

