        let (x2, y2) = pos2

        // Check positions are valid and not the same
        if (x1 < 0 || x1 >= rows || y1 < 0 || y1 >= cols || 
            x2 < 0 || x2 >= rows || y2 < 0 || y2 >= cols || 
            (x1 == x2 && y1 == y2)) {
            return false
        }

        // Check icons match
        if (board[x1 as Int][y1 as Int] != board[x2 as Int][y2 as Int]) {
            return false
        }

        // Check path exists
        return has_path(pos1: pos1, pos2: pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        var visited = ArrayList<(Int64, Int64)>()
        return dfs_path_search(pos1: pos1, pos2: pos2, visited: visited)
    }

    private func dfs_path_search(pos1: (Int64, Int64), pos2: (Int64, Int64), visited: ArrayList<(Int64, Int64)>): Bool {
        let (x1, y1) = pos1
        let (x2, y2) = pos2

        if (pos1 == pos2) {
            return true
        }

        if (contains(visited: visited, pos: pos1)) {
            return false
        }
        visited.add(pos1)

        // Check adjacent cells (next to each other directly)
        if (match (x1, y1) {
            case (x2, y) if (y == y2 && (x1 == x2 - 1 || x1 == x2 + 1)) => true
            case (x, y2) if (x == x2 && (y1 == y2 - 1 || y1 == y2 + 1)) => true
            case _ => false
        }) {
            return true
        }

        // Check turns (L shape)
        let directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for (dx, dy) in directions {
            let newX = x1 + 2 * dx
            let newY = y1 + 2 * dy
            let midX = x1 + dx
            let midY = y1 + dy

            if (newX >= 0 && newX < BOARD_SIZE[0] && newY >= 0 && newY < BOARD_SIZE[1] &&
                midX >= 0 && midX < BOARD_SIZE[0] && midY >= 0 && midY < BOARD_SIZE[1] &&
                board[midX as Int][midY as Int] == " " && // empty space
                dfs_path_search(pos1: (newX, newY), pos2: pos2, visited: visited)) {
                return true
            }
        }

        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        let (x1, y1) = pos1
        let (x2, y2) = pos2
        board[x1 as Int][y1 as Int] = " "
        board[x2 as Int][y2 as Int] = " "
    }

    public func is_game_over(): Bool {
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        for (i in 0..rows) {
            for (j in 0..cols) {
                if (board[i as Int][j as Int] != " ") {
                    return false
                }
            }
        }
        return true
    }
}

