class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        var new_center = center
        var new_diff = diff
        let len = string.runes().size as Int64
        while (true) {
            let left_index = new_center - new_diff - 1
            let right_index = new_center + new_diff + 1
            if (left_index < 0 || right_index >= len) {
                return new_diff
            }
            let left_rune = string.runes().toArray()[left_index as Int]
            let right_rune = string.runes().toArray()[right_index as Int]
            if (left_rune != right_rune) {
                return new_diff
            }
            new_diff += 1
        }
    }

    public func palindromic_string(): String {
        if (this.input_string.isEmpty()) {
            return ""
        }
        let processed = this.preprocess(this.input_string)
        let n = processed.runes().size as Int64
        var p = ArrayList<Int64>([])
        for (_ in 0..n) {
            p.add(0)
        }
        var center = 0 as Int64
        var right = 0 as Int64
        for (i in 0..n) {
            let mirror = 2 * center - i
            if (i < right) {
                p[i] = min(right - i, p[mirror] ?? 0)
            }
            let diff = this.palindromic_length(i, p[i] ?? 0, processed)
            p[i] = diff
            if (i + diff > right) {
                center = i
                right = i + diff
            }
        }
        var max_len = 0 as Int64
        var center_index = 0 as Int64
        for (i in 0..n) {
            if (p[i] ?? 0 > max_len) {
                max_len = p[i] ?? 0
                center_index = i
            }
        }
        let start = (center_index - max_len) / 2
        return this.input_string.substr(start as Int, (start + max_len) as Int)
    }

    private func preprocess(s: String): String {
        var n = s.runes().size
        if (n == 0) {
            return "^$"
        }
        let ret = "^"
        for (r in s.runes()) {
            ret + "#" + r.toString()
        }
        ret + "#$"
        return ret
    }
}

