        }
        processed += r'|'

        var max_len = 0
        var max_center = 0

        for (i in 0..processed.size) {
            let current_len = palindromic_length(center: i, diff: 1, string: processed)
            if (current_len > max_len) {
                max_len = current_len
                max_center = i
            }
        }

        let start_idx = (max_center - max_len) / 2
        let end_idx = start_idx + max_len
