class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        if (data is (ArrayList<Int64>, Int64)) {
            let (results, ground_truth) = data as (ArrayList<Int64>, Int64)
            let reciprocal = compute_rank_reciprocal(results: results, ground_truth: ground_truth)
            return (reciprocal, ArrayList<Float64>([reciprocal]))
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let data_list = data as ArrayList<(ArrayList<Int64>, Int64)>
            var total: Float64 = 0.0
            var reciprocals = ArrayList<Float64>()
            for (results, ground_truth) in data_list {
                let reciprocal = compute_rank_reciprocal(results: results, ground_truth: ground_truth)
                reciprocals.add(reciprocal)
                total += reciprocal
            }
            let avg = total / Float64(data_list.size)
            return (avg, reciprocals)
        } else {
            panic("Invalid input type for mrr")
        }
    }

    private static func compute_rank_reciprocal(results: ArrayList<Int64>, ground_truth: Int64): Float64 {
        var relevant_positions = ArrayList<Int64>()
        for (i in 0..results.size) {
            if (results[i] == 1) {
                relevant_positions.add(i as Int64 + 1) // convert to 1-based index
            }
        }
        if (relevant_positions.size == 0) {
            return 0.0
        }
        let first_relevant_pos = relevant_positions[0]
        return 1.0 / Float64(first_relevant_pos)
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        if (data is (ArrayList<Int64>, Int64)) {
            let (results, ground_truth) = data as (ArrayList<Int64>, Int64)
            let avg_precision = compute_average_precision(results: results, ground_truth: ground_truth)
            return (avg_precision, ArrayList<Float64>([avg_precision]))
        } else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let data_list = data as ArrayList<(ArrayList<Int64>, Int64)>
            var total: Float64 = 0.0
            var avg_precisions = ArrayList<Float64>()
            for (results, ground_truth) in data_list {
                let avg_precision = compute_average_precision(results: results, ground_truth: ground_truth)
                avg_precisions.add(avg_precision)
                total += avg_precision
            }
            let avg = total / Float64(data_list.size)
            return (avg, avg_precisions)
        } else {
            panic("Invalid input type for map")
        }
    }

    private static func compute_average_precision(results: ArrayList<Int64>, ground_truth: Int64): Float64 {
        var relevant_pos = 0
        var precision_at_k = 0.0
        var sum_precision = 0.0
        var relevant_count = 0

        let relevant_total = compute_relevant_count(results: results)
        if (relevant_total == 0) {
            return 0.0
        }

        for (k in 0..results.size) {
            if (results[k] == 1) {
                relevant_pos += 1
                relevant_count += 1
                let true_positives = relevant_count
                let precision_k = Float64(true_positives) / Float64(k + 1)
                sum_precision += precision_k
            }
        }

        let min_relevant = min(relevant_total, ground_truth)
        return sum_precision / Float64(min_relevant)
    }

    private static func compute_relevant_count(results: ArrayList<Int64>): Int64 {
        var count = 0
        for (i in 0..results.size) {
            if (results[i] == 1) {
                count += 1
            }
        }
        return count
    }
}

