                var total_reciprocal: Float64 = 0.0
                let precision_list = ArrayList<Float64>()

                for (actual, ground_truth) in list_data {
                    let reciprocal = calculate_reciprocal_rank(actual, ground_truth)
                    let current_value = if (reciprocal == -1) { 0.0 } else { 1.0 / Float64(reciprocal) }
                    total_reciprocal += current_value
                    precision_list.add(current_value, at: precision_list.size)
                }

                let average_mrr = total_reciprocal / Float64(list_data.size)
                return (average_mrr, precision_list)
            }
            case _ => {
                println("Invalid input type")
                return (0.0, ArrayList<Float64>())
            }
        }
    }

    private static func calculate_reciprocal_rank(actual: ArrayList<Int64>, ground_truth: Int64): Int64 {
        var correct_found = false
        for (i in 0..actual.size) {
            if (i >= ground_truth) { break }
            if (actual[i] == 1) {
                return Int64(i + 1) // ranks are 1-based
            }
        }
        return -1 // no correct answer found in valid range
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        match (data) {
            case let (single_data: (ArrayList<Int64>, Int64)) => {
                let (actual, ground_truth) = single_data
                let ap = calculate_average_precision(actual, ground_truth)
                let precision_list = ArrayList<Float64>([ap])
                return (ap, precision_list)
            }
            case let list_data: ArrayList<(ArrayList<Int64>, Int64)> => {
                var total_ap: Float64 = 0.0
                let precision_list = ArrayList<Float64>()

                for (actual, ground_truth) in list_data {
                    let ap = calculate_average_precision(actual, ground_truth)
                    total_ap += ap
                    precision_list.add(ap, at: precision_list.size)
                }

                let average_map = total_ap / Float64(list_data.size)
                return (average_map, precision_list)
            }
            case _ => {
                println("Invalid input type")
                return (0.0, ArrayList<Float64>())
            }
        }
    }

    private static func calculate_average_precision(actual: ArrayList<Int64>, ground_truth: Int64): Float64 {
        var relevant = 0
        var precision_sum: Float64 = 0.0
        var correct_at_k = 0

        for (i in 0..actual.size) {
            if (actual[i] == 1) {
                relevant += 1
                if (relevant <= ground_truth) {
                    correct_at_k += 1
                    // Calculate precision at current i (0-based), convert to 1-based rank
                    let current_precision = Float64(correct_at_k) / Float64(i + 1)
                    precision_sum += current_precision
                } else {
                    break
                }
            }
        }

        if (relevant == 0) { return 0.0 }
        if (relevant < ground_truth) { return precision_sum / Float64(relevant) }
        return precision_sum / Float64(ground_truth)
    }
}

