                let reciprocalRank = calculateReciprocalRank(singlePrediction, groundTruth)
                let resultList = ArrayList<Float64>([reciprocalRank])
                return (reciprocalRank, resultList)
            }
            case let predictions: ArrayList<(ArrayList<Int64>, Int64)> => {
                // Handle multiple predictions case
                var totalReciprocalRank: Float64 = 0.0
                let reciprocalRanks = ArrayList<Float64>()

                for (i in 0..predictions.size) {
                    let (prediction, groundTruth) = predictions[i]
                    let rr = calculateReciprocalRank(prediction, groundTruth)
                    reciprocalRanks.add(rr)
                    totalReciprocalRank += rr
                }

                let averageRR = totalReciprocalRank / Float64(predictions.size)
                return (averageRR, reciprocalRanks)
            }
            case _ => {
                panic("Invalid input type for MRR calculation")
            }
        }
    }

    private static func calculateReciprocalRank(prediction: ArrayList<Int64>, groundTruth: Int64): Float64 {
        var firstCorrectIndex: Int64 = -1

        for (i in 0..prediction.size) {
            if (prediction[i] == 1) {
                firstCorrectIndex = i
                break
            }
        }

        if (firstCorrectIndex == -1) {
            return 0.0
        } else {
            return 1.0 / Float64(firstCorrectIndex + 1)
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        match (data) {
            case let (singlePrediction: ArrayList<Int64>, groundTruth: Int64) => {
                // Handle single prediction case
                let averagePrecision = calculateAveragePrecision(singlePrediction, groundTruth)
                let resultList = ArrayList<Float64>([averagePrecision])
                return (averagePrecision, resultList)
            }
            case let predictions: ArrayList<(ArrayList<Int64>, Int64)> => {
                // Handle multiple predictions case
                var totalAveragePrecision: Float64 = 0.0
                let averagePrecisions = ArrayList<Float64>()

                for (i in 0..predictions.size) {
                    let (prediction, groundTruth) = predictions[i]
                    let ap = calculateAveragePrecision(prediction, groundTruth)
                    averagePrecisions.add(ap)
                    totalAveragePrecision += ap
                }

                let averageAP = totalAveragePrecision / Float64(predictions.size)
                return (averageAP, averagePrecisions)
            }
            case _ => {
                panic("Invalid input type for MAP calculation")
            }
        }
    }

    private static func calculateAveragePrecision(prediction: ArrayList<Int64>, groundTruth: Int64): Float64 {
        var relevantPositions = ArrayList<Int64>()
        var precisionAtCutoffs = ArrayList<Float64>()
        var relevantCount: Int64 = 0
        var runningCorrect: Int64 = 0

        // First collect all relevant positions (where prediction == 1)
        for (i in 0..prediction.size) {
            if (prediction[i] == 1) {
                relevantPositions.add(i)
            }
        }

        let numRelevant = relevantPositions.size

        if (numRelevant == 0) {
            return 0.0
        }

        // Calculate precision at each relevant position
        for (pos in relevantPositions) {
            runningCorrect += 1
            var currentCorrect: Int64 = 0

            // Count number of correct predictions up to current position
            for (i in 0..pos+1) {
                if (prediction[i] == 1) {
                    currentCorrect += 1
                }
            }

            let precision = Float64(currentCorrect) / Float64(pos + 1)
            precisionAtCutoffs.add(precision)
        }

        // Calculate average of these precisions
        var sum: Float64 = 0.0
        for (i in 0..precisionAtCutoffs.size) {
            sum += precisionAtCutoffs[i]
        }

        return sum / Float64(numRelevant)
    }
}

