        let isList = match (data) {
            case is ArrayList<Any> => true  // handles list of tuples
            case _ => false                 // handles single tuple
        }

        if (isList) {
            let dataList = data as! ArrayList<Any>
            var reciprocalRanks = ArrayList<Float64>()
            var totalReciprocal: Float64 = 0.0
            var count: Int64 = 0

