                    if (actual[i] == 1) {
                        // Only count if we haven't found a correct answer yet
                        if (!found || i == 0) {
                            found = true
                            if (i < groundTruth) {  // Check if it's within ground truth
                                reciprocalRanks.add(1.0 / Float64(rank))
                                totalReciprocal += 1.0 / Float64(rank)
                                count += 1
                                break
                            }
                        }
                        rank += 1
                    }
                }

                // If no correct answer found within ground truth (rank exceeded)
                if (!found || rank > groundTruth) {
                    reciprocalRanks.add(0.0)
                }
            }

            let average: Float64 = if (count > 0) { totalReciprocal / Float64(count) } else { 0.0 }
            return (average, reciprocalRanks)
        } else {
            // Handle single tuple case
            let tuple = data as! (ArrayList<Int64>, Int64)
            let (actual, groundTruth) = (tuple[0], tuple[1] as! Int64)
            var rank: Int64 = 1
            var found = false

            for (i in 0..actual.size) {
