    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        match (data) {
            case let tuple: (ArrayList<Int64>, Int64) => 
                let (scores, ground_truth) = tuple
                let reciprocal = computeRank(scores, ground_truth)
                    .map({ rank: Int64 => 
                        if (rank > 0) { 1.0 / Float64.fromInt64(rank) } 
                        else { 0.0 }
                    })
                let sum = reciprocal.foldLeft(0.0, { acc: Float64, val => acc + val })
                let avg = sum / Float64.fromInt64(1)
                let result = ArrayList<Float64>(reciprocal)
                return (avg, result)

            case let list: ArrayList<(ArrayList<Int64>, Int64)> => 
                let reciprocals = list.map({ item =>
                    let (scores, ground_truth) = item
                    computeRank(scores, ground_truth)
                        .map({ rank: Int64 => 
                            if (rank > 0) { 1.0 / Float64.fromInt64(rank) } 
                            else { 0.0 }
                        })
                })
                let sums = reciprocals.map({ r => r.foldLeft(0.0, { acc, val => acc + val }) })
                let avg = sums.foldLeft(0.0, { acc, val => acc + val }) / Float64.fromInt64(sums.size)
                let result = reciprocals.foldLeft(ArrayList<Float64>(), { acc, r =>
                    var tmp = acc
                    for (v in r) { tmp.add(v) }
                    tmp
                })
                return (avg, result)

            case _ => 
                println("Invalid input type")
                return (0.0, ArrayList<Float64>())
        }
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        match (data) {
            case let tuple: (ArrayList<Int64>, Int64) => 
                let (scores, ground_truth) = tuple
                let precision_list = computePrecisionAtK(scores, ground_truth)
                let ap = computeAveragePrecision(precision_list)
                let result = ArrayList<Float64>(precision_list)
                return (ap, result)

            case let list: ArrayList<(ArrayList<Int64>, Int64)> => 
                let ap_list = ArrayList<Float64>()
                let all_precisions = ArrayList<Float64>()
                for (item in list) {
                    let (scores, ground_truth) = item
                    let precision_list = computePrecisionAtK(scores, ground_truth)
                    let ap = computeAveragePrecision(precision_list)
                    ap_list.add(ap)
                    for (p in precision_list) { all_precisions.add(p) }
                }
                let avg_ap = ap_list.foldLeft(0.0, { acc, val => acc + val }) / Float64.fromInt64(ap_list.size)
                return (avg_ap, all_precisions)

            case _ => 
                println("Invalid input type")
                return (0.0, ArrayList<Float64>())
        }
    }

    private static func computeRank(scores: ArrayList<Int64>, ground_truth: Int64): ArrayList<Int64> {
        let positions = ArrayList<Int64>()
        let relevant_positions = ArrayList<Int64>()
        for (i in 0..scores.size) {
            if (scores[i] == 1) { relevant_positions.add(i + 1) } // 1-based index
        }
        // The rank is the first relevant position (1-based)
        if (relevant_positions.size > 0) {
            return ArrayList<Int64>([relevant_positions[0]])
        }
        return ArrayList<Int64>([0]) // No relevant items
    }

    private static func computePrecisionAtK(scores: ArrayList<Int64>, ground_truth: Int64): ArrayList<Float64> {
        let precisions = ArrayList<Float64>()
        var relevant_count = 0
        for (i in 0..scores.size) {
            if (scores[i] == 1) { relevant_count += 1 }
            let precision = Float64.fromInt64(relevant_count) / Float64.fromInt64(i + 1)
            precisions.add(precision)
        }
        return precisions
    }

    private static func computeAveragePrecision(precisions: ArrayList<Float64>): Float64 {
        var sum = 0.0
        var relevant_positions = 0
        for (i in 0..precisions.size) {
            if (i == 0 || (i < precisions.size && precisions[i - 1] != precisions[i])) {
                // Only consider positions where precision changes (for relevant docs)
                // Note: This is a simplified AP calculation - actual implementation might need adjustment
                // based on true ground truth count
                relevant_positions += 1
                sum += precisions[i]
            }
        }
        // This is a simplified version - a more accurate implementation would need
        // to know the total number of relevant documents in the ground truth
        // Here we'll use the number of 1s in scores as a proxy
        let relevant_docs = precisions.filter({ p => p > 0.0 }).size
        if (relevant_docs > 0) {
            return sum / Float64.fromInt64(relevant_docs)
        }
        return 0.0
    }
}

