        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let rand = Random()
        var mine_positions = ArrayList<Int64>([])

        // Generate unique mine positions
        while (mine_positions.size < k) {
            let pos = rand.nextInt64(n * n)
            var duplicate = false
            for (i in 0..mine_positions.size) {
                if (mine_positions[i] == pos) {
                    duplicate = true
                    break
                }
            }
            if (!duplicate) {
                mine_positions.add(pos)
            }
        }

        var map = ArrayList<ArrayList<String>>([])
        for (i in 0..n) {
            var row = ArrayList<String>([])
            for (j in 0..n) {
                let index = i * n + j
                let is_mine = mine_positions.contains(index)
                if (is_mine) {
                    row.add("X")
                } else {
                    // Count surrounding mines
                    var count = 0
                    for (di in -1..2) {
                        for (dj in -1..2) {
                            if (di == 0 && dj == 0) continue
                            let ni = i + di
                            let nj = j + dj
                            if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                                let nindex = ni * n + nj
                                if (mine_positions.contains(nindex)) {
                                    count += 1
                                }
                            }
                        }
                    }
                    row.add(count.toString())
                }
            }
            map.add(row)
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var map = ArrayList<ArrayList<String>>([])
        for (i in 0..n) {
            var row = ArrayList<String>([])
            for (j in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                let cell = map[i][j]
                if (cell != "-" && this.minesweeper_map[i][j] != "X") {
                    // Found a non-mine cell that hasn't been swept
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= this.n || y < 0 || y >= this.n) {
            return this.player_map
        }

        if (this.player_map[x][y] != "-") {
            return this.player_map
        }

        if (this.minesweeper_map[x][y] == "X") {
            // Game over (mine hit)
            for (i in 0..this.n) {
                for (j in 0..this.n) {
                    if (this.minesweeper_map[i][j] == "X") {
                        this.player_map[i][j] = "X"
                    }
                }
            }
            return false
        }

        // Reveal the cell
