class MusicPlayer {

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == song) {
                this.playlist.remove(at: i)
                break
            }
        }
    }

    public func play(): Option<String> {
        if (this.current_song != None) {
            return this.current_song
        } else if (this.playlist.size > 0) {
            this.current_song = Some(this.playlist[0])
            return this.current_song
        } else {
            return None
        }
    }

    public func stop(): Bool {
        if (this.current_song != None) {
            this.current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }

        let current_index = this.playlist.indexOf(this.current_song.getOrThrow())
        if (current_index == None || current_index == this.playlist.size - 1) {
            return false
        }

        let next_index = current_index.getOrThrow() + 1
        this.current_song = Some(this.playlist[next_index])
        return true
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }

        let current_index = this.playlist.indexOf(this.current_song.getOrThrow())
        if (current_index == None || current_index == 0) {
            return false
        }

        let prev_index = current_index.getOrThrow() - 1
        this.current_song = Some(this.playlist[prev_index])
        return true
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }

        // Create a shuffled copy
        let shuffled = ArrayList<String>()
        let temp = ArrayList<String>(this.playlist.toArray())

        while (temp.size > 0) {
            let random_index = Random().nextInt(temp.size)
            shuffled.add(temp.remove(at: random_index))
        }

        this.playlist = shuffled
        return true
    }
}

