        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        // First check if the song to remove is the current one
        if (this.current_song != None && this.current_song.getOrThrow() == song) {
            this.current_song = None
        }

        // Remove from playlist
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == song) {
                this.playlist.remove(at: i)
                break
            }
        }
    }

    public func play(): Option<String> {
        if (this.playlist.size == 0) {
            return None
        }

        if (this.current_song == None) {
            if (this.playlist.size > 0) {
                this.current_song = Some(this.playlist[0])
            }
        }

        return this.current_song
    }

    public func stop(): Bool {
        if (this.current_song != None) {
            this.current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }

        let current = this.current_song.getOrThrow()
        var current_index = -1

        // Find current song index
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == current) {
                current_index = i
                break
            }
        }

        if (current_index == -1 || current_index == this.playlist.size - 1) {
            return false
        }

        this.current_song = Some(this.playlist[current_index + 1])
        return true
    }

    public func previous_song(): Bool {
        if (this.playlist.size == 0 || this.current_song == None) {
            return false
        }

        let current = this.current_song.getOrThrow()
        var current_index = -1

        // Find current song index
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == current) {
                current_index = i
                break
            }
        }

        if (current_index == -1 || current_index == 0) {
            return false
        }

        this.current_song = Some(this.playlist[current_index - 1])
        return true
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if (this.playlist.size == 0) {
            return false
        }

        // Fisher-Yates shuffle algorithm
        let rand = Random()
        for (i in (this.playlist.size - 1)..0: -1) {
            let j = rand.nextInt(upper_bound: i + 1)
            // Swap elements
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }

        // If current song exists, try to keep it current after shuffle
        if (this.current_song != None) {
            let current = this.current_song.getOrThrow()
            for (i in 0..this.playlist.size) {
                if (this.playlist[i] == current) {
                    this.current_song = Some(current)
                    return true
                }
            }
            this.current_song = None
        }

        return true
    }
}

