                playlist.remove(at: i)
                break
            }
        }
    }

    public func play(): Option<String> {
        return if (current_song != None) {
            current_song
        } else if (playlist.size > 0) {
            current_song = Some(playlist[0])
            current_song
        } else {
            None
        }
    }

    public func stop(): Bool {
        if (current_song != None) {
            current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if (playlist.size == 0) return false

        let current = current_song.getOrThrow()
        let current_index = {i: Int64 => 
            if (playlist[i] == current) { 
                i 
            } else { 
                -1 
            }
        }.find(playlist.size)

        if (current_index == -1) {
            if (playlist.size > 0) {
                current_song = Some(playlist[0])
                return true
            }
            return false
        } else {
            let next_index = (current_index + 1) % playlist.size
            current_song = Some(playlist[next_index])
            return true
        }
    }

    public func previous_song(): Bool {
        if (playlist.size == 0) return false

        let current = current_song.getOrThrow()
        let current_index = {i: Int64 => 
            if (playlist[i] == current) { 
                i 
            } else { 
                -1 
            }
        }.find(playlist.size)

        if (current_index == -1) {
            if (playlist.size > 0) {
                current_song = Some(playlist[playlist.size - 1])
                return true
            }
            return false
        } else {
            let prev_index = (current_index - 1 + playlist.size) % playlist.size
            current_song = Some(playlist[prev_index])
            return true
        }
    }

    public func set_volume(volume: Int64): Bool {
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if (playlist.size <= 1) return false

        // Convert to Array for shuffling
        var arr = ArrayList<String>()
        for (song in playlist) {
            arr.add(song)
        }

        // Fisher-Yates shuffle
        var i = arr.size - 1
        while (i > 0) {
            let j = Random().nextInt64(lower: 0, upper: i + 1)
            let temp = arr[i]
            arr[i] = arr[j]
            arr[j] = temp
            i -= 1
        }

        // Update playlist
        playlist.clear()
        for (song in arr) {
            playlist.add(song)
        }

        return true
    }
}

