        match (this.current_song) {
            case Some(current) => {
                let current_index = this.playlist.index_of(current)
                match (current_index) {
                    case Some(i) => {
                        if (i + 1 < this.playlist.size) {
                            this.current_song = Some(this.playlist[i + 1])
                            return true
                        } else {
                            return false
                        }
                    }
                    case None => return false
                }
            }
            case None => {
                if (this.playlist.size > 0) {
                    this.current_song = Some(this.playlist[0])
                    return true
                } else {
                    return false
                }
            }
        }
    }

    public func previous_song(): Bool {
