            this.volume = volume
            return true
        } else {
            return false
        }
    }

    public func shuffle(): Bool {
        if (this.playlist.size > 0) {
            // Convert to Array for shuffling (ArrayList doesn't have shuffle)
            let arr = this.playlist.to_array()
            // Simple Fisher-Yates shuffle implementation
            for (i in arr.size-1..0:-1) {
                let j = Random.int(from: 0, to: i+1)
                let temp = arr[i]
                arr[i] = arr[j]
                arr[j] = temp
            }
