    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        let pattern = Regex(r"[^a-zA-Z ]")

        for (str in string_list) {
            // Remove non-alphabetic characters except spaces
            let cleaned = pattern.replaceAll(str, "")
            // Convert to lowercase
            let lower = cleaned.toLowerCase()
            // Split into words
            let words = ArrayList<String>(lower.split(" "))
            // Filter out empty strings
            let filtered_words = ArrayList<String>()
            for (word in words) {
                if (word.size > 0) {
                    filtered_words.add(word)
                }
            }
            words_list.add(filtered_words)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var frequency_map = HashMap<String, Int64>()

        for (words in words_list) {
            for (word in words) {
                let current_count = frequency_map.get(word) ?? 0
                frequency_map.add(word, current_count + 1)
            }
        }

        // Convert HashMap to ArrayList of tuples for sorting
        var items = ArrayList<(String, Int64)>()
        for ((k, v) in frequency_map) {
            items.add((k, v))
        }

        // Sort by frequency in descending order
        let by_freq = {l: (String, Int64), r: (String, Int64) => l.1 < r.1}
        sort(items, lessThan: by_freq, descending: true)

        // Get top 5 entries
        var top_items = HashMap<String, Int64>()
        for (i in 0..(items.size.min(5))) {
            let item = items[i]
            top_items.add(item.0, item.1)
        }

        return top_items
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list: string_list)
        return this.calculate_word_frequency(words_list: words_list)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        var words_list = ArrayList<ArrayList<String>>()
        for (i in 0..string_list.size) {
            let str = string_list[i]
            // Keep only English letters and spaces, convert to lowercase
            let cleaned = Regex("\\P{L}|[^\\s]").replace(str, "")
            let lower = cleaned.toLowerCase()
            // Split into words (split by whitespace)
            let words = lower.split(" ").filter({ w => w.size > 0 })
            let word_arr = ArrayList<String>(words.map({ w => String(w) }))
            words_list.add(word_arr)
        }
        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        var freq_map = HashMap<String, Int64>()
        for (i in 0..words_list.size) {
            let words = words_list[i]
            for (j in 0..words.size) {
                let word = words[j]
                if (freq_map.contains(word)) {
                    let current = freq_map[word] ?? 0
                    freq_map.add(word, current + 1)
                } else {
                    freq_map.add(word, 1)
                }
            }
        }

        // Convert to list of (word, count) pairs for sorting
        var freq_list = ArrayList<(String, Int64)>()
        for (pair in freq_map) {
            freq_list.add((pair.key, pair.value))
        }

        // Sort in descending order by count
        let lessThan = { l: (String, Int64), r: (String, Int64) => l[1] < r[1] }
        sort(freq_list, lessThan: lessThan, descending: true)

        // Get top 5 and build result map
        var top_map = HashMap<String, Int64>()
        let limit = if (freq_list.size > 5) { 5 } else { freq_list.size }
        for (i in 0..limit) {
            top_map.add(freq_list[i][0], freq_list[i][1])
        }

        return top_map
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

