            remain = remain.substring(0, remain.size - segmentSize)

            let words = this.trans_three(segment)
            if (words != "") {
                if (pos > 0) {
                    result.add(0, this.parse_more(pos))
                }
                result.add(0, words)
            }
            pos += 1
        }

        let formatted = result.join(" ")
        return if (formatted == "") { "ZERO" } else { "${formatted} ONLY" }
