class NumberWordFormatter {
    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                           "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if (x is None<String>) {
            return "INVALID NUMBER"
        }
        let numStr = x.getOrThrow()
        return this.format_string(numStr)
    }

    public func format_string(x: String): String {
        var result = ArrayList<String>()
        var i = x.size - 1
        var currentGroup = ArrayList<String>()
        var groupCount = 0

        while (i >= 0) {
            let start = if (i - 2 < 0) { 0 } else { i - 2 }
            let group = x.substring(start, i + 1)
            if (!group.isEmpty()) {
                let groupStr = this.trans_three(group.toRuneArray().map { it.toString() }.joinToString(""))
                if (!groupStr.isEmpty()) {
                    if (groupCount > 0) {
                        currentGroup.insert(0, this.parse_more(groupCount))
                    }
                    currentGroup.insert(0, groupStr)
                    result.insert(0, currentGroup.joinToString(" "))
                    currentGroup.clear()
                }
            }
            i -= 3
            groupCount += 1
        }

        if (!currentGroup.isEmpty()) {
            result.insert(0, currentGroup.joinToString(" "))
        }

        let finalResult = result.joinToString(" ")
        return if (finalResult.isEmpty()) { "ZERO" } else { "${finalResult} ONLY" }
    }

    public func trans_two(s: String): String {
        let num = s.toInt64().getOrThrow()
        if (num >= 10 && num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else if (num >= 20) {
            let ten = num / 10
            let one = num % 10
            return if (one == 0) {
                this.NUMBER_TEN[ten.toInt32() - 1]
            } else {
                "${this.NUMBER_TEN[ten.toInt32() - 1]} ${this.NUMBER[one.toInt32()]}"
            }
        } else if (num > 0) {
            return this.NUMBER[num.toInt32()]
        }
        return ""
    }

    public func trans_three(s: String): String {
        let num = s.toInt64().getOrThrow()
        let hundred = num / 100
        let remainder = num % 100
        var result = ""

        if (hundred > 0) {
            result = "${this.NUMBER[hundred.toInt32()]} HUNDRED"
            if (remainder > 0) {
                result += " AND ${this.trans_two(remainder.toString())}"
            }
        } else if (remainder > 0) {
            result = this.trans_two(remainder.toString())
        }

        return result
    }

    public func parse_more(i: Int64): String {
        return this.NUMBER_MORE[i.toInt32()]
    }
}

