        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if (x.isNone()) {
            return "INVALID NUMBER"
        }
        let numStr = x.getOrThrow()
        return this.format_string(numStr)
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let integerPart = parts[0]
        let decimalPart = if (parts.size > 1) { parts[1] } else { "" }

        let result = ArrayList<String>()
        let chunks = ArrayList<String>()

        for (i in 0..<integerPart.size:3) {
            let start = if (integerPart.size - i - 3 >= 0) { integerPart.size - i - 3 } else { 0 }
            let end = if (integerPart.size - i >= 0) { integerPart.size - i } else { 0 }
            let chunk = integerPart.substring(start, end)
            chunks.add(chunk)
        }

        sort(chunks, lessThan: {l, r => l.size < r.size}, descending: true)

        for (i in 0..<chunks.size) {
            let chunk = chunks[i]
            let magnitude = chunks.size - 1 - i
            let words = this.trans_three(chunk)
            if (words != "") {
                if (words == "ZERO") {
                    continue
                }
                if (magnitude > 0) {
                    result.add(words + " " + this.parse_more(magnitude))
                } else {
                    result.add(words)
                }
            }
        }

        let formatted = result.join(" ")
        let finalResult = if (formatted != "") { formatted + " ONLY" } else { "ZERO ONLY" }

        if (decimalPart != "") {
            return finalResult + " AND " + decimalPart + " CENTS"
        }
        return finalResult
    }

    public func trans_two(s: String): String {
        if (s == "") {
            return ""
        }
        let num = s.parseInt64().getOrThrow()
        if (num < 10) {
            return this.NUMBER[num as Int64]
        } else if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let ten = num / 10
            let one = num % 10
            return if (one != 0) {
                this.NUMBER_TEN[ten - 1] + " " + this.NUMBER[one]
            } else {
                this.NUMBER_TEN[ten - 1]
            }
        }
    }

    public func trans_three(s: String): String {
        if (s == "") {
            return ""
        }
        let num = s.parseInt64().getOrThrow()
        if (num == 0) {
            return "ZERO"
        }
        let hundred = num / 100
        let remainder = num % 100
        var result = ""

        if (hundred > 0) {
            result = this.NUMBER[hundred] + " HUNDRED"
        }

        let twoDigits = this.trans_two(remainder.toString())
        if (twoDigits != "") {
            if (hundred > 0) {
                result += " AND " + twoDigits
            } else {
                result = twoDigits
            }
        }

        return result
    }

    public func parse_more(i: Int64): String {
        if (i >= 0 && i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        }
        return ""
    }
}

