class NumberWordFormatter {
    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if (x is None<String>) {
            return "INVALID NUMBER"
        }
        let num = x.getOrThrow()
        return this.format_string(num)
    }

    public func format_string(x: String): String {
        var trimmed = x.trim()
        if (trimmed.size == 0) {
            return "ZERO ONLY"
        }

        // Check for decimal part
        var parts = trimmed.split(".")
        let integerPart = parts[0]
        let decimalPart = if (parts.size > 1) { Some<String>(parts[1]) } else { None<String>() }

        var result = ArrayList<String>()
        let groups = ArrayList<String>()
        let len = integerPart.size

        // Split into groups of 3 digits
        for (i in 0..(len / 3)) {
            let start = if (len - (i + 1) * 3 >= 0) { len - (i + 1) * 3 } else { 0 }
            let end = len - i * 3
            let group = integerPart.substring(start, end)
            if (group.size > 0) {
                groups.add(group)
            }
        }

        for (i in 0..groups.size) {
            let group = groups[i]
            let value = group.toInt64().getOrThrow()
            if (value == 0 && groups.size == 1) {
                result.add("ZERO")
                continue
            }

            if (value > 0) {
                let groupWords = this.trans_three(group)
                if (i > 0) {
                    groupWords.add(" ")
                    groupWords.add(this.parse_more(i))
                }
                result.add(0, groupWords)
            }
        }

        let integerWords = if (result.size > 0) { result.join(" ") } else { "" }
        let suffix = if (decimalPart is Some<String>) {
            let dec = decimalPart.getOrThrow()
            if (dec.size > 0) {
                " POINT " + this.decimal_parts_to_words(dec)
            } else {
                ""
            }
        } else {
            ""
        }

        return if (integerWords.size > 0) { 
            "${integerWords}${suffix} ONLY" 
        } else { 
            "ZERO ONLY" 
        }
    }

    public func trans_two(s: String): String {
        let value = s.toInt64().getOrThrow()
        if (value < 10) {
            return this.NUMBER[value as Int64]
        } else if (value < 20) {
            return this.NUMBER_TEEN[value - 10]
        } else {
            let ten = this.NUMBER_TEN[value / 10 - 1]
            let one = this.NUMBER[value % 10]
            return if (value % 10 != 0) {
                "${ten} ${one}"
            } else {
                ten
            }
        }
    }

    public func trans_three(s: String): String {
        let value = s.toInt64().getOrThrow()
        var result = ArrayList<String>()
        let hundred = value / 100
        let remainder = value % 100

        if (hundred > 0) {
            result.add(this.NUMBER[hundred])
            result.add("HUNDRED")
        }

        if (remainder > 0) {
            let twoDigits = this.trans_two(remainder.toString())
            if (hundred > 0) {
                result.add("AND")
            }
            result.add(twoDigits)
        }

        return result.join(" ")
    }

    public func parse_more(i: Int64): String {
        // For thousand (1), million (2), billion (3)
        return this.NUMBER_MORE[i]
    }

    private func decimal_parts_to_words(dec: String): String {
        var result = ArrayList<String>()
        for (i in 0..dec.size) {
            let digit = dec[i].toString().toInt64().getOrThrow()
            if (digit != 0) {
                result.add(this.NUMBER[digit])
            }
        }
        return result.join(" ")
    }
}

func main(): Unit {
    let formatter = NumberWordFormatter()
    println(formatter.format(Some<String>("123456")))  // "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
    println(formatter.format(Some<String>("100")))     // "ONE HUNDRED ONLY"
    println(formatter.format(Some<String>("23")))      // "TWENTY THREE ONLY"
    println(formatter.format(Some<String>("105")))     // "ONE HUNDRED AND FIVE ONLY"
    println(formatter.format(Some<String>("1000000"))) // "ONE MILLION ONLY"
