class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case None<?> => return "INVALID NUMBER"
            case Some<?>(s) => return this.format_string(s)
        }
    }

    public func format_string(x: String): String {
        var i = x.toRuneArray().size - 1
        var result = ArrayList<String>()
        var segment_count = 0
        var segment = ArrayList<String>()

        while (i >= 0) {
            if (segment.size == 3) {
                result.add(0, this.trans_three(segment.join()))
                segment = ArrayList<String>()
                segment_count += 1
            }
            let char = x[i].toString()
            if (char.matches("[0-9]")) {
                segment.add(0, char)
            }
            i -= 1
        }

        if (segment.size > 0) {
            result.add(0, this.trans_three(segment.join()))
            segment_count += 1
        }

        var final_result = ArrayList<String>()
        for (j in 0..result.size) {
            if (j < result.size) {
                if (result[j] != "") {
                    final_result.add(result[j])
                    if (segment_count - j - 1 >= 0 && segment_count - j - 1 < this.NUMBER_MORE.size) {
                        if (this.NUMBER_MORE[segment_count - j - 1] != "") {
                            final_result.add(this.NUMBER_MORE[segment_count - j - 1])
                        }
                    }
                }
            }
        }

        if (final_result.size == 0) {
            return "ZERO ONLY"
        }

        let joined = final_result.join(" ")
        if (!joined.contains("ONLY")) {
            return joined + " ONLY"
        }
        return joined
    }

    public func trans_two(s: String): String {
        let num = s.toInt64().getOrThrow()
        if (num < 10) {
            return this.NUMBER[num.toInt()] // Conversion from Int64 to Int assumed safe here
        } else if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let ten_digit = num / 10
            let one_digit = num % 10
            if (one_digit == 0) {
                return this.NUMBER_TEN[ten_digit.toInt() - 1]
            } else {
                return this.NUMBER_TEN[ten_digit.toInt() - 1] + " " + this.NUMBER[one_digit.toInt()]
            }
        }
    }

    public func trans_three(s: String): String {
        let num = s.toInt64().getOrThrow()
        if (num == 0) {
            return ""
        }
        let hundred_digit = num / 100
        let remainder = num % 100
        var result = ""
        if (hundred_digit > 0) {
            result += this.NUMBER[hundred_digit.toInt()] + " HUNDRED"
            if (remainder > 0) {
                result += " AND "
            }
        }
        if (remainder > 0) {
            result += this.trans_two(remainder.toString())
        }
        return result
    }

    public func parse_more(i: Int64): String {
        return this.NUMBER_MORE[i.toInt()] // Conversion from Int64 to Int assumed safe here
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case None => ""
            case Some(numStr) => this.format_string(numStr)
        }
    }

    public func format_string(x: String): String {
        var anum = x
        var result = ""

        // Handle negative numbers
        if (anum.startsWith("-")) {
            result += "MINUS "
            anum = anum.subString(from: 1)
        }

        anum = anum.reverse()
        let len = anum.size
        var start = len
        var i = 0

        while (i < len) {
            let blockLen = match (start) {
                case a if (a > 3) => 3
                case _ => start
            }
            let end = i + blockLen
            let blockStr = anum.subString(from: i, to: end).reverse()

            if (!blockStr.allMatch({c => c == '0'})) {
                var blockResult = ""
                match (blockLen) {
                    case 3 => {
                        let hundredDigit = blockStr[0].toString().toInt() ?? 0
                        if (hundredDigit > 0) {
                            blockResult += this.NUMBER[hundredDigit] + " HUNDRED"
                            if (blockStr.subString(from: 1).allMatch({c => c == '0'})) {
                                blockResult += " "
                            } else {
                                blockResult += " AND "
                            }
                        }
                        if (blockStr.subString(from: 1) != "00") {
                            blockResult += this.trans_two(blockStr.subString(from: 1))
                        }
                    }
                    case 2 => {
                        blockResult += this.trans_two(blockStr)
                    }
                    case 1 => {
                        let digit = blockStr[0].toString().toInt() ?? 0
                        if (digit > 0) {
                            blockResult += this.NUMBER[digit]
                        }
                    }
                }

                if (start > 3) {
                    blockResult += " " + this.parse_more((len - i) / 3 - 1)
                }

                if (result != "") {
                    result += " " + blockResult
                } else {
                    result = blockResult
                }
            }

            start -= 3
            i += 3
        }

        if (result == "") {
            return "ZERO"
        }

        result += " ONLY"
        return result.trim()
    }

    public func trans_two(s: String): String {
        if (s.size == 1 || s[0] == r'0') {
            return this.trans_one(s[1].toString())
        }

        let tensDigit = s[0].toString().toInt() ?? 0
        if (tensDigit == 1) {
            let onesDigit = s[1].toString().toInt() ?? 0
            return this.NUMBER_TEEN[onesDigit]
        }

        let result = this.NUMBER_TEN[tensDigit - 1]
        let onesDigit = s[1].toString().toInt() ?? 0
        if (onesDigit > 0) {
            return result + " " + this.NUMBER[onesDigit]
        }
        return result
    }

    public func trans_three(s: String): String {
        let result = ""
        if (s.size == 3 && s[0] != r'0') {
            let hundredDigit = s[0].toString().toInt() ?? 0
            result += this.NUMBER[hundredDigit] + " HUNDRED"

            let twoDigits = s.subString(from: 1)
            if (twoDigits != "00") {
                result += " AND " + this.trans_two(twoDigits)
            }
        } else if (s.size > 1) {
            return this.trans_two(s.subString(from: s.size - 2))
        }
        return result.trim()
    }

    public func parse_more(i: Int64): String {
        match (i) {
            case 0 => "THOUSAND"
            case 1 => "MILLION"
            case 2 => "BILLION"
            case _ => ""
        }
    }

    private func trans_one(s: String): String {
        let digit = s.toInt() ?? 0
        return this.NUMBER[digit]
    }
}

