        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if (x == None<String>()) {
            return "INVALID NUMBER"
        }
        return this.format_string(x.getOrThrow())
    }

    public func format_string(x: String): String {
        let cleaned = x.trim()
        if (cleaned.size == 0) {
            return "INVALID NUMBER"
        }

        var result = ArrayList<String>()
        var parts = cleaned.split(".")
        let integerPart = parts[0]
        let decimalPart = if (parts.size > 1) { parts[1] } else { "" }

        let groups = ArrayList<String>()
        let len = integerPart.size
        for (i in 0..len:3) {
            let end = if (i + 3 < len) { i + 3 } else { len }
            groups.add(0, integerPart.slice(i, end))
        }

        for (i in 0..groups.size) {
            let numStr = groups[i]
            if (numStr.size > 0) {
                let num = numStr.toInt64()!.getOrThrow()
                if (num != 0) {
                    let words = this.trans_three(numStr)
                    if (words != "") {
                        result.add(words)
                        if (i < groups.size - 1) {
                            result.add(this.NUMBER_MORE[groups.size - 1 - i])
                        }
                    }
                }
            }
        }

        var finalResult = ""
        if (result.size > 0) {
            finalResult = result.join(" ")
            if (decimalPart != "") {
                finalResult += " AND ${this.trans_two(decimalPart).toLower()} CENTS"
            }
            finalResult += " ONLY"
        } else {
            finalResult = "ZERO"
        }
        return finalResult
    }

    public func trans_two(s: String): String {
        if (s.size != 2) {
            return ""
        }
        let num = s.toInt64()!.getOrThrow()
        if (num < 10) {
            return this.NUMBER[num.toInt32()!]
        } else if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let tens = this.NUMBER_TEN[(num / 10).toInt32()! - 1]
            let ones = this.NUMBER[(num % 10).toInt32()!]
            if (ones == "") {
                return tens
            }
            return "${tens} ${ones}"
        }
    }

    public func trans_three(s: String): String {
        if (s.size != 3) {
            return ""
        }
        let num = s.toInt64()!.getOrThrow()
        if (num == 0) {
            return ""
        }

        let hundred = this.NUMBER[(num / 100).toInt32()!]
        let remainder = num % 100
        var result = ""

        if (hundred != "") {
            result += "${hundred} HUNDRED"
            if (remainder != 0) {
                result += " AND ${this.trans_two(remainder.toString())}"
            }
        } else if (remainder != 0) {
            result += this.trans_two(remainder.toString())
        }

        return result
    }

    public func parse_more(i: Int64): String {
        if (i >= 0 && i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i.toInt32()!]
        }
        return ""
    }
}

