                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        if (x == None<String>()) {
            return "ZERO ONLY"
        }
        let s = x.getOrThrow()
        return this.format_string(s) + " ONLY"
    }

    public func format_string(x: String): String {
        var len = x.size
        var result = ArrayList<String>()
        var i = 0

        while (i < len) {
            var start = i
            var end = i + 3
            if (end > len) {
                end = len
            }
            let chunk = x[start..end]
            let num = Int64.parse(chunk) ?? 0
            var words = ""

            if (num > 0) {
                if (num < 100) {
                    words = this.trans_two(num.toString())
                } else {
                    words = this.trans_three(num.toString())
                }

                let pos = (len - end) / 3
                if (pos < this.NUMBER_MORE.size && pos > 0) {
                    words += " " + this.NUMBER_MORE[pos]
                }
            }

            if (!words.isEmpty()) {
                result.add(words)
            }

            i += 3
        }

        // Reverse and join with spaces
        var reversed = ArrayList<String>()
        for (j in result.size - 1..-1:1) {
            reversed.add(result[j])
        }

        return reversed.join(" ")
    }

    public func trans_two(s: String): String {
        let num = Int64.parse(s) ?? 0
        if (num < 10) {
            return this.NUMBER[num.toInt() as Int]
        } else if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let ten = num / 10
            let one = num % 10
            var result = this.NUMBER_TEN[ten - 1]
            if (one > 0) {
                result += " " + this.NUMBER[one.toInt() as Int]
            }
            return result
        }
    }

    public func trans_three(s: String): String {
        let num = Int64.parse(s) ?? 0
        let hundred = num / 100
        let remainder = num % 100
