    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        return match (x) {
            case None => "INVALID INPUT"
            case Some(s) => this.format_string(s)
        }
    }

    public func format_string(x: String): String {
        let parseInt: Option<Int64> = x.toInt64()
        return match (parseInt) {
            case None => "INVALID NUMBER"
            case Some(num) => 
                if (num == 0) {
                    "ZERO ONLY"
                } else {
                    this.convert_number(num) + " ONLY"
                }
        }
    }

    private func convert_number(num: Int64): String {
        if (num < 100) {
            return this.trans_two(num.toString())
        } else if (num < 1000) {
            return this.trans_three(num.toString())
        } else {
            let magnitude = (num.tology() as Float64).log10() / 3.0
            let highest = (magnitude.toInt64() - if (magnitude % 1 == 0) { 0 } else { 1 })
            let group: Int64 = if (highest < 0) { 0 } else { highest }
            let power = 1000G.pow(group)
            let part = num / power
            let remainder = num % power
            let part_str = this.convert_number(part)
            let suffix = this.NUMBER_MORE[group]
            let result: String
            if (remainder == 0) {
                result = part_str + " " + suffix
            } else {
                result = part_str + " " + suffix + " AND " + this.convert_number(remainder)
            }
            return result
        }
    }

    public func trans_two(s: String): String {
        let num = s.toInt64() ?? 0
        if (num < 10) {
            return this.NUMBER[num]
        } else if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let ten = num / 10
            let one = num % 10
            let ten_str = this.NUMBER_TEN[ten - 1]
            let one_str = if (one == 0) { "" } else { " " + this.NUMBER[one] }
            return ten_str + one_str
        }
    }

    public func trans_three(s: String): String {
        let num = s.toInt64() ?? 0
        if (num < 100) {
            return this.trans_two(num.toString())
        } else {
            let hundred = num / 100
            let remainder = num % 100
            let hundred_str = this.NUMBER[hundred] + " HUNDRED"
            let remainder_str = if (remainder == 0) { "" } else { " AND " + this.trans_two(remainder.toString()) }
            return hundred_str + remainder_str
        }
    }

    public func parse_more(i: Int64): String {
        return this.NUMBER_MORE[i]
    }
}

