class NumberWordFormatter {
    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                           "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case None<String>() => "INVALID NUMBER"
            case Some<String>(s) => this.format_string(s)
        }
    }

    public func format_string(x: String): String {
        if (x.isEmpty()) {
            return "INVALID NUMBER"
        }

        var s = x
        var has_decimal = false
        var decimal_part = ""

        if (s.contains(".")) {
            let parts = s.split(".")
            s = parts[0]
            if (parts.size > 1) {
                decimal_part = parts[1]
                has_decimal = true
            }
        }

        if (!this.is_all_digits(s)) {
            return "INVALID NUMBER"
        }

        let num = this.parse_long(s) ?? 0
        var result = ""

        if (num == 0) {
            return "ZERO ONLY"
        }

        let chunks = ArrayList<String>()
        var n = num
        var remainder: Int64 = 0
        var i = 0

        while (n > 0) {
            remainder = n % 1000
            n = n / 1000
            let chunk = this.trans_three(remainder.toString())
            if (chunk.isNotEmpty()) {
                let suffix = if (i > 0) { " " + this.NUMBER_MORE[i] } else { "" }
                chunks.add(0, chunk + suffix)
            }
            i += 1
        }

        result = chunks.join(" ")

        if (has_decimal && decimal_part.isNotEmpty()) {
            if (!this.is_all_digits(decimal_part)) {
                return "INVALID NUMBER"
            }
            let decimal_num = this.parse_long(decimal_part) ?? 0
            let decimal_str = this.trans_three(decimal_num.toString())
            if (decimal_str.isNotEmpty()) {
                result += " AND " + decimal_str + " ONLY"
            } else {
                result += " ONLY"
            }
        } else {
            result += " ONLY"
        }

        return result
    }

    public func trans_two(s: String): String {
        let num = this.parse_long(s) ?? 0

        if (num < 10) {
            return this.NUMBER[num]
        } else if (num < 20) {
            return this.NUMBER_TEEN[num - 10]
        } else {
            let tens = num / 10
            let ones = num % 10
            var result = this.NUMBER_TEN[tens - 1]
            if (ones != 0) {
                result += " " + this.NUMBER[ones]
            }
            return result
        }
    }

    public func trans_three(s: String): String {
        let num = this.parse_long(s) ?? 0

        if (num == 0) {
            return ""
        } else if (num < 100) {
            return this.trans_two(num.toString())
        } else {
            let hundreds = num / 100
            let remainder = num % 100
            var result = this.NUMBER[hundreds] + " HUNDRED"
            if (remainder != 0) {
                let two_digit = this.trans_two(remainder.toString())
                if (two_digit.isNotEmpty()) {
                    result += " AND " + two_digit
                }
            }
            return result
        }
    }

    public func parse_more(i: Int64): String {
        return this.NUMBER_MORE[i]
    }

    // Helper functions (not part of original interface but needed for implementation)
    private func parse_long(s: String): Option<Int64> {
        var result: Int64 = 0
        var negative = false
        var start = 0

        if (s.isEmpty()) {
            return None<Int64>()
        }

        if (s[0] == r'-') {
            negative = true
            start = 1
        } else if (s[0] == r'+') {
            start = 1
        }

        for (i in start..<s.size) {
            let c = s[i]
            if (c < r'0' || c > r'9') {
                return None<Int64>()
            }
            let digit = c - r'0'
            result = result * 10 + digit

            // Check for overflow (simplified check)
            if (negative && result > -(Int64.MIN_VALUE)) {
                return None<Int64>()
            }
            if (!negative && result > Int64.MAX_VALUE) {
                return None<Int64>()
            }
        }

        return if (negative) { Some<Int64>(-result) } else { Some<Int64>(result) }
    }

    private func is_all_digits(s: String): Bool {
        if (s.isEmpty()) {
            return false
        }

        for (i in 0..<s.size) {
            let c = s[i]
            if (i == 0 && (c == r'-' || c == r'+')) {
                continue
            }
            if (c < r'0' || c > r'9') {
                return false
            }
        }
        return true
    }
}

// Helper function to split string by delimiter (since Cangjie doesn't have built-in split)
func split(s: String, delimiter: Rune): ArrayList<String> {
    let result = ArrayList<String>()
    let chars = s.toRuneArray()
    var current_word = ""

    for (c in chars) {
        if (c == delimiter) {
            result.add(current_word)
            current_word = ""
        } else {
            current_word += String.fromRune(c)
        }
    }
    result.add(current_word)
    return result
}

