        var i = 0
        let n = runes.size

        while (i < n) {
            if (runes[i] == r'&' && i + 3 < n && runes[i + 1] == r'#') {
                // Check for numeric entity (decimal or hex)
                var is_hex = false
                if (i + 4 < n && runes[i + 2] == r'x') {
                    is_hex = true
                    i += 2 // skip &# and x
                } else {
                    i += 1 // skip &#
                }

                // Extract digits
                var num_start = i
                while (i < n && 
                       (if (is_hex) { 
                            NumericEntityUnescaper.is_hex_char(runes[i])
                        } else {
                            runes[i].isDigit()
                        })) {
                    i += 1
                }

                if (i > num_start && i < n && runes[i] == r';') {
                    let num_str = String.fromRuneArray(Array.slice(runes, num_start, i))
                    let code_point = if (is_hex) {
                        num_str.toUInt64(radix: 16) ?? 0
                    } else {
                        num_str.toUInt64() ?? 0
                    }

                    // Convert to Rune and add to result
                    if (code_point <= 0x10FFFF) {
                        result.add(Unicode.toRune(code_point))
                    }
                    i += 1 // skip ;
                    continue
