                if (j < runes.size && runes[j] == r';') {
                    let num = if (is_hex) {
                        num_str.toUInt64(16) ?? 0
                    } else {
                        num_str.toUInt64(10) ?? 0
                    }
                    result += num.toChar().toString()
                    i = j + 1
                } else {
                    result += runes[i].toString()
                    i += 1
                }
            } else {
                result += runes[i].toString()
                i += 1
            }
        }

        return result
    }

    public static func is_hex_char(char: Rune): Bool {
        return (char >= r'0' && char <= r'9') || 
               (char >= r'a' && char <= r'f') || 
               (char >= r'A' && char <= r'F')
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let result = ArrayList<Rune>()
        var i = 0
        let runes = string.toRuneArray()

        while (i < runes.size) {
            if (i + 1 < runes.size && runes[i] == r'&' && runes[i+1] == r'#') {
                var j = i + 2
                var is_hex = false
                var radix = 10

                if (j < runes.size && runes[j] == r'x') {
                    is_hex = true
                    j += 1
                    radix = 16
                }

                var num_str = ArrayList<Rune>()
                while (j < runes.size && runes[j] != r';') {
                    num_str.add(runes[j])
                    j += 1
                }

                if (j < runes.size && runes[j] == r';') {
                    let num_rune_array = ArrayList<Rune>()
                    for (k in 0..num_str.size) {
                        num_rune_array.add(num_str[k])
                    }
                    let num_str_final = String.fromRuneArray(num_rune_array)

                    if (let code_point = num_str_final.toUInt64(radix: radix)) {
                        if (let char = Rune.fromCodePoint(code_point)) {
                            result.add(char)
                            i = j + 1
                            continue
                        }
                    }
                }
            }
            result.add(runes[i])
            i += 1
        }

        return String.fromRuneArray(result.toArray())
    }

    public static func is_hex_char(char: Rune): Bool {
        return match (char) {
            case r'0'..r'9' => true
            case r'a'..r'f' => true
            case r'A'..r'F' => true
            case _ => false
        }
    }
}

