class Order {
    let menu: ArrayList<Dish>
    let selected_dishes: ArrayList<Dish>
    let sales: HashMap<String, Float64>

    public init() {
        this.menu = ArrayList<Dish>()
        this.selected_dishes = ArrayList<Dish>()
        this.sales = HashMap<String, Float64>()
    }

    public func add_dish(dish: Dish): Bool {
        // Check if dish exists in menu and has sufficient quantity
        var found = false
        var menuIndex = -1

        for (i in 0..<this.menu.size) {
            if (this.menu[i] == dish) {
                found = true
                menuIndex = i
                break
            }
        }

        if (!found) {
            return false
        }

        // Check if requested count is available
        if (dish.count > this.menu[menuIndex].count) {
            return false
        }

        // Decrease menu count
        var updatedMenuDish = Dish(dish: dish.dish, price: dish.price, count: this.menu[menuIndex].count - dish.count)
        this.menu[menuIndex] = updatedMenuDish

        // Add to selected dishes (need to find if dish already exists)
        var selectedIndex = -1
        for (i in 0..<this.selected_dishes.size) {
            if (this.selected_dishes[i] == dish) {
                selectedIndex = i
                break
            }
        }

        if (selectedIndex != -1) {
            // Update existing selected dish
            var existingDish = this.selected_dishes[selectedIndex]
            var updatedSelectedDish = Dish(dish: existingDish.dish, 
                                         price: existingDish.price, 
                                         count: existingDish.count + dish.count)
            this.selected_dishes[selectedIndex] = updatedSelectedDish
        } else {
            // Add new selected dish
            this.selected_dishes.add(dish)
        }

        return true
    }

    public func calculate_total(): Float64 {
        var total: Float64 = 0.0

        for (i in 0..<this.selected_dishes.size) {
            let currentDish = this.selected_dishes[i]
            let basePrice = Float64(currentDish.price * currentDish.count)

            let saleFactor = match (this.sales.get(currentDish.dish)) {
                case Some<Float64>(factor) => factor
                case None<Float64> => 1.0
            }

            total += basePrice * saleFactor
        }

        return total
    }

    public func checkout(): Option<Float64> {
        if (this.selected_dishes.size == 0) {
            return None<Float64>()
        }

        let total = this.calculate_total()
        return Some<Float64>(total)
    }
}

