class Order {
    let menu: ArrayList<Dish>
    let selected_dishes: ArrayList<Dish>
    let sales: HashMap<String, Float64>

    public init() {
        this.menu = ArrayList<Dish>()
        this.selected_dishes = ArrayList<Dish>()
        this.sales = HashMap<String, Float64>()
    }

    public func add_dish(dish: Dish): Bool {
        for (i in 0..<menu.size) {
            let menu_dish = menu[i]
            if (menu_dish == dish) {
                if (menu_dish.count >= dish.count) {
                    // Update menu count and add to selected
                    menu[i] = Dish(dish: menu_dish.dish, 
                                  price: menu_dish.price, 
                                  count: menu_dish.count - dish.count)
                    selected_dishes.add(dish)
                    return true
                } else {
                    return false
                }
            }
        }
        return false
    }

    public func calculate_total(): Float64 {
        var total: Float64 = 0.0
        let dish_names = HashMap<String, Int64>() // Temporary mapping for count aggregation

        // First aggregate counts per dish
        for (sdish in selected_dishes) {
            if (dish_names.contains(sdish.dish)) {
                let current_count = dish_names[sdish.dish]!
                dish_names[sdish.dish] = current_count + sdish.count
            } else {
                dish_names[sdish.dish] = sdish.count
            }
        }

        // Then calculate total with menu price and sales
        for (dish_name, count in dish_names) {
            let found = false
            for (mdish in menu) {
                if (mdish.dish == dish_name) {
                    let price_per_unit = Float64(mdish.price)
                    let sales_factor = sales.get(dish_name).getOrThrow(1.0)
                    total += price_per_unit * Float64(count) * sales_factor
                    found = true
                    break
                }
            }
            // In real implementation, might want to handle missing dishes
        }

        return total
    }

    public func checkout(): Option<Float64> {
        if (selected_dishes.size == 0) {
            return None<Float64>()
        } else {
            return Some<Float64>(calculate_total())
        }
    }
}

