        }
        var allDigits = true
        for (i in 0..11) {
            let c = phoneNumber[i]
            match (c) {
                case r'0'..r'9' => continue
                case _ => allDigits = false
            }
        }
        return if (allDigits) { Some<String>(phoneNumber) } else { None<String>() }
    }
