        if (this.boxes.size != this.target_count) {
            this.is_game_over = false
            return false
        }

        var win = true
        for (box in this.boxes) {
            var is_on_target = false
            for (target in this.targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    is_on_target = true
                    break
                }
            }
            if (!is_on_target) {
                win = false
                break
            }
        }

        this.is_game_over = win
