                new_col -= 1
            }
            case "d" => {
                new_col += 1
            }
            case _ => {
                return false
            }
        }

        // Check if new position is out of bounds or wall
        if (new_row < 0 || new_row >= this.map.size || 
            new_col < 0 || new_col >= this.map[0].size || 
            this.map[new_row][new_col] == "#") {
            return false
        }

