        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (r in 0..map.size) {
                for (c in 0..map[r].size) {
                    let tile = map[r][c]
                    match (tile) {
                        case "O" => {
                            this.player_row = r
                            this.player_col = c
                        }
                        case "G" => {
                            this.targets.add(ArrayList<Int64>([r, c]))
                            this.target_count = this.target_count + 1
                        }
                        case "X" => {
                            this.boxes.add(ArrayList<Int64>([r, c]))
                        }
                        case _ => {} // do nothing
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var box_count: Int64 = 0
        for (box in this.boxes) {
            var on_target: Bool = false
            for (target in this.targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    on_target = true
                    break
                }
            }
            if (!on_target) {
                this.is_game_over = false
                return false
            }
            box_count = box_count + 1
        }
        this.is_game_over = box_count == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let dr: Int64 = match (direction) {
            case "w" => -1
            case "s" => 1
            case _ => 0 // handled in match below
        }
        let dc: Int64 = match (direction) {
            case "a" => -1
            case "d" => 1
            case _ => 0 // handled in match below
        }

        // Validate direction
        if (!(direction == "w" || direction == "a" || direction == "s" || direction == "d")) {
            return false
        }

        let new_row: Int64 = this.player_row + dr
        let new_col: Int64 = this.player_col + dc
        let current_tile = this.map[new_row.toInt()][new_col.toInt()]

        // Check for walls
        if (current_tile == "#") {
            return false
        }

        // Check if we're pushing a box
        var pushing_box_index: ?Int64 = None<Int64>
        for (i in 0..this.boxes.size) {
            let box = this.boxes[i]
            if (box[0] == new_row && box[1] == new_col) {
                pushing_box_index = Some(i.toInt())
                break
            }
        }

        if (let Some(i) = pushing_box_index) {
            let box_row = this.boxes[i][0]
            let box_col = this.boxes[i][1]
            let new_box_row = box_row + dr
            let new_box_col = box_col + dc

            // Check if box would hit wall or another box
            if (this.map[new_box_row.toInt()][new_box_col.toInt()] == "#") {
                return false
            }

            // Check if another box would be in the way
            for (other_box in this.boxes) {
                if (other_box != this.boxes[i] && other_box[0] == new_box_row && other_box[1] == new_box_col) {
                    return false
                }
            }

            // Move the box
            this.boxes[i][0] = new_box_row
            this.boxes[i][1] = new_box_col
        }

        // Move the player
        this.player_row = new_row
        this.player_col = new_col

        // Check if we've won
        return this.check_win()
    }

    // Helper method to print the map (not in original spec but useful for testing)
    public func print_map() {
        for (r in 0..this.map.size) {
            for (c in 0..this.map[r].size) {
                let tile = this.map[r][c]
                var output: String = tile
                let is_player = (r == this.player_row && c == this.player_col)
                let is_box = false
                for (box in this.boxes) {
                    if (box[0] == r.toInt() && box[1] == c.toInt()) {
                        is_box = true
                        break
                    }
                }

                if (is_player) {
                    output = "O"
                } else if (is_box) {
                    output = "X"
                } else if (tile == "G") {
                    var box_on_target = false
                    for (box in this.boxes) {
                        if (box[0] == r.toInt() && box[1] == c.toInt()) {
                            box_on_target = true
                            break
                        }
                    }
                    if (box_on_target) {
                        output = "*" // Box on target
                    } else {
                        output = "G"
                    }
                }
                print(output)
                print(" ")
            }
            println()
        }
    }
}

