        this.is_game_over = (boxes_on_target == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_row = this.player_row
        var new_col = this.player_col

        match (direction) {
            case "w" => {
                new_row -= 1
            }
            case "s" => {
                new_row += 1
            }
            case "a" => {
                new_col -= 1
            }
            case "d" => {
                new_col += 1
            }
            case _ => {
                return false
            }
        }

        // Check boundary and wall collision
        if (new_row < 0 || new_row >= this.map.size || 
            new_col < 0 || new_col >= this.map[new_row].size || 
            this.map[new_row][new_col] == "#") {
            return false
        }

        // Check if moving to box
        var box_index = -1
        for ((index, box) in this.boxes.enumerate()) {
            if (box[0] == new_row && box[1] == new_col) {
                box_index = index
                break
            }
        }

        if (box_index != -1) {
            var box_new_row = new_row
            var box_new_col = new_col

            match (direction) {
                case "w" => {
                    box_new_row -= 1
                }
                case "s" => {
                    box_new_row += 1
                }
                case "a" => {
                    box_new_col -= 1
                }
                case "d" => {
                    box_new_col += 1
                }
                case _ => {}
            }

            // Check if box movement is valid
            if (box_new_row < 0 || box_new_row >= this.map.size || 
                box_new_col < 0 || box_new_col >= this.map[box_new_row].size || 
                this.map[box_new_row][box_new_col] == "#") {
                return false
            }

            // Update box position
            this.boxes[box_index][0] = box_new_row
            this.boxes[box_index][1] = box_new_col
        }

        // Update player position
        this.player_row = new_row
        this.player_col = new_col

        // Check win condition after move
        this.is_game_over = this.check_win()
        return this.is_game_over
    }

    public func print_map(): Unit {
        // Create a temporary map to display
        let display_map = ArrayList<ArrayList<String>>()
        for (row in 0..this.map.size) {
            display_map.add(ArrayList<String>())
            for (col in 0..this.map[row].size) {
                // Check if this is player position
                var is_player = (row == this.player_row && col == this.player_col)
                if (is_player) {
                    display_map[row].add("O")
                    continue
                }

                // Check if this is box position
                var is_box = false
                for (box in this.boxes) {
                    if (box[0] == row && box[1] == col) {
                        is_box = true
                        break
                    }
                }
                if (is_box) {
                    // Check if this is also target (show GX for box on target)
                    var on_target = false
                    for (target in this.targets) {
                        if (target[0] == row && target[1] == col) {
                            on_target = true
                            break
                        }
                    }
                    if (on_target) {
                        display_map[row].add("X") // In original game, might show X for box on target
                    } else {
                        display_map[row].add("X")
                    }
                    continue
                }

                // Check if this is target position (but not covered by box)
                var is_target = false
                for (target in this.targets) {
                    if (target[0] == row && target[1] == col) {
                        is_target = true
                        break
                    }
                }
                if (is_target) {
                    display_map[row].add("G")
                    continue
                }

                // Show original tile
                display_map[row].add(this.map[row][col])
            }
        }

        // Print the map
        for (row in display_map) {
            for ((col_index, tile) in row.enumerate()) {
                print(tile)
                if (col_index < row.size - 1) {
                    print(" ")
                }
            }
            println()
        }
    }
}

import std.collection.ArrayList
import std.collection.HashSet

class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                for (j in 0..map[i].size) {
                    let cell = map[i][j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        this.targets.add(ArrayList<Int64>([i, j]))
                        this.target_count = this.target_count + 1
                    } else if (cell == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        if (this.is_game_over) {
            return true
        }

        let box_positions = HashSet<ArrayList<Int64>>()
        for (box in this.boxes) {
            box_positions.add(box)
        }

        let target_positions = HashSet<ArrayList<Int64>>()
        for (target in this.targets) {
            target_positions.add(target)
        }

        var matched = 0
        for (box in box_positions) {
            if (target_positions.contains(box)) {
                matched = matched + 1
            }
        }

        this.is_game_over = matched == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let (dr, dc) = match (direction) {
            case "w" => (-1, 0)
            case "s" => (1, 0)
            case "a" => (0, -1)
            case "d" => (0, 1)
            case _ => (0, 0) // shouldn't happen in valid game
        }

        let new_row = this.player_row + dr
        let new_col = this.player_col + dc

        // Check boundaries
        if (new_row < 0 || new_row >= this.map.size || new_col < 0 || new_col >= this.map[0].size) {
            return false
        }

        let cell = this.map[new_row][new_col]

        // If moving to empty space
        if (cell == " ") {
            this.player_row = new_row
            this.player_col = new_col
        } 
        // If moving to box
        else if (cell == "X") {
            let box_new_row = new_row + dr
            let box_new_col = new_col + dc

            // Check boundaries for box movement
            if (box_new_row < 0 || box_new_row >= this.map.size || box_new_col < 0 || box_new_col >= this.map[0].size) {
                return false
            }

            let box_dest = this.map[box_new_row][box_new_col]
            if (box_dest == " " || box_dest == "G") { // Can push to empty space or target
                this.player_row = new_row
                this.player_col = new_col

                // Update box position
                func find_box_index(box_row: Int64, box_col: Int64): Int64 {
                    for (i in 0..this.boxes.size) {
                        if (this.boxes[i][0] == box_row && this.boxes[i][1] == box_col) {
                            return i
                        }
                    }
                    return -1
                }

                let box_idx = find_box_index(box_row: new_row, box_col: new_col)
                if (box_idx != -1) {
                    this.boxes[box_idx][0] = box_new_row
                    this.boxes[box_idx][1] = box_new_col
                }
            } else {
                return false // Wall or something else - can't push
            }
        } 
        // If moving to wall or something else
        else if (cell == "#" || cell == "G") { // Can walk on target (but not box on target in move)
            if (cell == "G") { // Just stepping on target doesn't change game state
                this.player_row = new_row
                this.player_col = new_col
            }
            return false
        }

        return this.check_win()
    }

    // Helper function for testing (not part of original spec but useful for doctests)
    public func print_map(): Unit {
        // This is a simplified version that doesn't show actual box/target positions
        // Just for demonstration purposes
        for (i in 0..this.map.size) {
            var line = ""
            for (j in 0..this.map[i].size) {
                let is_player = (i == this.player_row && j == this.player_col)
                let is_box_here = false // Would need to check all boxes in real implementation
                let is_target_here = false // Would need to check all targets in real implementation

                if (is_player) {
                    line = line + "O"
                } else if (is_box_here) {
                    line = line + "X"
                } else if (is_target_here) {
                    line = line + "G"
                } else {
                    line = line + this.map[i][j]
                }
            }
            println(line)
        }
    }
}

