    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                let row = map[i]
                for (j in 0..row.size) {
                    let cell = row[j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        targets.add([i, j])
                        this.target_count += 1
                    } else if (cell == "X") {
                        boxes.add([i, j])
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        if (this.target_count == 0) return false

        var matched = 0
        for (i in 0..boxes.size) {
            let box = boxes[i]
            var found = false
            for (j in 0..targets.size) {
                let target = targets[j]
                if (box[0] == target[0] && box[1] == target[1]) {
                    found = true
                    break
                }
            }
            if (found) matched += 1
        }

        this.is_game_over = matched == this.target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_row = this.player_row
        var new_col = this.player_col

        match (direction) {
            case "w" => {
                new_row -= 1
            }
            case "s" => {
                new_row += 1
            }
            case "a" => {
                new_col -= 1
            }
            case "d" => {
                new_col += 1
            }
            case _ => {
                return false
            }
        }

        // Check wall boundary
        if (new_row < 0 || new_row >= map.size || 
            new_col < 0 || new_col >= map[0].size || 
            map[new_row][new_col] == "#") {
            return false
        }

        // Check if moving to box
        var box_index = -1
        for (i in 0..boxes.size) {
            if (boxes[i][0] == new_row && boxes[i][1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            let box = boxes[box_index]
            let box_new_row = new_row + (new_row - this.player_row)
            let box_new_col = new_col + (new_col - this.player_col)

            // Check if box can move
            if (box_new_row < 0 || box_new_row >= map.size || 
                box_new_col < 0 || box_new_col >= map[0].size || 
                map[box_new_row][box_new_col] == "#") {
                return false
            }

            // Move box
            boxes[box_index] = [box_new_row, box_new_col]
        }

        // Move player
        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }
}

