                        this.target_count = this.target_count + 1
                    } else if (cell == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        if (this.boxes.size != this.targets.size) {
            return false
        }

        var win = true
        for (i in 0..this.boxes.size) {
            let box = this.boxes[i]
            var found = false
            for (j in 0..this.targets.size) {
                let target = this.targets[j]
                if (box[0] == target[0] && box[1] == target[1]) {
                    found = true
                    break
                }
            }
            if (!found) {
                win = false
                break
            }
        }
        this.is_game_over = win
        return win
    }

    public func move(direction: String): Bool {
        var new_row = this.player_row
        var new_col = this.player_col

        match (direction) {
            case "w" => { new_row = new_row - 1 }
            case "s" => { new_row = new_row + 1 }
            case "a" => { new_col = new_col - 1 }
            case "d" => { new_col = new_col + 1 }
            case _ => { return this.is_game_over }
        }

        let current_row = this.player_row
        let current_col = this.player_col

        // Check if new position is wall or out of bounds
        if (new_row < 0 || new_row >= this.map.size || 
            new_col < 0 || new_col >= this.map[0].size || 
            this.map[new_row][new_col] == "#") {
            return this.is_game_over
        }

        // Check if next position is a box
        var box_index = -1
        for (i in 0..this.boxes.size) {
            let box = this.boxes[i]
            if (box[0] == new_row && box[1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            let box = this.boxes[box_index]
            let box_new_row = new_row + (new_row - current_row)
            let box_new_col = new_col + (new_col - current_col)

            // Check if box can be pushed (not wall and not out of bounds)
            if (box_new_row < 0 || box_new_row >= this.map.size || 
                box_new_col < 0 || box_new_col >= this.map[0].size || 
                this.map[box_new_row][box_new_col] == "#") {
                return this.is_game_over
            }

            // Update box position
            this.boxes[box_index][0] = box_new_row
            this.boxes[box_index][1] = box_new_col
        }

        // Update player position
        this.player_row = new_row
        this.player_col = new_col

        // Check if game is won
        return this.check_win()
    }
}

