                        }
                        case _ => {}
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        if (this.boxes.size == 0) {
            return false
        }

        var win: Bool = true
        for (box in this.boxes) {
            var is_target: Bool = false
            for (target in this.targets) {
                if (box[0] == target[0] && box[1] == target[1]) {
                    is_target = true
                    break
                }
            }
            if (!is_target) {
                win = false
                break
            }
        }
        this.is_game_over = win
        return win
    }

