import std.collection.ArrayList
import std.collection.HashMap

class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                let row = map[i]
                for (j in 0..row.size) {
                    let cell = row[j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        this.targets.add(ArrayList<Int64>([i, j]))
                        this.target_count = this.target_count + 1
                    } else if (cell == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        if (this.target_count == 0) {
            this.is_game_over = false
            return false
        }

        var box_on_target = 0
        let target_hash = HashMap<String, Bool>()
        for (target in this.targets) {
            let key = "${target[0]},${target[1]}"
            target_hash[key] = true
        }

        for (box in this.boxes) {
            let key = "${box[0]},${box[1]}"
            if (target_hash.get(key) != None) {
                box_on_target = box_on_target + 1
            }
        }

        this.is_game_over = (box_on_target == this.target_count)
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_row = this.player_row
        var new_col = this.player_col
        let move_map = HashMap<String, (Int64, Int64)>([
            ("w", (-1, 0)),
            ("s", (1, 0)),
            ("a", (0, -1)),
            ("d", (0, 1))
        ])

        if (move_map.get(direction) == None) {
            return false
        }

        let (dr, dc) = move_map[direction] ?? (0, 0)
        new_row = this.player_row + dr
        new_col = this.player_col + dc

        // Check wall collision
        if (new_row < 0 || new_row >= this.map.size || 
            new_col < 0 || new_col >= this.map[0].size || 
            this.map[new_row][new_col] == "#") {
            return false
        }

        // Check box interaction
        var box_index = -1
        for (i in 0..this.boxes.size) {
            if (this.boxes[i][0] == new_row && this.boxes[i][1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            let box = this.boxes[box_index]
            let new_box_row = box[0] + dr
            let new_box_col = box[1] + dc

            // Check if box can move (not wall or out of bounds)
            if (new_box_row < 0 || new_box_row >= this.map.size || 
                new_box_col < 0 || new_box_col >= this.map[0].size || 
                this.map[new_box_row][new_box_col] == "#") {
                return false
            }

            // Check if another box would block the move
            for (other_box in this.boxes) {
                if (other_box != box && other_box[0] == new_box_row && other_box[1] == new_box_col) {
                    return false
                }
            }

            // Move the box
            box[0] = new_box_row
            box[1] = new_box_col
        }

        // Move the player
        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }

