import std.collection.ArrayList
import std.sort.*

class PushBoxGame {
    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for (i in 0..map.size) {
                let row = map[i]
                for (j in 0..row.size) {
                    let cell = row[j]
                    if (cell == "O") {
                        this.player_row = i
                        this.player_col = j
                    } else if (cell == "G") {
                        this.targets.add(ArrayList<Int64>([i, j]))
                        this.target_count = this.target_count + 1
                    } else if (cell == "X") {
                        this.boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var boxes_on_target: Int64 = 0
        for (i in 0..boxes.size) {
            let box = boxes[i]
            var on_target: Bool = false
            for (j in 0..targets.size) {
                if (box[0] == targets[j][0] && box[1] == targets[j][1]) {
                    on_target = true
                    break
                }
            }
            if (on_target) {
                boxes_on_target = boxes_on_target + 1
            }
        }
        this.is_game_over = boxes_on_target == target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        let new_row: Int64
        let new_col: Int64

        match (direction) {
            case "w" => { new_row = this.player_row - 1; new_col = this.player_col; }
            case "s" => { new_row = this.player_row + 1; new_col = this.player_col; }
            case "a" => { new_row = this.player_row; new_col = this.player_col - 1; }
            case "d" => { new_row = this.player_row; new_col = this.player_col + 1; }
            case _ => { return false; }
        }

        // Check wall collision
        let row_size = map[0].size
        let map_size = map.size
        if (new_row < 0 || new_row >= map_size || new_col < 0 || new_col >= row_size) {
            return false
        }
        if (map[new_row as Int64][new_col] == "#") {
            return false
        }

        // Check if moving into box
        var box_index: Int64 = -1
        for (i in 0..boxes.size) {
            if (boxes[i][0] == new_row && boxes[i][1] == new_col) {
                box_index = i
                break
            }
        }

        if (box_index != -1) {
            // Calculate box's new position
            let box_new_row: Int64
            let box_new_col: Int64
            match (direction) {
                case "w" => { box_new_row = new_row - 1; box_new_col = new_col; }
                case "s" => { box_new_row = new_row + 1; box_new_col = new_col; }
                case "a" => { box_new_row = new_row; box_new_col = new_col - 1; }
                case "d" => { box_new_row = new_row; box_new_col = new_col + 1; }
                case _ => { return false; }
            }

            // Check if box can move there
            if (box_new_row < 0 || box_new_row >= map_size || box_new_col < 0 || box_new_col >= row_size) {
                return false
            }
            if (map[box_new_row][box_new_col] == "#") {
                return false
            }

            // Check if another box is in the way
            for (other_box in boxes) {
                if (other_box[0] == box_new_row && other_box[1] == box_new_col) {
                    return false
                }
            }

            // Move the box
            boxes[box_index][0] = box_new_row
            boxes[box_index][1] = box_new_col
        }

        // Move player
        this.player_row = new_row
        this.player_col = new_col

        return this.check_win()
    }

    public func print_map(): Unit {
        // Create a copy of the map for display
        let display = ArrayList<ArrayList<String>>()
        for (i in 0..map.size) {
            let row = ArrayList<String>()
            for (j in 0..map[i].size) {
                row.add(map[i][j])
            }
            display.add(row)
        }

        // Mark boxes and player on display
        display[player_row][player_col] = "O"
        for (box in boxes) {
            if (display[box[0]][box[1]] != "O") {
                display[box[0]][box[1]] = "X"
            }
        }

        // Print the map
        for (row in display) {
            var line = ""
            for (cell in row) {
                line = line + cell + " "
            }
            println(line.trim())
        }
    }
}

