import std.collection.ArrayList
import std.random.Random

class Snake {
    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0]
        let new_x = head[0] + direction[0]
        let new_y = head[1] + direction[1]

        // Check boundaries
        if (new_x < 0 || new_x >= this.SCREEN_WIDTH || 
            new_y < 0 || new_y >= this.SCREEN_HEIGHT) {
            this.reset()
            return
        }

        // Check collision with body
        for (i in 1..<this.positions.size) {
            let part = this.positions[i]
            if (part[0] == new_x && part[1] == new_y) {
                this.reset()
                return
            }
        }

        // Create new head
        let new_head = ArrayList<Int64>([new_x, new_y])

        // Check if we eat food
        let eating = (new_x == this.food_position[0] && new_y == this.food_position[1])

        if (eating) {
            // Increase length and score
            this.length += 1
            this.score += 10
            // Generate new food (but don't call here, caller should handle)
        } else {
            // Normal move, remove tail
            this.positions.remove(at: this.positions.size - 1)
        }

        // Add new head
        this.positions.add(new_head, at: 0)

        // If eating was true, caller should call eat_food() to generate new food
    }

    public func random_food_position(): Unit {
        let random = Random()
        while (true) {
            let new_x = random.nextInt(min: 0, max: this.SCREEN_WIDTH)
            let new_y = random.nextInt(min: 0, max: this.SCREEN_HEIGHT)
            let new_pos = ArrayList<Int64>([new_x, new_y])

            // Check if position is on snake
            var valid = true
            for (part in this.positions) {
                if (part[0] == new_pos[0] && part[1] == new_pos[1]) {
                    valid = false
                    break
                }
            }

            if (valid) {
                this.food_position = new_pos
                break
            }
        }
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 10
        this.random_food_position()
    }
}

