    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0]
        let newX = head[0] + direction[0] * this.BLOCK_SIZE
        let newY = head[1] + direction[1] * this.BLOCK_SIZE
        let newHead = ArrayList<Int64>([newX, newY])

        // Check collision with screen boundaries
        if (newX < 0 || newX >= this.SCREEN_WIDTH || 
            newY < 0 || newY >= this.SCREEN_HEIGHT) {
            this.reset()
            return
        }

        // Check collision with self
        for (i in 1..<this.positions.size) {
            if (this.positions[i][0] == newX && this.positions[i][1] == newY) {
                this.reset()
                return
            }
        }

        // Add new head
        this.positions.add(0, newHead)

        // Check if food is eaten
        if (newX == this.food_position[0] && newY == this.food_position[1]) {
            this.score += 10
