        if new_x == food[0] && new_y == food[1] {
            this.eat_food()
        } else {
            // Remove tail if not eating
            if this.length > 1 {
                this.positions.remove(at: this.positions.size - 1)
            } else {
                this.length = 0 // Will be reset to 1 when adding new head
            }
        }

        // Add new head
        this.positions.add(new_head, at: 0)
        this.length = this.positions.size as Int64

        // Check collision with body
        for i in 1..<this.positions.size {
            let segment = this.positions[i]
            if new_x == segment[0] && new_y == segment[1] {
                this.reset()
                return
            }
        }

        // Check boundaries
        if new_x < 0 || new_x >= this.SCREEN_WIDTH || 
           new_y < 0 || new_y >= this.SCREEN_HEIGHT {
