            let x = (this.random.nextInt() % (this.SCREEN_WIDTH / this.BLOCK_SIZE)) * this.BLOCK_SIZE
            let y = (this.random.nextInt() % (this.SCREEN_HEIGHT / this.BLOCK_SIZE)) * this.BLOCK_SIZE
            new_position = ArrayList<Int64>([x, y])

