        }
        if (this.length > 1) {
            // If snake just ate, don't check last position (would be overlapping)
            let last_pos = this.positions[this.positions.size-1]
            // Create a copy without the last position if snake just ate
            var temp_body = ArrayList<ArrayList<Int64>>()
            for (i in 1..<this.positions.size-1) {
                temp_body.add(this.positions[i])
            }
            body_positions = temp_body
        }

        for (pos in body_positions) {
            if (pos[0] == new_x && pos[1] == new_y) {
                this.reset()
                return
            }
        }

        // Add new head
        this.positions.add(0, new_head)

        // Check if ate food
        if (new_x == this.food_position[0] && new_y == this.food_position[1]) {
            this.score += 100
