    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
        this.random = Random()
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0]
        let new_x = head[0] + direction[0] * this.BLOCK_SIZE
        let new_y = head[1] + direction[1] * this.BLOCK_SIZE
        let new_head = ArrayList<Int64>([new_x, new_y])

        // Check if new head is on food
        let food_collide = new_head[0] == this.food_position[0] && new_head[1] == this.food_position[1]

        if (food_collide) {
            // Add new head without removing tail (growth)
            this.positions.add(new_head, at: 0)
            this.length += 1
            this.score += 10
            this.eat_food()
        } else {
            // Check if new head collides with body
            for (i in 0..this.positions.size) {
                let pos = this.positions[i]
                if (new_head[0] == pos[0] && new_head[1] == pos[1]) {
                    // Collision - reset game (handled in reset())
                    this.reset()
                    return
                }
            }

            // Check boundaries
            if (new_x < 0 || new_x >= this.SCREEN_WIDTH || 
                new_y < 0 || new_y >= this.SCREEN_HEIGHT) {
                this.reset()
                return
            }

            // Move normally (add new head, remove tail)
            this.positions.add(new_head, at: 0)
            this.positions.remove(at: this.length)
        }
    }

    public func random_food_position(): Unit {
        var valid_position = false
        var new_x: Int64 = 0
        var new_y: Int64 = 0

        while (!valid_position) {
            valid_position = true
            new_x = this.random.nextInt(0, this.SCREEN_WIDTH)
            new_y = this.random.nextInt(0, this.SCREEN_HEIGHT)

            // Ensure food isn't on snake body
            for (i in 0..this.length) {
                let pos = this.positions[i]
                if (new_x == pos[0] && new_y == pos[1]) {
                    valid_position = false
                    break
                }
            }
        }

        this.food_position = ArrayList<Int64>([new_x, new_y])
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.random_food_position()
    }
}

