import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted = data.toArrayList() // Create a copy
        sort(sorted)
        if (sorted.size == 0) {
            return 0.0 // or handle error appropriately
        }
        let mid = sorted.size / 2
        if (sorted.size % 2 == 1) {
            return Float64(sorted[mid])
        } else {
            return (Float64(sorted[mid - 1]) + Float64(sorted[mid])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequency = HashMap<Int64, Int64>()
        for (num in data) {
            if (frequency.contains(num)) {
                frequency[num] = frequency[num]!! + 1
            } else {
                frequency[num] = 1
            }
        }

        var maxCount = 0
        var modes = ArrayList<Int64>()
        for (num, count in frequency) {
            if (count > maxCount) {
                maxCount = count
                modes = ArrayList<Int64>([num])
            } else if (count == maxCount) {
                modes.add(num)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let meanX = Statistics3.mean(x)
        let meanY = Statistics3.mean(y)
        if (meanX is None<Float64> || meanY is None<Float64>) {
            return None<Float64>()
        }

        var numerator = 0.0
        var denomX = 0.0
        var denomY = 0.0

        for (i in 0..x.size) {
            let diffX = Float64(x[i]) - meanX.getOrThrow()
            let diffY = Float64(y[i]) - meanY.getOrThrow()
            numerator += diffX * diffY
            denomX += diffX * diffX
            denomY += diffY * diffY
        }

        if (denomX == 0.0 || denomY == 0.0) {
            return None<Float64>()
        }

        return Some<Float64>(numerator / (sqrt(denomX) * sqrt(denomY)))
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }

        var sum = 0.0
        for (num in data) {
            sum += Float64(num)
        }
        return Some<Float64>(sum / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()

        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                if (i == j) {
                    row.add(1.0)
                } else {
                    let corr = Statistics3.correlation(data[i], data[j])
                    row.add(corr.getOrThrow())
                }
            }
            matrix.add(row)
        }

        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanVal = Statistics3.mean(data)
        if (meanVal is None<Float64>) {
            return None<Float64>()
        }

        var sumSquares = 0.0
        for (num in data) {
            let diff = Float64(num) - meanVal.getOrThrow()
            sumSquares += diff * diff
        }

        let variance = sumSquares / Float64(data.size)
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanVal = Statistics3.mean(data)
        if (meanVal is None<Float64>) {
            return None<ArrayList<Float64>>()
        }

        let stdDev = Statistics3.standard_deviation(data)
        if (stdDev is None<Float64> || stdDev.getOrThrow() == 0.0) {
            return None<ArrayList<Float64>>()
        }

        let result = ArrayList<Float64>()
        for (num in data) {
            let z = (Float64(num) - meanVal.getOrThrow()) / stdDev.getOrThrow()
            result.add(z)
        }

        return Some<ArrayList<Float64>>(result)
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted = data.clone()
        sort(sorted)
        let n = sorted.size
        if (n == 0) {
            return 0.0
        }
        if (n % 2 == 0) {
            return (Float64(sorted[n/2]) + Float64(sorted[n/2 - 1])) / 2.0
        } else {
            return Float64(sorted[n/2])
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let count_map = HashMap<Int64, Int64>()
        for (i in 0..data.size) {
            let num = data[i]
            if (count_map.contains(num)) {
                count_map[num] = count_map[num]! + 1
            } else {
                count_map.add(num, 1)
            }
        }

        var max_count = 0
        for (k, v in count_map) {
            if (v > max_count) {
                max_count = v
            }
        }

        var modes = ArrayList<Int64>()
        for (k, v in count_map) {
            if (v == max_count) {
                modes.add(k)
            }
        }

        // If all elements appear with same frequency, return empty list (no mode)
        if (max_count == 1 && count_map.size > 1) {
            return ArrayList<Int64>()
        }

        sort(modes)
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size) {
            return None<Float64>()
        }

        let mean_x = Statistics3.mean(x)
        let mean_y = Statistics3.mean(y)
        if (mean_x is None<Float64> || mean_y is None<Float64>) {
            return None<Float64>()
        }

        let sum_xy = Float64(0)
        let sum_x_sq = Float64(0)
        let sum_y_sq = Float64(0)

        for (i in 0..x.size) {
            let dx = Float64(x[i]) - mean_x.getOrThrow()
            let dy = Float64(y[i]) - mean_y.getOrThrow()
            sum_xy += dx * dy
            sum_x_sq += dx * dx
            sum_y_sq += dy * dy
        }

        if (sum_x_sq == 0.0 || sum_y_sq == 0.0) {
            return None<Float64>()
        }

        let correlation = sum_xy / sqrt(sum_x_sq * sum_y_sq)
        return Some<Float64>(correlation)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }

        var sum = Int64(0)
        for (i in 0..data.size) {
            sum += data[i]
        }

        return Some<Float64>(Float64(sum) / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
