        let freq = HashMap<Int64, Int64>()
        var max_count: Int64 = 0
        let result = ArrayList<Int64>()

        for (num in data) {
            let count = freq.get(num) ?? 0 + 1
            freq.add(num, count)
            if (count > max_count) {
                max_count = count
                result.clear()
                result.add(num)
            } else if (count == max_count) {
                // Check if already exists to avoid duplicates (though HashMap keys are unique)
                var exists = false
                for (res in result) {
                    if (res == num) {
                        exists = true
                        break
                    }
                }
                if (!exists) {
                    result.add(num)
                }
            }
        }

        // Handle empty input case
        if (data.size == 0) {
