    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()

        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                let corr = Statistics3.correlation(data[i], data[j])
                row.add(corr ?? 0.0)
            }
            matrix.add(row)
        }

        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let mean_val = Statistics3.mean(data) ?? 0.0
        if (data.size == 0) {
            return None<Float64>()
        }

        let squared_diffs = ArrayList<Float64>()
        for (num in data) {
            let diff = num.toFloat64() - mean_val
            squared_diffs.add(diff * diff)
        }

        let variance = squared_diffs.fold(0.0, { acc, val => acc + val }) / data.size.toFloat64()
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let mean_val = Statistics3.mean(data) ?? 0.0
        let std_dev = Statistics3.standard_deviation(data) ?? 0.0

        if (std_dev == 0.0 || data.size == 0) {
            return None<ArrayList<Float64>>()
        }

        let result = ArrayList<Float64>()
        for (num in data) {
            result.add((num.toFloat64() - mean_val) / std_dev)
        }

        return Some<ArrayList<Float64>>(result)
    }
}

import std.collection.ArrayList
