class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0 // Should ideally return None or handle empty case
        }
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let mid = sorted.size / 2
        if (sorted.size % 2 == 0) {
            let left = sorted[mid - 1]?.toFloat64() ?? 0.0
            let right = sorted[mid]?.toFloat64() ?? 0.0
            return (left + right) / 2.0
        } else {
            return sorted[mid]?.toFloat64() ?? 0.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if (data.size == 0) {
            return ArrayList<Int64>() // Return empty list for empty input
        }
        var freqMap = HashMap<Int64, Int64>()
        for (i in 0..data.size) {
            let num = data[i] ?? 0
            let count = freqMap.get(num) ?? 0
            freqMap.add(num, count + 1)
        }
        var modes = ArrayList<Int64>()
        var maxCount = 0
        for ((num, count) in freqMap) {
            if (count > maxCount) {
                maxCount = count
                modes = ArrayList<Int64>([num])
            } else if (count == maxCount) {
                modes.add(num)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size) {
            return None<Float64>()
        }
        let n = x.size.toFloat64()
        if (n == 0.0) {
            return None<Float64>()
        }
        let meanX = mean(x)
        let meanY = mean(y)
        if (meanX is None<Float64>() || meanY is None<Float64>()) {
            return None<Float64>()
        }
        var numerator = 0.0
        var sumXSq = 0.0
        var sumYSq = 0.0
        for (i in 0..x.size) {
            let xVal = x[i]?.toFloat64() ?? 0.0
            let yVal = y[i]?.toFloat64() ?? 0.0
            numerator += (xVal - meanX.getOrThrow()) * (yVal - meanY.getOrThrow())
            sumXSq += (xVal - meanX.getOrThrow()) * (xVal - meanX.getOrThrow())
            sumYSq += (yVal - meanY.getOrThrow()) * (yVal - meanY.getOrThrow())
        }
        let denominator = sqrt(sumXSq) * sqrt(sumYSq)
        if (denominator == 0.0) {
            return Some<Float64>(0.0)
        }
        return Some<Float64>(numerator / denominator)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }
        var sum = 0.0
        for (i in 0..data.size) {
            sum += data[i]?.toFloat64() ?? 0.0
        }
        return Some<Float64>(sum / data.size.toFloat64())
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        if (data.size == 0 || data[0]?.size ?? 0 == 0) {
            return ArrayList<ArrayList<Float64>>()
        }
        let n = data.size
        let m = data[0]?.size ?? 0
        var matrix = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            var row = ArrayList<Float64>()
            for (j in 0..n) {
                if (i == j) {
                    row.add(1.0)
                } else {
                    let corr = correlation(data[i] ?? ArrayList<Int64>(), data[j] ?? ArrayList<Int64>())
                    row.add(corr.getOrThrow())
                }
            }
            matrix.add(row)
        }
        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanVal = mean(data)
        if (meanVal is None<Float64>()) {
            return None<Float64>()
        }
        let m = meanVal.getOrThrow()
        var sum = 0.0
        for (i in 0..data.size) {
            let diff = (data[i]?.toFloat64() ?? 0.0) - m
            sum += diff * diff
        }
        return Some<Float64>(sqrt(sum / data.size.toFloat64()))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanVal = mean(data)
        let stdDev = standard_deviation(data)
        if (meanVal is None<Float64>() || stdDev is None<Float64>()) {
            return None<ArrayList<Float64>>()
        }
        if (stdDev.getOrThrow() == 0.0) {
            return None<ArrayList<Float64>>()
        }
        let m = meanVal.getOrThrow()
        let s = stdDev.getOrThrow()
        var result = ArrayList<Float64>()
        for (i in 0..data.size) {
            let z = (data[i]?.toFloat64() ?? 0.0 - m) / s
            result.add(z)
        }
        return Some<ArrayList<Float64>>(result)
    }
}

import std.collection.ArrayList
