class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequencyMap = HashMap<Int64, Int64>()
        for (num in data) {
            if (frequencyMap.contains(num)) {
                let count = frequencyMap[num] ?? 0
                frequencyMap[num] = count + 1
            } else {
                frequencyMap[num] = 1
            }
        }

        var maxCount = 0
        let result = ArrayList<Int64>()
        for (entry in frequencyMap) {
            if (entry.value > maxCount) {
                maxCount = entry.value
                result.clear()
                result.add(entry.key)
            } else if (entry.value == maxCount) {
                result.add(entry.key)
            }
        }
        return result
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>()
        }

        let meanX = mean(x) ?? return None<Float64>()
        let meanY = mean(y) ?? return None<Float64>()

        var numerator: Float64 = 0.0
        var denominatorX: Float64 = 0.0
        var denominatorY: Float64 = 0.0

        for (i in 0..x.size) {
            let diffX = Float64(x[i]) - meanX
            let diffY = Float64(y[i]) - meanY
            numerator += diffX * diffY
            denominatorX += pow(diffX, 2)
            denominatorY += pow(diffY, 2)
        }

        if (denominatorX == 0.0 || denominatorY == 0.0) {
            return None<Float64>()
        }

        return Some<Float64>(numerator / sqrt(denominatorX * denominatorY))
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>()
        }
        var sum: Int64 = 0
        for (num in data) {
            sum += num
        }
        return Some<Float64>(Float64(sum) / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let n = data.size
        let matrix = ArrayList<ArrayList<Float64>>()

        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                row.add(0.0)
            }
            matrix.add(row)
        }

        for (i in 0..n) {
            for (j in i..n) {
                if (i == j) {
                    matrix[i][j] = 1.0
                } else {
                    let corr = correlation(data[i], data[j]) ?? 0.0
                    matrix[i][j] = corr
                    matrix[j][i] = corr
                }
            }
        }

        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data) ?? return None<Float64>()
        var sum: Float64 = 0.0

        for (num in data) {
            let diff = Float64(num) - m
            sum += pow(diff, 2)
        }

        let variance = sum / Float64(data.size)
        return Some<Float64>(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data) ?? return None<ArrayList<Float64>>()
        let std = standard_deviation(data) ?? return None<ArrayList<Float64>>()

        if (std == 0.0) {
            return None<ArrayList<Float64>>()
        }

        let result = ArrayList<Float64>()
        for (num in data) {
            result.add((Float64(num) - m) / std)
        }
        return Some<ArrayList<Float64>>(result)
    }
}

