        for (_ in 0..N) {  // Fixed range to use N (3x3 board)
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        // Check if position is valid and empty
        if (row < 0 || row >= this.board.size || col < 0 || col >= this.board[0].size) {
            return false
        }
        if (this.board[row][col] != ' ') {
            return false
        }

        // Make the move
        this.board[row][col] = this.current_player
        // Switch player
        this.current_player = if (this.current_player == 'X') { 'O' } else { 'X' }
        return true
    }

    public func check_winner(): Option<String> {
        let N = this.board.size

        // Check rows
        for (i in 0..N) {
            var row_match = true
            if (this.board[i][0] != ' ') {
                for (j in 1..N) {
                    if (this.board[i][j] != this.board[i][0]) {
                        row_match = false
                        break
                    }
                }
                if (row_match) {
                    return Some<String>(this.board[i][0])
                }
            }
        }

        // Check columns
        for (j in 0..N) {
            var col_match = true
            if (this.board[0][j] != ' ') {
                for (i in 1..N) {
                    if (this.board[i][j] != this.board[0][j]) {
                        col_match = false
                        break
                    }
                }
                if (col_match) {
                    return Some<String>(this.board[0][j])
                }
            }
        }

        // Check main diagonal
        var diag1_match = true
        if (this.board[0][0] != ' ') {
            for (i in 1..N) {
                if (this.board[i][i] != this.board[0][0]) {
                    diag1_match = false
                    break
                }
            }
            if (diag1_match) {
                return Some<String>(this.board[0][0])
            }
        }

        // Check anti-diagonal
        var diag2_match = true
        if (this.board[0][N-1] != ' ') {
            for (i in 1..N) {
                if (this.board[i][N-1-i] != this.board[0][N-1]) {
                    diag2_match = false
                    break
                }
            }
            if (diag2_match) {
                return Some<String>(this.board[0][N-1])
            }
        }

        return None<String>()
    }

    public func is_board_full(): Bool {
        for (i in 0..this.board.size) {
            for (j in 0..this.board[0].size) {
                if (this.board[i][j] == ' ') {
                    return false
                }
            }
        }
        return true
    }
}

