        // Assuming format "yyyy-MM-dd HH:mm:ss" based on docstring examples
        let parts = string.split(" ")
        let date_parts = parts[0].split("-")
        let time_parts = parts[1].split(":")
        return DateTime(
            year: date_parts[0].toInt64(),
            month: date_parts[1].toInt64(),
            day: date_parts[2].toInt64(),
            hour: time_parts[0].toInt64(),
            minute: time_parts[1].toInt64(),
            second: time_parts[2].toInt64()
        )
