    }

    public func get_current_time(): String {
        let now = DateTime.now()
        return "${now.hour}:${now.minute.toString(2)}:${now.second.toString(2)}"
    }

    public func get_current_date(): String {
        let now = DateTime.now()
        return "${now.year}-${now.month.toString(2)}-${now.day.toString(2)}"
    }

    public func add_seconds(seconds: Int64): String {
        let new_time = this.datetime.addSeconds(seconds)
        return "${new_time.hour}:${new_time.minute.toString(2)}:${new_time.second.toString(2)}"
    }

    public func string_to_datetime(string: String): DateTime {
        // Assuming the format is "yyyy-MM-dd HH:mm:ss"
        let parts = string.split(" ")
        let date_parts = parts[0].split("-")
        let time_parts = parts[1].split(":")

        let year = date_parts[0].toInt64()!
        let month = date_parts[1].toInt64()!
        let day = date_parts[2].toInt64()!

        let hour = time_parts[0].toInt64()!
        let minute = time_parts[1].toInt64()!
        let second = time_parts[2].toInt64()!

        return DateTime(year: year, month: month, day: day, 
                       hour: hour, minute: minute, second: second)
    }

    public func datetime_to_string(datetime: DateTime): String {
        return "${datetime.year}-${datetime.month.toString(2)}-${datetime.day.toString(2)} ${datetime.hour}:${datetime.minute.toString(2)}:${datetime.second.toString(2)}"
    }

    public func get_minutes(string_time1: String, string_time2: String): Int64 {
        let dt1 = this.string_to_datetime(string_time1)
        let dt2 = this.string_to_datetime(string_time2)
        let diff_seconds = dt2.timestamp - dt1.timestamp
        let diff_minutes = round(diff_seconds / 60.0)
        return diff_minutes.toInt64()
    }

    public func get_format_time(year: Int64, month: Int64, day: Int64, hour: Int64, minute: Int64, second: Int64): String {
        return "${year}-${month.toString(2)}-${day.toString(2)} ${hour}:${minute.toString(2)}:${second.toString(2)}"
    }
}

