import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs
import std.math.pow

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        // Convert degrees to radians for Taylor series (Taylor series uses radians)
        let radians = x * PI / 180.0
        return taylor(radians, 50)
    }

    public func factorial(a: Int64): Decimal {
        if (a <= 1) {
            return Decimal(1)
        }
        var result: Decimal = Decimal(1)
        for (i in 2..a+1) {
            result = result * Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var result: Float64 = 0.0
        // Taylor series for cos(x) = Σ (-1)^i * x^(2i) / (2i)! from i=0 to n
        for (i in 0..n) {
            let sign: Int64 = if (i % 2 == 0) { 1 } else { -1 }
            let power: Float64 = pow(x, 2.0 * Float64(i))
            let fact: Decimal = factorial(2 * i)
            let term: Float64 = Float64(sign) * Float64(power) / Float64(fact)
            result = result + term
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        // Convert degrees to radians for Taylor series
        let radians = x * PI / 180.0
        var result: Float64 = 0.0
        // Taylor series for sin(x) = Σ (-1)^i * x^(2i+1) / (2i+1)! from i=0 to n
        for (i in 0..50) {
            let sign: Int64 = if (i % 2 == 0) { 1 } else { -1 }
            let power: Float64 = pow(radians, 2.0 * Float64(i) + 1.0)
            let fact: Decimal = factorial(2 * i + 1)
            let term: Float64 = Float64(sign) * Float64(power) / Float64(fact)
            result = result + term
        }
        return result
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = cos(x)
        let threshold: Float64 = 0.000001
        if (abs(cos_val - 0.0) < threshold) {
            return None<Float64>()
        }
        let sin_val = sin(x)
        return Some<Float64>(sin_val / cos_val)
    }
}

