        for (i in 0..n) {
            let sign = if (i % 2 == 0) { 1.0 } else { -1.0 }
            let numerator = this.powInt(x, 2 * i)
            let denominator = Decimal(this.factorial(2 * i)).toFloat64()
            sum += sign * numerator / denominator
        }
        return sum
    }

    private func powInt(base: Float64, exponent: Int64): Float64 {
        var result: Float64 = 1.0
        for (i in 0..exponent) {
            result *= base
        }
        return result
    }

