        // Convert angle to radians and adjust to 0-360 range
        let rad = (x % 360.0) * this.PI / 180.0
        // Use cosine shift property: sin(x) = cos(x - 90°)
        let shifted = (rad - this.PI / 2.0)
        // Handle negative angles by adding 2*PI
        let adjusted = if (shifted < 0.0) { shifted + 2.0 * this.PI } else { shifted }
        return this.taylor(adjusted, 50)
    }

