        var sum: Float64 = 0.0
        for (i in 0..(n+1)) {
            let numerator: Float64 = (if (i % 2 == 0) { 1.0 }  else { -1.0 }) * pow(x, Float64(2 * i))
            let denominator: Decimal = factorial(a: Int64(2 * i))
            sum = sum + Float64(numerator / Float64(denominator))
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
        // Convert angle to radians and use Taylor series with offset by pi/2
        let radians = (x / 180.0) * PI
        // Using sin(x) = cos(x - pi/2)
        let adjusted = radians - (PI / 2.0)
        // For better approximation, we'll implement sin's Taylor series directly
        // Alternatively could use cos with phase shift, but here's direct implementation:
        var sum: Float64 = 0.0
        let n = 50
        for (i in 0..(n+1)) {
            let term = (if (i % 2 == 0) { 1.0 }  else { -1.0 }) * pow(radians, Float64(2 * i + 1)) / Float64(factorial(a: Int64(2 * i + 1)))
            sum = sum + term
        }
        return sum
    }

