        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        /*
        Finding the n-order Taylor expansion value of cos (x)
        :param x: Float64
        :param n: Int64
        :return: Float64
        >>> tricalculator.taylor(60.0 * 3.1415926 / 180.0, 50)
