    public func cos(x: Float64): Float64 {
        // Convert degrees to radians and adjust x to range [-pi, pi]
        let adj_x = (x / 180.0 * PI) % (2.0 * PI)
        let final_x = if (adj_x > PI) { adj_x - 2.0 * PI } else { adj_x }
        let n = 20 // Accuracy control
        return this.taylor(final_x, n)
    }

    public func factorial(a: Int64): Decimal {
        var result: Decimal = Decimal(1)
        for (i in 1..a+1) {
            result = result * Decimal(i)
        }
        return result
    }

