        var sum: Float64 = 0.0
        for (i in 0..n) {
            let numerator: Float64 = if (i % 2 == 0) { 1.0 } else { -1.0 }
            let power = Float64(2 * i)
            let fact = Decimal::fromFloat64((power + 1) / 2).toFloat64()
            let denominator = this.factorial(Int64(fact))
            sum = sum + numerator * (x.pow(power) / denominator.toFloat64())
        }
        return sum
    }

    public func sin(x: Float64): Float64 {
