        let shifted_x = final_x + PI / 2.0
        let n = 20 // Accuracy control
        let cos_shifted = this.taylor(shifted_x, n)
        return if (abs(shifted_x % (2.0 * PI) - PI / 2.0) > PI/2 + 0.000001) { -cos_shifted } else { cos_shifted }
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = this.cos(x)
        if (abs(cos_val) < 0.000001) {
            return None<Float64>()
        } else {
            let sin_val = this.sin(x)
