    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let doubleSlashIndex = url.indexOf("//")
        if (doubleSlashIndex == -1) {
            return None<String>
        }
        let schemeEnd = doubleSlashIndex
        let schemeStr = url.substring(0, schemeEnd)
        let colonIndex = schemeStr.lastIndexOf(":")
        if (colonIndex == -1) {
            return None<String>
        }
        return Some<String>(schemeStr.substring(0, colonIndex))
    }

    public func get_host(): Option<String> {
        let doubleSlashIndex = url.indexOf("//")
        if (doubleSlashIndex == -1) {
            return None<String>
        }
        let hostStart = doubleSlashIndex + 2
        let pathIndex = url.indexOf("/", hostStart)
        let fragmentIndex = url.indexOf("#", hostStart)

        var endIndex = -1
        if (pathIndex != -1 && fragmentIndex != -1) {
            endIndex = min(pathIndex, fragmentIndex)
        } else if (pathIndex != -1) {
            endIndex = pathIndex
        } else if (fragmentIndex != -1) {
            endIndex = fragmentIndex
        }

        if (endIndex == -1) {
            return Some<String>(url.substring(hostStart))
        } else {
            return Some<String>(url.substring(hostStart, endIndex))
        }
    }

    public func get_path(): Option<String> {
        let doubleSlashIndex = url.indexOf("//")
        if (doubleSlashIndex == -1) {
            return None<String>
        }
        let hostEnd = get_host()?.getOrThrow().size + (doubleSlashIndex + 2) ?? 0
        let fragmentIndex = url.indexOf("#", hostEnd)

        var endIndex = -1
        if (fragmentIndex != -1) {
            endIndex = fragmentIndex
        }

        if (endIndex == -1) {
            return Some<String>(url.substring(hostEnd))
        } else {
            return Some<String>(url.substring(hostEnd, endIndex))
        }
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let pathPart = get_path()?.getOrThrow() ?? ""
        let questionIndex = pathPart.indexOf("?")
        if (questionIndex == -1) {
            return Some<HashMap<String, String>>(HashMap<String, String>([]))
        }

        let queryStr = pathPart.substring(questionIndex + 1)
        let params = HashMap<String, String>([])

        let keyValuePairs = queryStr.split("&")
        for (pair in keyValuePairs) {
            let equalIndex = pair.indexOf("=")
            if (equalIndex != -1) {
                let key = pair.substring(0, equalIndex)
                let value = pair.substring(equalIndex + 1)
                params.add(key, value)
            }
        }

        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        let fragmentIndex = url.indexOf("#")
        if (fragmentIndex == -1) {
            return None<String>
        }
        return Some<String>(url.substring(fragmentIndex + 1))
    }
}

