                end
            }
            case None<String> => return None<String>()
        }
        var hostEnd = schemeEnd
        while (hostEnd < url.size && 
               url[hostEnd] != r'/' && 
               url[hostEnd] != r'?' && 
               url[hostEnd] != r'#') {
            hostEnd += 1
        }
        if (hostEnd == schemeEnd) {
            return None<String>()
        }
        let slice = url.substring(schemeEnd, hostEnd - schemeEnd)
        return Some<String>(slice)
    }

