                    case None<String> => 0
                }
                url.indexOf(r'/', start: hostStart + host.size)!
            }
            case None<String> => {
                let schemeEnd = match (get_scheme()) {
                    case Some<String>(s) => s.size + 3
                    case None<String> => 0
                }
                url.indexOf(r'/', start: schemeEnd) ?? url.size
            }
        }
        var pathEnd = hostEnd
        while (pathEnd < url.size && url[pathEnd] != r'?' && url[pathEnd] != r'#') {
            pathEnd += 1
        }
        if (pathEnd == hostEnd) {
            if (hostEnd < url.size && url[hostEnd] == r'/') {
                let slice = url.substring(hostEnd, 1)
                return Some<String>(slice)
            }
            return None<String>()
        }
        let slice = url.substring(hostEnd, pathEnd - hostEnd)
        return Some<String>(slice)
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let pathEnd = match (get_path()) {
            case Some<String>(p) => {
