                            case Some<String>(s) => s.size + 3
                            case None<String> => 0
                        }
                        schemeEnd + h.size
                    }
                    case None<String> => {
                        let schemeEnd = match (get_scheme()) {
                            case Some<String>(s) => s.size + 3
                            case None<String> => 0
                        }
                        schemeEnd
                    }
                }
                url.indexOf(r'/', start: start) ?? start
            }
            case None<String> => {
                let hostEnd = match (get_host()) {
                    case Some<String>(h) => {
                        let schemeEnd = match (get_scheme()) {
                            case Some<String>(s) => s.size + 3
                            case None<String> => 0
                        }
                        schemeEnd + h.size
                    }
                    case None<String> => 0
                }
                hostEnd
            }
        }
        let queryStart = match (url.indexOf(r'?', start: pathEnd)) {
            case Some<Int64>(index) => index + 1
            case None<Int64> => return None<HashMap<String, String>>()
        }
        let fragmentStart = match (url.indexOf(r'#', start: queryStart)) {
            case Some<Int64>(index) => index
            case None<Int64> => url.size
        }
        if (queryStart >= fragmentStart) {
            return None<HashMap<String, String>>()
        }
        let queryStr = url.substring(queryStart, fragmentStart - queryStart)
        let params = HashMap<String, String>()
        let pairs = queryStr.split(r'&')
        for (pair in pairs) {
            let kv = pair.split(r'=')
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            }
        }
        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        let fragmentStart = match (url.indexOf(r'#')) {
            case Some<Int64>(index) => index + 1
            case None<Int64> => return None<String>()
        }
        if (fragmentStart >= url.size) {
            return None<String>()
        }
        let slice = url.substring(fragmentStart, url.size - fragmentStart)
        return Some<String>(slice)
    }
