    }

    public func get_scheme(): Option<String> {
        let parts = this.url.split("://")
        if (parts.size >= 2) {
            Some<String>(parts[0])
        } else {
            None<String>
        }
    }

    public func get_host(): Option<String> {
        let scheme_end = this.url.indexOf("://")
        if (scheme_end == -1) {
            return None<String>
        }

        let after_scheme = this.url.substring(scheme_end + 3)
        let slash_pos = after_scheme.indexOf("/")

        if (slash_pos == -1) {
            let end_pos = this.url.indexOf("?")
            if (end_pos == -1) {
                end_pos = this.url.indexOf("#")
                if (end_pos == -1) {
                    return Some<String>(after_scheme)
                }
            }
            return Some<String>(after_scheme.substring(0, end_pos))
        } else {
            let end_pos = min(
                after_scheme.indexOf("?"), 
                min(after_scheme.indexOf("#"), slash_pos)
            )
            if (end_pos == -1 || end_pos >= slash_pos) {
                return Some<String>(after_scheme.substring(0, slash_pos))
            } else {
                return Some<String>(after_scheme.substring(0, end_pos))
            }
        }
    }

    public func get_path(): Option<String> {
        let scheme_end = this.url.indexOf("://")
        if (scheme_end == -1) {
            return None<String>
        }

        let after_scheme = this.url.substring(scheme_end + 3)
        let host_end = match (this.get_host()) {
            case Some<String>(host) => 
                let host_str = host
                let host_len = host_str.size
                scheme_end + 3 + host_len + (if (after_scheme[host_len] == '/') { 0 } else { 1 }) // crude estimate
            case _ => return None<String>
        }

        // Simpler approach: find first ? or # after host
        let after_host = after_scheme.substring(
            this.get_host() ?? "").size
        let query_pos = this.url.indexOf("?", scheme_end + 3 + after_host)
        let frag_pos = this.url.indexOf("#", scheme_end + 3 + after_host)

        let start_pos = scheme_end + 3 + (this.get_host() ?? "").size
        if (query_pos == -1 && frag_pos == -1) {
            return Some<String>(this.url.substring(start_pos))
        } else {
            let end_pos = min(
                if (query_pos == -1) { Int64.MAX_VALUE } else { query_pos },
                if (frag_pos == -1) { Int64.MAX_VALUE } else { frag_pos }
            )
            return Some<String>(this.url.substring(start_pos, end_pos))
        }
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let frag_pos = this.url.indexOf("#")
        let query_str = if (frag_pos == -1) {
            let q_pos = this.url.indexOf("?")
            if (q_pos == -1) {
                return None<HashMap<String, String>>
            }
            this.url.substring(q_pos + 1)
        } else {
            let q_pos = this.url.indexOf("?", 0, frag_pos)
            if (q_pos == -1) {
                return None<HashMap<String, String>>
            }
            this.url.substring(q_pos + 1, frag_pos)
        }

        let params = HashMap<String, String>()
        let pairs = query_str.split("&")

        for (pair in pairs) {
            let kv = pair.split("=")
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            }
        }

        Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        let frag_pos = this.url.indexOf("#")
        if (frag_pos == -1) {
            None<String>
        } else {
            Some<String>(this.url.substring(frag_pos + 1))
        }
    }
}

