class UrlPath {

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        this.segments.add(segment)
    }

    public func parse(path: String): Unit {
        let fixed_path = UrlPath.fix_path(path: path)
        this.segments = ArrayList<String>()

        if fixed_path.size == 0 {
            return
        }

        var current_segment = ArrayList<Rune>()
        for (c in fixed_path.runes()) {
            if (c == r'/') {
                if (current_segment.size > 0) {
                    let segment = String.fromRunes(current_segment)
                    this.segments.add(segment)
                    current_segment = ArrayList<Rune>()
                }
            } else {
                current_segment.add(c)
            }
        }

        if (current_segment.size > 0) {
            let segment = String.fromRunes(current_segment)
            this.segments.add(segment)
        }
    }

    public static func fix_path(path: String): String {
        var filtered = ArrayList<Rune>()
        var in_segment = false

        for (c in path.runes()) {
            if (c == r'/') {
                if (in_segment || filtered.size == 0) {
                    if (filtered.size == 0 || filtered[filtered.size - 1] != r'/') {
                        in_segment = false
                        if (filtered.size == 0 || filtered[filtered.size - 1] != r'/') {
                            filtered.add(c)
                        }
                    }
                }
            } else {
                in_segment = true
                filtered.add(c)
            }
        }

        // Clean up trailing slash
        if (filtered.size > 0 && filtered[filtered.size - 1] == r'/') {
            filtered.removeAt(filtered.size - 1)
        }

        // Clean up leading slash if needed (but preserve if it's the only character)
        if (filtered.size > 0 && filtered[0] == r'/' && filtered.size > 1) {
            let temp = ArrayList<Rune>()
            for (i in 1..filtered.size:1) {
                temp.add(filtered[i])
            }
            return String.fromRunes(temp)
        }

        // Alternative simpler implementation:
        // Remove leading/trailing slashes and collapse multiple slashes
        let runes = path.runes().filter { c, i => 
            !(c == r'/' && (
                i == 0 || 
                i == path.runes().size - 1 || 
                path.runes()[i-1] == r'/'
            ))
        }.toArrayList()

        // Join the filtered runes into string
        return String.fromRunes(runes)
    }
}

