// Corrected version with proper string splitting (alternative implementation)
class UrlPathCorrect {
    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        this.segments.add(segment)
    }

    public func parse(path: String): Unit {
        let fixed_path = UrlPathCorrect.fix_path(path: path)
        var current_segment = ""
        var in_segment = false

        for (c in fixed_path.runes()) {
            if (c == r'/') {
                if (in_segment && current_segment != "") {
                    this.segments.add(current_segment)
                    current_segment = ""
                }
                in_segment = false
            } else {
                current_segment += String.fromRune(c)
                in_segment = true
            }
        }
        if (current_segment != "") {
            this.segments.add(current_segment)
        }
        this.with_end_tag = path.endsWith('/')
    }

    public static func fix_path(path: String): String {
        var start = 0
        var end = path.size

        // Remove leading slashes
        while (start < end && path[start] == '/') {
            start += 1
        }

        // Remove trailing slashes
        while (end > start && path[end - 1] == '/') {
            end -= 1
        }

        return path.substring(start, end)
    }
}

