class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        if (vector_1.size != vector_2.size) {
            panic("Vectors must have the same dimension")
        }

        var dot_product: Float64 = 0.0
        var magnitude1: Float64 = 0.0
        var magnitude2: Float64 = 0.0

        for (i in 0..vector_1.size) {
            let v1 = vector_1[i]
            let v2 = vector_2[i]
            dot_product += v1 * v2
            magnitude1 += pow(v1, 2)
            magnitude2 += pow(v2, 2)
        }

        let magnitude = sqrt(magnitude1) * sqrt(magnitude2)
        if (magnitude == 0.0) {
            return 0.0
        }
        return dot_product / magnitude
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for (i in 0..vectors_all.size) {
            let vec = vectors_all[i]
            let similarity = VectorUtil.similarity(vector_1, vec)
            result.add(similarity)
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            return 0.0
        }

        // First compute mean vectors
        let mean_vec1 = VectorUtil.mean_vector(vector_list_1)
        let mean_vec2 = VectorUtil.mean_vector(vector_list_2)

