    }

    public static func magnitude(v: ArrayList<Float64>): Float64 {
        var sum: Float64 = 0.0
        for (x in v) {
            sum += pow(x, 2.0)
        }
        return sqrt(sum)
    }

    public static func normalize(v: ArrayList<Float64>): ArrayList<Float64> {
        let mag = magnitude(v)
        let result = ArrayList<Float64>()
        for (x in v) {
            result.add(x / mag)
        }
        return result
    }

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        if (vector_1.size != vector_2.size) {
            panic("Vector dimensions don't match")
        }
        let dot = dot_product(vector_1, vector_2)
        let mag1 = magnitude(vector_1)
        let mag2 = magnitude(vector_2)
        return dot / (mag1 * mag2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let normalized_1 = normalize(vector_1)
        let result = ArrayList<Float64>()
        for (v in vectors_all) {
            let normalized_v = normalize(v)
            result.add(similarity(normalized_1, normalized_v))
        }
        return result
    }

    public static func average_vector(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        if (vectors.size == 0) {
            panic("Empty vector list")
        }
        let dim = vectors[0].size
        let result = ArrayList<Float64>([0.0 : dim])  // Initialize with zeros
        for (v in vectors) {
            for (i in 0..<dim) {
                result[i] += v[i]
            }
        }
        for (i in 0..<dim) {
            result[i] /= vectors.size.toFloat64()
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let avg_1 = average_vector(vector_list_1)
        let avg_2 = average_vector(vector_list_2)
        return similarity(avg_1, avg_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for (key, count in number_dict) {
            let weighted_count = count + 1.0
            let denominator = total_num.toFloat64() + 1.0
            let idf = log(denominator / weighted_count)
            result.add(key, idf)
        }
        return result
    }
}

