        for (i in 0..vectors_all.size) {
            let sim = similarity(vector_1, vectors_all[i])
            results.add(sim)
        }
        return results
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            return 0.0
        }

        var sum_1: Float64 = 0.0
        var sum_2: Float64 = 0.0
        var total: Float64 = 0.0

        for (i in 0..vector_list_1.size) {
            for (j in 0..vector_list_2.size) {
                let sim = similarity(vector_list_1[i], vector_list_2[j])
                sum_1 += sim
                total += 1.0
            }
        }

        let avg_1 = sum_1 / total

        sum_1 = 0.0
        sum_2 = 0.0
        total = 0.0

        for (i in 0..vector_list_1.size) {
            for (j in i+1..vector_list_1.size) {
                let sim = similarity(vector_list_1[i], vector_list_1[j])
                sum_1 += sim
                total += 1.0
            }
        }

        let avg_2 = sum_1 / total

        sum_1 = 0.0
        sum_2 = 0.0
        total = 0.0

        for (i in 0..vector_list_2.size) {
            for (j in i+1..vector_list_2.size) {
                let sim = similarity(vector_list_2[i], vector_list_2[j])
                sum_2 += sim
                total += 1.0
            }
        }

        let avg_3 = sum_2 / total

        return (avg_1 - (avg_2 + avg_3) / 2.0)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        let total_num_plus_1 = total_num + 1.0

        for (entry in number_dict.entries()) {
            let key = entry.key
            let value = entry.value
            let idf = log(total_num_plus_1 / (value + 1.0))
            result.add(key, idf)
        }

        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        if (vector_1.size != vector_2.size) {
            return 0.0
        }

        var dot_product: Float64 = 0.0
        var mag_1: Float64 = 0.0
        var mag_2: Float64 = 0.0

        for (i in 0..vector_1.size) {
            dot_product += vector_1[i] * vector_2[i]
            mag_1 += pow(vector_1[i], 2.0)
            mag_2 += pow(vector_2[i], 2.0)
        }

        mag_1 = sqrt(mag_1)
        mag_2 = sqrt(mag_2)

        if (mag_1 == 0.0 || mag_2 == 0.0) {
            return 0.0
        }

        return dot_product / (mag_1 * mag_2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let results = ArrayList<Float64>()
        for (i in 0..vectors_all.size) {
            results.add(VectorUtil.similarity(vector_1, vectors_all[i]))
        }
        return results
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.size == 0 || vector_list_2.size == 0) {
            return 0.0
        }

        var mag_1: Float64 = 0.0
        var mag_2: Float64 = 0.0
        var dot_product: Float64 = 0.0

        for (i in 0..vector_list_1.size) {
            if (i >= vector_list_2.size) {
                break
            }
            for (j in 0..vector_list_1[i].size) {
                if (j >= vector_list_2[i].size) {
                    break
                }
                dot_product += vector_list_1[i][j] * vector_list_2[i][j]
                mag_1 += pow(vector_list_1[i][j], 2.0)
                mag_2 += pow(vector_list_2[i][j], 2.0)
            }
        }

        mag_1 = sqrt(mag_1)
        mag_2 = sqrt(mag_2)

        if (mag_1 == 0.0 || mag_2 == 0.0) {
            return 0.0
        }

        return dot_product / (mag_1 * mag_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        number_dict.forEach { key: String, value: Float64 =>
            let idf = log((total_num + 1.0) / (value + 1.0))
            result.add(key, idf)
        }
        return result
    }
}

