class VendingMachine {

    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        let product = if (this.inventory.contains(item_name)) {
            let previous = this.inventory.get(item_name).getOrThrow()
            Product(price: previous.price, quantity: previous.quantity + quantity)
        } else {
            Product(price: price, quantity: quantity)
        }
        this.inventory.add(item_name, product)
    }

    public func insert_coin(amount: Float64): Float64 {
        this.balance += amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        if (!this.inventory.contains(item_name)) {
            return None<Float64>()
        }

        let product = this.inventory.get(item_name).getOrThrow()
        if (product.quantity <= 0) {
            return None<Float64>()
        }

        if (this.balance < product.price) {
            return None<Float64>()
        }

        this.balance -= product.price
        this.inventory.add(item_name, 
            Product(price: product.price, quantity: product.quantity - 1))
        return Some<Float64>(this.balance)
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        if (!this.inventory.contains(item_name)) {
            return false
        }

        let product = this.inventory.get(item_name).getOrThrow()
        this.inventory.add(item_name, 
            Product(price: product.price, quantity: product.quantity + quantity))
        return true
    }

    public func display_items(): Option<String> {
        if (this.inventory.size == 0) {
            return None<String>()
        }

        var result = ArrayList<String>()
        for (item in this.inventory.keys) {
