class WeatherSystem {
    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = "celsius"): Option<(Float64, String)> {
        let weather = weather_list.get(this.city)
        match (weather) {
            case None<Weather> => return None<(Float64, String)>()
            case Some<Weather>(w) => {
                let temp = w.temperature
                let unit = w.temperature_units
                if (tmp_units == "celsius" && unit == "fahrenheit") {
                    return Some<(Float64, String)>(
                        (this.fahrenheit_to_celsius_value(temp), w.weather)
                    )
                } else if (tmp_units == "fahrenheit" && unit == "celsius") {
                    return Some<(Float64, String)>(
                        (this.celsius_to_fahrenheit_value(temp), w.weather)
                    )
                }
                return Some<(Float64, String)>(
                    (w.temperature, w.weather)
                )
            }
        }
    }

    private func celsius_to_fahrenheit_value(c: Float64): Float64 {
        return c * 9.0 / 5.0 + 32.0
    }

    private func fahrenheit_to_celsius_value(f: Float64): Float64 {
        return (f - 32.0) * 5.0 / 9.0
    }

    public func set_city(city: String): Unit {
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        if (this.temperature_is_nan()) {
            return Float64.NaN
        }
        return this.celsius_to_fahrenheit_value(this.temperature)
    }

    public func fahrenheit_to_celsius(): Float64 {
        if (this.temperature_is_nan()) {
            return Float64.NaN
        }
        return this.fahrenheit_to_celsius_value(this.temperature)
    }

    private func temperature_is_nan(): Bool {
        return this.temperature.isNaN()
    }
}

