class Words2Numbers {

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        // Initialize numwords with base values
        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            this.numwords[this.units[idx]] = (1, idx)
        }
        for (idx in 0..this.tens.size) {
            this.numwords[this.tens[idx]] = (1, idx * 10)
        }
        for (idx in 0..this.scales.size) {
            if (idx == 0) {
                this.numwords[this.scales[idx]] = (100, 0)
            } else {
                this.numwords[this.scales[idx]] = (Int64(10 ** (idx * 3)), 0)
            }
        }

        // Initialize ordinal words
        this.ordinal_words = HashMap<String, Int64>([("first", 1), ("second", 2), ("third", 3), ("fifth", 5), ("eighth", 8), ("ninth", 9), ("twelfth", 12)])
        this.ordinal_endings = ArrayList<(String, String)>([("ieth", "y"), ("th", "")])
    }

    public func text2int(textnum: String): String {
        let parts = textnum.split("-")
        var current: Int64 = 0
        var result: Int64 = 0

        for (part in parts) {
            if (this.numwords.contains(part)) {
                let (scale, value) = this.numwords[part] ?? (1, 0)
                current = current * scale + value
            } else {
                // Handle ordinal numbers
                var matched = false
                for (idx in 0..this.ordinal_words.size) {
                    if (let entry = this.ordinal_words.get(this.ordinal_words.keys[idx])) {
                        if (part == this.ordinal_words.keys[idx]) {
                            current = current * 1 + entry
                            matched = true
                            break
                        }
                    }
                }

                if (!matched) {
                    // Check for ordinal endings (simple implementation)
                    var modified_part = part
                    for (ending, replacement) in this.ordinal_endings {
                        if (modified_part.endsWith(ending)) {
                            modified_part = modified_part[0..modified_part.size - ending.size] + replacement
                            if (this.numwords.contains(modified_part)) {
                                let (scale, value) = this.numwords[modified_part] ?? (1, 0)
                                current = current * scale + value
                                matched = true
                                break
                            }
                        }
                    }

                    if (!matched) {
                        return "0" // or handle error appropriately
                    }
                }
            }

            // Handle scale words (hundred, thousand, etc.)
            // This is simplified - a more complete implementation would need better parsing
            if (this.scales.contains(part)) {
                let (scale, _) = this.numwords[part] ?? (1, 0)
                if (scale != 1 && scale != 100) { // thousand, million, etc.
                    result = result + current
                    current = 0
                }
            }
        }

        result = result + current
        return result.toString()
    }

    public func is_valid_input(textnum: String): Bool {
        let parts = textnum.split("-")
        var valid = true

        for (part in parts) {
            if (this.numwords.contains(part)) {
                continue
            }

            // Check ordinal words
            var matched = false
            for (idx in 0..this.ordinal_words.size) {
                if (let entry = this.ordinal_words.get(this.ordinal_words.keys[idx])) {
                    if (part == this.ordinal_words.keys[idx]) {
                        matched = true
                        break
                    }
                }
            }

            if (!matched) {
                // Check for ordinal endings (simple implementation)
                var modified_part = part
                for (ending, _) in this.ordinal_endings {
                    if (modified_part.endsWith(ending)) {
                        modified_part = modified_part[0..modified_part.size - ending.size]
                        if (this.numwords.contains(modified_part)) {
                            matched = true
                            break
                        }
                    }
                }
            }

            if (!matched) {
                valid = false
                break
            }
        }

        return valid
    }
}

